INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C1','kor',6,2,'u2',2,'면담의 뜻과 특성 — 면담은 정보를 얻으려고 면담 대상자와 주고받는 대화이고, 정보·준비·예의가 함께 있어야 하며, 찾으면 나오는 것이 아니라 그분이 겪은 일과 생각처럼 면담이라야 들을 수 있는 것을 얻는다(일상 대화와 다름: 목적·차례·답하는 쪽이 더 많이 말함)',ARRAY['[6국01-04]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C2','kor',6,2,'u2',2,'면담 요청하기와 물어서는 안 되는 것 — 직접·전화·전자 우편·누리집 등 어느 방법이든 먼저 허락을 구하고, 우리가 누구인지·목적·걸리는 시간·바라는 날짜와 장소를 밝혀 대상자의 사정에 맞추어 정하며, 사는 곳·나이·가족·버는 돈 같은 개인 정보와 곤란한 물음은 덜어 내기',ARRAY['[6국01-04]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C3','kor',6,2,'u2',3,'면담의 절차 — 면담 준비하기(모둠·목적·대상자·방식·자료·질문·역할·요청과 허락, 목적이 맨 먼저) → 면담 진행하기(면담 열기·질문하기·면담 마무리하기) → 면담 정리하기(내용 정리·과정 성찰·보고서 쓰기), 면담은 들은 것을 쓸 수 있게 남길 때 끝남',ARRAY['[6국01-04]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C4','kor',6,2,'u2',3,'질문 세 갈래와 목적에 맞는 질문 — 구체적인 사실·생각이나 느낌·앞으로의 계획이나 당부에 대한 질문을 골고루 만들고, 면담 목적과 이어지지 않는 질문은 덜어 내며, 미리 찾은 자료를 바탕으로 더 깊이 묻기',ARRAY['[6국01-03][6국01-04]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C5','kor',6,2,'u2',5,'면담 자료 읽기와 후속 질문 — 면담 자료에서 열기·질문하기·마무리 단계를 짚어 읽고, 답을 끝까지 듣고 그 안의 말을 붙들어 더 자세히 알려고 이어서 묻는 후속 질문을 하기(질문지는 지도이지 대본이 아님)',ARRAY['[6국01-03][6국01-04]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C6','kor',6,2,'u2',5,'면담 예절과 질문 점검 — 인사·감사·목적 밝히기·동의 구하기, 말씀 도중에 끊지 않고 질문은 짧게, 고개를 끄덕이며 듣기, 만든 질문을 목적에 맞는가·예의를 갖추었는가·뜻이 분명한가로 점검하고, 자료는 누가·언제 만들었는지 밝혀진 믿을 만한 출처에서 찾기',ARRAY['[6국01-03][6국01-04]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C7','kor',6,2,'u2',7,'매체를 고려하여 면담하기 — 매체는 소통을 이어 주는 도구와 환경이고 절차마다 쓰임이 다르며(준비 — 누리집·책, 진행 — 녹음기·영상 통화, 정리 — 다시 들으며 간추리기), 대면·비대면을 대상자의 사정에 맞추어 정하고, 담기 전에 허락받아 보고서에만 쓰고 밖으로 내보내지 않기',ARRAY['[6국01-04]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C8','kor',6,2,'u2',7,'모둠 역할과 면담 내용 간추리기 — 진행·약속·질문·매체·정리 담당이 하는 일을 알고, 면담 내용을 삭제·대체·선택·구성으로 간추려 내 말로 다시 세우되 답변의 뜻은 바꾸지 않기(통째 옮기기·뭉뚱그리기 피하기)',ARRAY['[6국01-04]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C9','kor',6,2,'u2',9,'면담 성찰과 면담 보고서 — 잘한 점·보완할 점·더 알고 싶은 점(+ 다음 면담에서 실천할 점)으로 절차마다 되돌아보되 사람 탓이 아니라 다음 약속으로 바꾸고, 보고서를 앞부분(목적·대상자·준비)·가운데 부분(새롭게 안 사실을 갈래로)·뒷부분(깨달은 점·달라진 생각)으로 쓰고 알려도 되는 것만 나누기',ARRAY['[6국01-04]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C10','kor',6,2,'u2',11,'작품 속 인물과 면담하기와 바람직한 질문 — 인물에게 세 갈래로 묻고, 인물이 되어 답할 때는 작품 속 사건·말·행동만 근거로 하며(없으면 「이야기에 나오지 않습니다」), 모자란 곳을 파고들거나 억지로 답하게 하는 불쾌한 질문을 상대의 마음을 헤아리는 바람직한 질문으로 고치기',ARRAY['[6국01-03][6국01-04]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C11','kor',6,2,'u2',11,'겹받침의 발음 — 받침에 자음이 두 개 있는 겹받침은 낱말 하나로 있을 때 하나만 소리 나고(맑다[막따]·넓다[널따]), 뒤에 모음으로 시작하는 말이 붙으면 앞 자음은 받침으로 남고 뒤 자음이 넘어가 소리 남(맑아[말가]·넓은[널븐])(기초 다지기)',ARRAY['기초 다지기 겹받침 발음(성취기준 표기 없음)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C12','kor',6,2,'u2',3,'「윤서네 모둠의 면담」 내용 알기 — 학급 신문 진로 상담 칸에 도서관 사서라는 직업을 알리는 글을 쓰려고 공공 도서관 사서와 대면 면담 · 면담 개요(열기·질문 ㉠~㉥·마무리) · 사서가 하는 일(대출·반납, 책 주문·정리, 독서 행사) · 되는 과정(문헌정보학·자격증·채용) · 능력(소통·검색·꼼꼼함)',ARRAY['[6국01-03][6국01-04]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C13','kor',6,2,'u2',5,'「로봇 공학자와의 면담」 내용 알기 — 로봇 공학자가 하는 일과 되기 위해 필요한 태도를 알아보려는 면담 · 가장 먼저 로봇이 풀 문제를 정함 → 설계·부품·프로그램·여러 번 시험(후속 질문) · 보람 · 목표 · 기술과 함께 생활에 주는 영향을 판단하는 태도',ARRAY['[6국01-03][6국01-04]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C14','kor',6,2,'u2',7,'민수네 모둠과 상담 선생님의 면담 — 상담 교사가 되는 방법과 역할을 알아보려고 연락할 수 있는 박○○ 상담 선생님과 대면 면담 · 매체로 찾은 자료(누리집·책·신문) · 역할 다섯 · 열기(감사·목적·녹화 동의)·질문 ㉠~㉥·마무리(알게 된 것 확인·감사 인사)',ARRAY['[6국01-03][6국01-04]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C15','kor',6,2,'u2',9,'「상담 교사, 마음의 길을 밝히는 사람들」 내용 알기 — 하늘 모둠의 면담 보고서: 앞부분(목적·대상자·역할과 준비) · 가운데 부분(새롭게 안 사실 넷: 되는 과정·하는 일·힘든 점·보람과 전망) · 뒷부분(공감 능력과 끈기, 역할 존중, 달라진 생각)',ARRAY['[6국01-04]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X01','kor',6,'u2',ARRAY['K6-2-u2-C1']::text[],'면담을 친해지려고 나누는 일상 대화나 누가 옳은지 가리는 겨루기로 여긴다','「무엇을 알고 싶어서 만나나?」 — 목적이 있는 대화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X02','kor',6,'u2',ARRAY['K6-2-u2-C1','K6-2-u2-C4','K6-2-u2-C5']::text[],'찾아보면 나오는 것(사전 뜻·수·기록)을 면담에서 묻거나, 면담을 검색을 사람으로 바꾼 일로 여긴다','그분이 아니면 답할 수 없는 물음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X03','kor',6,'u2',ARRAY['K6-2-u2-C2']::text[],'면담을 요청할 때 누구인지·목적·시간·날짜를 빠뜨리거나, 날짜를 정해 통보하고 허락을 구하지 않는다','누구 · 왜 · 얼마나 · 언제가 괜찮으신지 — 여쭈어 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X04','kor',6,'u2',ARRAY['K6-2-u2-C2','K6-2-u2-C9']::text[],'궁금하면 사는 곳·나이·가족·버는 돈 같은 개인 정보도 묻거나 보고서에 적어도 된다고 여긴다','「이 질문을 내가 받으면 어떨까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X05','kor',6,'u2',ARRAY['K6-2-u2-C3']::text[],'면담의 절차(준비·진행·정리)나 진행 단계(열기·질문하기·마무리)의 차례와 할 일을 섞는다(목적보다 날짜·역할을 먼저 정하기 등)','만나기 전 · 만나는 동안 · 만난 뒤로 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X06','kor',6,'u2',ARRAY['K6-2-u2-C3','K6-2-u2-C5']::text[],'질문지를 대본처럼 차례대로 읽기만 하고 답을 끝까지 듣지 않아 후속 질문을 하지 못한다','질문지는 지도 — 답 속의 말을 붙들어 이어서 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X07','kor',6,'u2',ARRAY['K6-2-u2-C3','K6-2-u2-C4','K6-2-u2-C5']::text[],'준비 없이 떠오르는 대로 묻거나 면담 목적에서 벗어난 질문을 한다','목적과 하나씩 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X08','kor',6,'u2',ARRAY['K6-2-u2-C4','K6-2-u2-C10']::text[],'질문의 세 갈래(사실·생각이나 느낌·계획이나 당부)를 헷갈리거나 사실만 묻는다','있었던 일? 마음? 앞일과 당부?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X09','kor',6,'u2',ARRAY['K6-2-u2-C4','K6-2-u2-C6']::text[],'자료를 재미·사진·검색 순서로 고르고 누가·언제 만들었는지 출처를 확인하지 않는다','누가 만들었나 · 언제 만들었나 · 목적과 이어지나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X10','kor',6,'u2',ARRAY['K6-2-u2-C6']::text[],'면담 예절을 놓친다(말씀 도중에 끊기·다시 답하게 하기·길게 묻기·감사 인사 없이 나오기)','시간을 내어 주신 분 쪽에서 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X11','kor',6,'u2',ARRAY['K6-2-u2-C7','K6-2-u2-C9']::text[],'허락 없이 담거나, 담아 둔 목소리·영상을 누리집·친구에게 내보내거나 다른 일에 쓴다','담아 둔 것은 빌려 온 것 — 허락 · 보고서에만 · 밖으로 안 내보내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X12','kor',6,'u2',ARRAY['K6-2-u2-C7']::text[],'매체의 뜻·절차마다의 쓰임·대면과 비대면을 헷갈린다','준비 — 찾기 · 진행 — 담기·영상 통화 · 정리 — 다시 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X13','kor',6,'u2',ARRAY['K6-2-u2-C8','K6-2-u2-C9']::text[],'면담 내용을 들은 그대로 통째로 옮기거나, 뭉뚱그려 남는 것이 없게 하거나, 답변의 뜻을 바꾸어 적는다','고르고 덜고 묶어 내 말로 — 뜻은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X14','kor',6,'u2',ARRAY['K6-2-u2-C9']::text[],'성찰을 사람 탓·잘잘못 가리기나 막연한 기분, 목소리·옷차림 같은 겉모습으로 한다','절차마다 무엇을 했나 → 다음에 무엇을 할까') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X15','kor',6,'u2',ARRAY['K6-2-u2-C9']::text[],'면담 보고서의 앞부분·가운데 부분·뒷부분이 담는 내용을 헷갈리거나 느낌·시각만 적는다','앞 — 왜·누구·준비 · 가운데 — 새로 안 사실 · 뒤 — 달라진 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X16','kor',6,'u2',ARRAY['K6-2-u2-C10']::text[],'인물이 되어 답할 때 작품에 없는 내용을 지어내거나 내 이야기를 대신한다','이야기 속 사건·말·행동에 밑줄 — 없으면 「나오지 않습니다」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X17','kor',6,'u2',ARRAY['K6-2-u2-C10']::text[],'모자란 곳을 파고들거나 깎아내리거나 억지로 답하게 하는 불쾌한 질문을 그대로 한다','궁금함 + 상대의 마음 헤아리기 + 고를 여지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X18','kor',6,'u2',ARRAY['K6-2-u2-C11']::text[],'겹받침을 모음 앞에서도 하나만 소리 내거나, 낱말 하나일 때 둘 다 소리 낸다','모음이 붙으면 뒤 자음이 넘어가요 — 맑아[말가]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X19','kor',6,'u2',ARRAY['K6-2-u2-C8']::text[],'모둠 역할(진행·약속·질문·매체·정리)이 하는 일을 헷갈리거나, 면담이 두려운 친구는 빠져야 한다고 여긴다','누가 시간을 · 누가 기기를 · 누가 글로 남기나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X20','kor',6,'u2',ARRAY['K6-2-u2-C2','K6-2-u2-C14']::text[],'면담 대상자를 정할 때 목적에 맞고 실제로 연락할 수 있으며 학생과 면담이 가능한 분인지 따지지 않고, 유명하거나 만나고 싶은 사람이면 된다고 여긴다','목적에 맞나 · 연락할 수 있나 · 학생과 면담이 가능한가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X21','kor',6,'u2',ARRAY['K6-2-u2-C7','K6-2-u2-C14']::text[],'비대면 면담은 얼굴을 마주하지 않으니 준비와 예절을 덜 챙겨도 된다고 여긴다(기기 연결 확인·카메라 렌즈 보며 말하기·마이크 끄기·녹음 동의를 놓침)','화면 너머에도 면담 대상자가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#1','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'mc','auto','만화 속 두 학생은 학교 전담 경찰관이 하는 일에 대해 궁금한 점을 어떤 방법으로 해결했나요?',ARRAY['K6-2-u2-X01','K6-2-u2-X02','K6-2-u2-X07']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"만화 속 두 학생은 학교 전담 경찰관이 하는 일에 대해 궁금한 점을 어떤 방법으로 해결했나요?","options":[{"t":"경찰관님께 면담을 부탁드려 질문하고 답을 들었다","correct":true},{"t":"친구들끼리 짐작해서 정했다","mis":"K6-2-u2-X01"},{"t":"경찰관님의 말씀을 듣지 않고 누리집 글만 읽었다","mis":"K6-2-u2-X02"},{"t":"교육 시간에 아무 질문도 하지 않고 기다렸다","mis":"K6-2-u2-X07"}],"explanation":["두 학생은 「경찰관님께 면담을 부탁드려 보자.」라고 했어요.","다음 날 준비한 질문을 하고 답을 들었어요.","궁금한 점을 면담으로 해결한 거예요."],"asset":{"type":"speech","turns":[{"who":"학생 1","text":"내일 학교에 학교 전담 경찰관이 와서 교육을 해 주신대."},{"who":"학생 2","text":"나도 들었어. 그런데 학교 전담 경찰관이 정확히 어떤 일을 하는지 궁금해."},{"who":"학생 1","text":"맞아. 나도 평소에 궁금한 점이 많았어. 그럼 학교 전담 경찰관님께 면담을 부탁드려 보자."},{"who":"학생 2","text":"좋아! 그렇다면 내일 경찰관님께 할 질문도 미리 만들어 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#2','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'sa','auto','만화 속 두 학생이 면담하기 전에 미리 한 준비는 무엇인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C1","difficulty":1,"kind":"sa","stem":"만화 속 두 학생이 면담하기 전에 미리 한 준비는 무엇인지 쓰세요.","answer":["질문","질문 준비","질문을 준비했다","질문 만들기","질문을 만들었다"],"explanation":["두 학생은 「경찰관님께 할 질문도 미리 만들어 보자.」라고 했어요.","면담 전에 질문을 준비한 거예요.","질문이 있어야 궁금한 점을 빠짐없이 물을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"학생 1","text":"내일 학교에 학교 전담 경찰관이 와서 교육을 해 주신대."},{"who":"학생 2","text":"나도 들었어. 그런데 학교 전담 경찰관이 정확히 어떤 일을 하는지 궁금해."},{"who":"학생 1","text":"맞아. 나도 평소에 궁금한 점이 많았어. 그럼 학교 전담 경찰관님께 면담을 부탁드려 보자."},{"who":"학생 2","text":"좋아! 그렇다면 내일 경찰관님께 할 질문도 미리 만들어 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#3','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'blank','auto','면담의 뜻이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#4','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',1,'ox','auto','면담 요청은 현장에 직접 방문하는 방법 말고도 전화하기, 전자 우편 보내기, 누리집에 문의하는 글 올리기로도 할 수 있어요.',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":4,"concept":"K6-2-u2-C2","difficulty":1,"kind":"ox","stem":"면담 요청은 현장에 직접 방문하는 방법 말고도 전화하기, 전자 우편 보내기, 누리집에 문의하는 글 올리기로도 할 수 있어요.","answer":"O","reason_options":[{"t":"『국어』 80쪽 도움말에서 면담 요청은 다양한 방법으로 할 수 있다고 했기 때문에","correct":true},{"t":"면담 요청은 반드시 직접 찾아가서만 해야 하기 때문에","mis":"K6-2-u2-X03"}],"mis":"K6-2-u2-X03","explanation":["신문 동아리는 직접 찾아가 면담을 요청했어요.","전화, 전자 우편, 누리집 글로도 요청할 수 있어요.","어느 방법이든 먼저 허락을 구하는 것은 같아요."],"asset":{"type":"passage","lines":["면담 요청은 현장에 직접 방문하거나 전화하기,","전자 우편 보내기, 누리집에 문의하는 글 올리기처럼","다양한 방법으로 할 수 있어요."],"title":"『국어』 80쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#5','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'mc','auto','면담으로 정보를 수집할 때 좋은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X03','K6-2-u2-X02']::text[],false,'{"seq":5,"concept":"K6-2-u2-C1","difficulty":2,"kind":"mc","stem":"면담으로 정보를 수집할 때 좋은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"궁금한 점을 자세하게 알 수 있고 생생한 정보를 얻을 수 있다","correct":true},{"t":"미리 준비하지 않아도 되어서 편하고 빠르다","mis":"K6-2-u2-X07"},{"t":"약속 없이 아무 때나 찾아가 물을 수 있다","mis":"K6-2-u2-X03"},{"t":"누구에게 물어도 늘 같은 답을 들을 수 있다","mis":"K6-2-u2-X02"}],"explanation":["『국어』 78쪽 예시 답안은 「궁금한 점을 자세하게 알 수 있어서 좋습니다.」예요.","면담 대상자에게서 생생한 정보를 얻을 수 있어요.","대신 약속과 준비가 꼭 필요해요."],"asset":{"type":"speech","turns":[{"who":"도움말 1","text":"면담으로 무엇을 알고 싶은지 목적을 분명하게 정해야 면담 대상자를 정할 수 있어요."},{"who":"도움말 2","text":"면담을 하면 면담 대상자에게서 생생한 정보를 얻을 수 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#6','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',2,'mc','auto','신문 동아리 친구들이 면담을 요청하며 가장 먼저 밝힌 것은 무엇인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X04','K6-2-u2-X05']::text[],false,'{"seq":6,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"신문 동아리 친구들이 면담을 요청하며 가장 먼저 밝힌 것은 무엇인가요?","options":[{"t":"자신들이 누구인지와 면담 목적(유기 동물 보호 기사)","correct":true},{"t":"면담할 날짜와 시간을 정해서 알린 것","mis":"K6-2-u2-X03"},{"t":"면담 대상자의 나이와 사는 곳을 물은 것","mis":"K6-2-u2-X04"},{"t":"면담을 마친 뒤에 드릴 감사 인사","mis":"K6-2-u2-X05"}],"explanation":["「○○초등학교 신문 동아리입니다.」라고 누구인지 밝혔어요.","「유기 동물 보호와 관련한 기사를 싣고 싶습니다.」라고 목적을 밝혔어요.","그다음 면담에 참여해 주실 수 있는지 허락을 구했어요."],"asset":{"type":"speech","turns":[{"who":"신문 동아리","text":"안녕하세요? ○○초등학교 신문 동아리입니다. 학교 신문에 유기 동물 보호와 관련한 기사를 싣고 싶습니다. 혹시 면담에 참여해 주실 수 있을까요?"},{"who":"보호 센터","text":"네, 다음 주 이 시간에 면담이 가능합니다."},{"who":"신문 동아리","text":"(일주일 뒤) 면담에 응해 주셔서 감사합니다. 미리 수집한 정보를 바탕으로 유기 동물 보호와 관련 있는 질문을 드리려고 합니다."},{"who":"신문 동아리","text":"유기 동물 보호 센터에서 하는 일은 무엇인가요?"},{"who":"신문 동아리","text":"(답을 듣고 나서) 감사합니다."},{"who":"보호 센터","text":"유기 동물 보호 센터에 관심을 가져 주어서 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#7','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'match','auto','『국어』 81쪽 3번처럼 면담의 특성을 정리했어요. 설명과 알맞은 낱말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C1","difficulty":2,"kind":"match","stem":"『국어』 81쪽 3번처럼 면담의 특성을 정리했어요. 설명과 알맞은 낱말을 이어 보세요.","pairs":[{"l":"대화를 주고받는 과정에서 얻는 것","r":"정보"},{"l":"대상자를 정하고 정보를 수집하고 질문을 만드는 일","r":"준비"},{"l":"면담할 때 꼭 지켜야 하는 것","r":"예의"}],"mis":"K6-2-u2-X07","explanation":["면담은 대화를 주고받는 과정에서 정보를 얻어요.","대상자 정하기·정보 수집·질문 만들기는 사전 준비예요.","면담할 때에는 예의를 지키는 것이 중요해요."],"asset":{"type":"passage","lines":["보기: 예의 · 준비 · 정보","● 면담은 대화를 주고받는 과정에서 (    ㉠    )을/를 얻는다.","● 면담을 진행하려면 면담 대상자를 정하고, 정보를 수집하고,","   질문을 만드는 사전 (    ㉡    )이/가 필요하다.","● 면담할 때에는 (    ㉢    )을/를 지키는 것이 중요하다."],"numbered":false,"title":"면담의 특성 정리하기 — 『국어』 81쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#8','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'mc','auto','생각 열기에서 친구 4가 「질문을 미리 마련하는 것 외에 어떤 것을 더 준비해야 할까?」라고 물었어요. 알맞은 대답은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X03','K6-2-u2-X01']::text[],false,'{"seq":8,"concept":"K6-2-u2-C1","difficulty":2,"kind":"mc","stem":"생각 열기에서 친구 4가 「질문을 미리 마련하는 것 외에 어떤 것을 더 준비해야 할까?」라고 물었어요. 알맞은 대답은 무엇인가요?","options":[{"t":"면담 대상자와 미리 약속을 잡고, 면담 목적과 관련된 정보를 찾아 두어야 해","correct":true},{"t":"질문을 더 길고 어렵게 고쳐 써야 해","mis":"K6-2-u2-X10"},{"t":"면담 대상자에게 알리지 않고 찾아가서 놀라게 해야 해","mis":"K6-2-u2-X03"},{"t":"면담 장소에서 친구들과 놀 거리를 준비해야 해","mis":"K6-2-u2-X01"}],"explanation":["면담은 사람을 만나 질문을 주고받는 활동이라 철저한 준비가 필요해요.","먼저 약속을 잡고 허락을 구해야 해요.","목적과 관련된 정보를 모아야 좋은 질문을 만들 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"다음 주 면담에서 소방관님께 드릴 질문을 모두 정했어."},{"who":"친구 2","text":"우리가 쓴 계획표를 다시 한번 살펴보자."},{"who":"친구 3","text":"직접 만나 이야기를 나누기 전까지 부족한 점을 찾고 보완하는 것이 좋겠어."},{"who":"친구 4","text":"질문을 미리 마련하는 것 외에 어떤 것을 더 준비해야 할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#9','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',2,'mc','auto','신문 동아리 친구들은 면담을 요청한 뒤 일주일 동안 어떤 준비를 했을까요?',ARRAY['K6-2-u2-X07','K6-2-u2-X03','K6-2-u2-X09']::text[],false,'{"seq":9,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"신문 동아리 친구들은 면담을 요청한 뒤 일주일 동안 어떤 준비를 했을까요?","options":[{"t":"유기 동물 보호와 관련된 정보를 수집하고 질문을 만들었을 것이다","correct":true},{"t":"아무것도 하지 않고 그날 떠오르는 대로 묻기로 했을 것이다","mis":"K6-2-u2-X07"},{"t":"면담 날짜를 다른 날로 바꾸겠다고 알렸을 것이다","mis":"K6-2-u2-X03"},{"t":"보호 센터에 있는 동물들의 사진만 모았을 것이다","mis":"K6-2-u2-X09"}],"explanation":["일주일 뒤 친구들은 「미리 수집한 정보를 바탕으로」 질문을 드린다고 했어요.","그러니 정보를 모으고 질문을 만들었을 거예요.","면담 요청 → 정보 수집·질문 만들기 → 면담 차례예요."],"asset":{"type":"speech","turns":[{"who":"신문 동아리","text":"안녕하세요? ○○초등학교 신문 동아리입니다. 학교 신문에 유기 동물 보호와 관련한 기사를 싣고 싶습니다. 혹시 면담에 참여해 주실 수 있을까요?"},{"who":"보호 센터","text":"네, 다음 주 이 시간에 면담이 가능합니다."},{"who":"신문 동아리","text":"(일주일 뒤) 면담에 응해 주셔서 감사합니다. 미리 수집한 정보를 바탕으로 유기 동물 보호와 관련 있는 질문을 드리려고 합니다."},{"who":"신문 동아리","text":"유기 동물 보호 센터에서 하는 일은 무엇인가요?"},{"who":"신문 동아리","text":"(답을 듣고 나서) 감사합니다."},{"who":"보호 센터","text":"유기 동물 보호 센터에 관심을 가져 주어서 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_basic#10','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',3,'essay','teacher','면담하는 모습을 보았거나 면담해 본 경험을 하나 쓰세요. 그때 누가(면담자) 누구에게(면담 대상자) 무엇을 알려고 물었는지도 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C1","difficulty":3,"kind":"essay","stem":"면담하는 모습을 보았거나 면담해 본 경험을 하나 쓰세요. 그때 누가(면담자) 누구에게(면담 대상자) 무엇을 알려고 물었는지도 함께 쓰세요.","answer_guide":{"answer":"예: 진로 수업 시간에 우리 반 친구들이 수의사 선생님께 질문한 적이 있다. 면담자는 우리 반 친구들이고 면담 대상자는 수의사 선생님이었다. 수의사가 하는 일과 수의사가 되는 방법을 알려고 물었다.","scoring_points":["면담을 보거나 해 본 경험을 썼는가","면담자와 면담 대상자를 밝혔는가","무엇을 알려고 물었는지(면담 목적) 썼는가"]},"explanation":["뉴스·축제·작가와의 만남·진로 수업처럼 여러 경험이 있어요.","누가 누구에게 물었는지 밝혀요.","무엇을 알려고 했는지가 면담 목적이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"뉴스에서 아나운서와 작가가 면담하는 장면을 본 적이 있어."},{"who":"친구 2","text":"지역 축제에 구경 갔을 때 축제를 준비하시는 분이 축제가 어땠는지 소감을 물어보셔서 대답한 적이 있어."},{"who":"친구 3","text":"작가와의 만남 시간에 궁금한 점을 묻고 답을 들은 적이 있어."},{"who":"친구 4","text":"진로 수업 시간에 내가 관심 있는 직업을 가진 분께 질문하고 이야기를 들은 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#1','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',2,'mc','auto','「이 단원에서 배워요」를 살펴보았어요. 소단원 2 「매체를 고려하여 면담하기」에서 배우는 내용은 무엇인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":2,"kind":"mc","stem":"「이 단원에서 배워요」를 살펴보았어요. 소단원 2 「매체를 고려하여 면담하기」에서 배우는 내용은 무엇인가요?","options":[{"t":"주변 인물과 면담하기","correct":true},{"t":"면담의 특성 이해하기","mis":"K6-2-u2-X05"},{"t":"면담의 절차 이해하기","mis":"K6-2-u2-X05"},{"t":"진로와 관련한 면담 자료 살펴보기","mis":"K6-2-u2-X05"}],"explanation":["소단원 1은 궁금한 내용을 질문하며 면담하기예요.","소단원 2는 매체를 고려하여 면담하기예요.","소단원 2에서 주변 인물과 면담하고, 성찰하며 보고서를 써요."],"asset":{"type":"passage","lines":["1. 궁금한 내용을 질문하며 면담하기","  • 면담의 특성 이해하기","  • 면담의 절차 이해하기","  • 진로와 관련한 면담 자료 살펴보기","2. 매체를 고려하여 면담하기","  • 주변 인물과 면담하기","  • 면담 과정을 성찰하고 면담 보고서 쓰기"],"numbered":false,"title":"이 단원에서 배워요 — 『국어』 79쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#2','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',2,'ox','auto','「뉴스에서 아나운서와 작가가 면담하는 장면을 본 적이 있어.」는 면담하는 모습을 본 경험으로 말할 수 있어요.',ARRAY['K6-2-u2-X01']::text[],false,'{"seq":2,"concept":"K6-2-u2-C1","difficulty":2,"kind":"ox","stem":"「뉴스에서 아나운서와 작가가 면담하는 장면을 본 적이 있어.」는 면담하는 모습을 본 경험으로 말할 수 있어요.","answer":"O","reason_options":[{"t":"영상 매체나 인쇄 매체에서 면담 장면을 본 것도 면담 경험으로 이야기할 수 있기 때문에","correct":true},{"t":"내가 직접 질문한 경험만 면담 경험이기 때문에","mis":"K6-2-u2-X01"}],"mis":"K6-2-u2-X01","explanation":["『국어』 79쪽 2번은 면담하는 모습을 보았거나 해 본 경험을 묻어요.","뉴스 속 면담 장면을 본 것도 경험이에요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"뉴스에서 아나운서와 작가가 면담하는 장면을 본 적이 있어."},{"who":"친구 2","text":"지역 축제에 구경 갔을 때 축제를 준비하시는 분이 축제가 어땠는지 소감을 물어보셔서 대답한 적이 있어."},{"who":"친구 3","text":"작가와의 만남 시간에 궁금한 점을 묻고 답을 들은 적이 있어."},{"who":"친구 4","text":"진로 수업 시간에 내가 관심 있는 직업을 가진 분께 질문하고 이야기를 들은 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#3','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',3,'mc','auto','「면담으로 무엇을 알고 싶은지 목적을 분명하게 정해야 면담 대상자를 정할 수 있어요.」 신문 동아리의 경우 목적과 면담 대상자가 바르게 짝 지어진 것은 무엇인가요?',ARRAY['K6-2-u2-X20','K6-2-u2-X07']::text[],false,'{"seq":3,"concept":"K6-2-u2-C2","difficulty":3,"kind":"mc","stem":"「면담으로 무엇을 알고 싶은지 목적을 분명하게 정해야 면담 대상자를 정할 수 있어요.」 신문 동아리의 경우 목적과 면담 대상자가 바르게 짝 지어진 것은 무엇인가요?","options":[{"t":"유기 동물 보호와 관련한 기사 쓰기 — 유기 동물 보호 센터","correct":true},{"t":"유기 동물 보호와 관련한 기사 쓰기 — 가장 유명한 동물 배우","mis":"K6-2-u2-X20"},{"t":"유기 동물 보호와 관련한 기사 쓰기 — 학교 전담 경찰관","mis":"K6-2-u2-X07"},{"t":"학교 전담 경찰관이 하는 일 알기 — 유기 동물 보호 센터","mis":"K6-2-u2-X07"}],"explanation":["먼저 무엇을 알고 싶은지 목적을 정해요.","유기 동물 보호를 알려면 그 일을 하는 곳에 물어야 해요.","목적이 대상자를 정해 줘요."],"asset":{"type":"speech","turns":[{"who":"도움말 1","text":"면담으로 무엇을 알고 싶은지 목적을 분명하게 정해야 면담 대상자를 정할 수 있어요."},{"who":"도움말 2","text":"면담을 하면 면담 대상자에게서 생생한 정보를 얻을 수 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#4','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',3,'error','auto','친구들이 면담을 요청하는 말을 연습했어요. 잘못된 말을 고르세요.',ARRAY['K6-2-u2-X03','K6-2-u2-X20']::text[],false,'{"seq":4,"concept":"K6-2-u2-C2","difficulty":3,"kind":"error","stem":"친구들이 면담을 요청하는 말을 연습했어요. 잘못된 말을 고르세요.","options":[{"t":"「다음 주 월요일 세 시에 찾아갈 테니 그때 기다려 주세요.」","correct":true,"mis_target":"K6-2-u2-X03"},{"t":"「저희는 ○○초등학교 신문 동아리입니다.」","mis":"K6-2-u2-X20"},{"t":"「혹시 면담에 참여해 주실 수 있을까요?」","mis":"K6-2-u2-X03"}],"explanation":["면담을 요청할 때에는 누구인지와 목적을 밝혀요.","날짜와 시간은 우리가 정해서 통보하지 않아요.","면담 대상자의 사정을 여쭈어 함께 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#5','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'mc','auto','면담이 친구와 나누는 일상 대화와 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X02']::text[],false,'{"seq":5,"concept":"K6-2-u2-C1","difficulty":3,"kind":"mc","stem":"면담이 친구와 나누는 일상 대화와 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"정보를 얻으려는 목적이 분명하고, 사전 준비와 예의가 필요하다","correct":true},{"t":"친해지려고 아무 이야기나 자유롭게 나눈다","mis":"K6-2-u2-X01"},{"t":"누구의 생각이 옳은지 겨루어 가린다","mis":"K6-2-u2-X01"},{"t":"찾아보면 바로 나오는 것만 묻는다","mis":"K6-2-u2-X02"}],"explanation":["면담은 정보를 얻으려는 목적이 있는 대화예요.","그래서 대상자 정하기·정보 수집·질문 만들기 같은 준비가 필요해요.","면담할 때에는 예의를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#6','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',3,'mc','auto','신문 동아리 친구들은 면담을 마치고 「감사합니다.」라고 했고, 보호 센터에서도 고맙다고 했어요. 이 장면으로 알 수 있는 면담의 특성은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X01']::text[],false,'{"seq":6,"concept":"K6-2-u2-C2","difficulty":3,"kind":"mc","stem":"신문 동아리 친구들은 면담을 마치고 「감사합니다.」라고 했고, 보호 센터에서도 고맙다고 했어요. 이 장면으로 알 수 있는 면담의 특성은 무엇인가요?","options":[{"t":"면담할 때에는 예의를 지키는 것이 중요하다","correct":true},{"t":"면담을 마치면 바로 자리를 떠도 된다","mis":"K6-2-u2-X10"},{"t":"면담은 정보만 얻으면 인사는 하지 않아도 된다","mis":"K6-2-u2-X10"},{"t":"면담은 서로 칭찬하려고 하는 대화이다","mis":"K6-2-u2-X01"}],"explanation":["친구들은 면담을 시작할 때와 마칠 때 감사 인사를 했어요.","시간을 내어 준 면담 대상자를 존중하는 모습이에요.","면담의 특성 가운데 「예의」에 해당해요."],"asset":{"type":"speech","turns":[{"who":"신문 동아리","text":"안녕하세요? ○○초등학교 신문 동아리입니다. 학교 신문에 유기 동물 보호와 관련한 기사를 싣고 싶습니다. 혹시 면담에 참여해 주실 수 있을까요?"},{"who":"보호 센터","text":"네, 다음 주 이 시간에 면담이 가능합니다."},{"who":"신문 동아리","text":"(일주일 뒤) 면담에 응해 주셔서 감사합니다. 미리 수집한 정보를 바탕으로 유기 동물 보호와 관련 있는 질문을 드리려고 합니다."},{"who":"신문 동아리","text":"유기 동물 보호 센터에서 하는 일은 무엇인가요?"},{"who":"신문 동아리","text":"(답을 듣고 나서) 감사합니다."},{"who":"보호 센터","text":"유기 동물 보호 센터에 관심을 가져 주어서 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#7','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'mc','auto','학교 전담 경찰관이 「학생들에게 꼭 해 주고 싶은 말씀」으로 알려 준 내용은 무엇인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":7,"concept":"K6-2-u2-C1","difficulty":3,"kind":"mc","stem":"학교 전담 경찰관이 「학생들에게 꼭 해 주고 싶은 말씀」으로 알려 준 내용은 무엇인가요?","options":[{"t":"어려운 일은 혼자 해결하려 하지 말고 믿을 만한 어른에게 알리고 도움을 요청하라","correct":true},{"t":"어려운 일은 친구에게도 말하지 말고 혼자 꾹 참아 보라","mis":"K6-2-u2-X07"},{"t":"경찰관이 되려면 무엇보다 운동을 많이 해 두라","mis":"K6-2-u2-X07"},{"t":"학교 규칙은 상황에 따라 꼭 지키지 않아도 된다","mis":"K6-2-u2-X07"}],"explanation":["학생은 앞으로의 당부를 묻는 질문을 했어요.","경찰관은 혼자 해결하려 하지 말라고 했어요.","믿을 만한 어른에게 알리고 도움을 요청하라고 당부했어요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"학교 전담 경찰관을 하시면서 가장 보람 있는 일은 무엇인가요?"},{"who":"경찰관","text":"학교에서 어려움을 겪던 학생이 상담과 지원으로 상황이 좋아질 때 큰 보람을 느낍니다."},{"who":"학생","text":"학생들에게 꼭 해 주고 싶은 말씀이 있다면 무엇인가요?"},{"who":"경찰관","text":"어려운 일이 있을 때에는 혼자 해결하려 하지 말고, 담임 선생님이나 믿을 만한 어른들에게 사실을 알리고 도움을 요청하세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#8','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',4,'essay','teacher','생각 열기의 물음 「궁금한 점을 해결하고자 면담할 때 무엇을 준비해야 할까요?」에 답하세요. 준비할 것을 두 가지 이상 쓰고, 왜 필요한지도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u2-C1","difficulty":4,"kind":"essay","stem":"생각 열기의 물음 「궁금한 점을 해결하고자 면담할 때 무엇을 준비해야 할까요?」에 답하세요. 준비할 것을 두 가지 이상 쓰고, 왜 필요한지도 쓰세요.","answer_guide":{"answer":"예: 첫째, 면담 질문을 미리 준비해야 한다. 질문이 있어야 궁금한 점을 빠짐없이 물을 수 있기 때문이다. 둘째, 면담 대상자에게 미리 약속을 잡고 허락을 구해야 한다. 면담 대상자가 시간을 내어 주셔야 면담을 할 수 있기 때문이다. 셋째, 면담 목적과 관련된 정보를 찾아 두어야 더 깊이 있는 질문을 할 수 있다.","scoring_points":["준비할 것을 두 가지 이상 썼는가","질문 준비·약속과 허락·정보 수집 가운데 알맞은 것을 골랐는가","준비가 필요한 까닭을 썼는가"]},"explanation":["『국어』 77쪽 예시 답안은 「면담 질문을 준비합니다.」예요.","약속을 잡고 정보를 모으는 일도 준비예요.","왜 필요한지까지 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"다음 주 면담에서 소방관님께 드릴 질문을 모두 정했어."},{"who":"친구 2","text":"우리가 쓴 계획표를 다시 한번 살펴보자."},{"who":"친구 3","text":"직접 만나 이야기를 나누기 전까지 부족한 점을 찾고 보완하는 것이 좋겠어."},{"who":"친구 4","text":"질문을 미리 마련하는 것 외에 어떤 것을 더 준비해야 할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#9','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',4,'essay','teacher','직접 만나 면담하고 싶은 사람을 한 명 정하고, 그 까닭과 면담을 요청할 방법, 그분께 하고 싶은 질문 하나를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C2","difficulty":4,"kind":"essay","stem":"직접 만나 면담하고 싶은 사람을 한 명 정하고, 그 까닭과 면담을 요청할 방법, 그분께 하고 싶은 질문 하나를 쓰세요.","answer_guide":{"answer":"예: 우리 동네 도서관 사서 선생님을 면담하고 싶다. 책을 좋아해서 사서가 하는 일이 궁금하기 때문이다. 도서관에 직접 찾아가 우리가 누구인지와 면담 목적을 말씀드리고 허락을 구하겠다. 「사서로 일하시면서 가장 보람 있었던 때는 언제인가요?」라고 묻고 싶다.","scoring_points":["면담하고 싶은 사람과 그 까닭을 썼는가","면담 요청 방법(방문·전화·전자 우편·누리집)과 허락 구하기를 썼는가","목적에 맞는 질문을 하나 썼는가"]},"explanation":["면담하고 싶은 까닭이 곧 면담 목적이 돼요.","요청할 때에는 누구인지와 목적을 밝히고 허락을 구해요.","질문은 그 목적과 이어지게 만들어요."],"asset":{"type":"passage","lines":["면담 요청은 현장에 직접 방문하거나 전화하기,","전자 우편 보내기, 누리집에 문의하는 글 올리기처럼","다양한 방법으로 할 수 있어요."],"title":"『국어』 80쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L02_challenge#10','kor',6,2,'u2','L02','tb_g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',4,'mc','auto','신문 동아리 만화에서 면담의 특성 「준비」가 가장 잘 드러난 말은 무엇인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X03','K6-2-u2-X07']::text[],false,'{"seq":10,"concept":"K6-2-u2-C1","difficulty":4,"kind":"mc","stem":"신문 동아리 만화에서 면담의 특성 「준비」가 가장 잘 드러난 말은 무엇인가요?","options":[{"t":"「미리 수집한 정보를 바탕으로 유기 동물 보호와 관련 있는 질문을 드리려고 합니다.」","correct":true},{"t":"「유기 동물 보호 센터에 관심을 가져 주어서 감사합니다.」","mis":"K6-2-u2-X05"},{"t":"「네, 다음 주 이 시간에 면담이 가능합니다.」","mis":"K6-2-u2-X03"},{"t":"「유기 동물 보호 센터에서 하는 일은 무엇인가요?」","mis":"K6-2-u2-X07"}],"explanation":["준비는 대상자 정하기·정보 수집·질문 만들기예요.","「미리 수집한 정보」와 「질문을 드리려고」가 준비를 보여 줘요.","감사 인사는 예의, 시간 약속은 요청에 해당해요."],"asset":{"type":"speech","turns":[{"who":"신문 동아리","text":"안녕하세요? ○○초등학교 신문 동아리입니다. 학교 신문에 유기 동물 보호와 관련한 기사를 싣고 싶습니다. 혹시 면담에 참여해 주실 수 있을까요?"},{"who":"보호 센터","text":"네, 다음 주 이 시간에 면담이 가능합니다."},{"who":"신문 동아리","text":"(일주일 뒤) 면담에 응해 주셔서 감사합니다. 미리 수집한 정보를 바탕으로 유기 동물 보호와 관련 있는 질문을 드리려고 합니다."},{"who":"신문 동아리","text":"유기 동물 보호 센터에서 하는 일은 무엇인가요?"},{"who":"신문 동아리","text":"(답을 듣고 나서) 감사합니다."},{"who":"보호 센터","text":"유기 동물 보호 센터에 관심을 가져 주어서 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#1','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'mc','auto','윤서네 모둠이 면담을 준비하는 과정에서 가장 먼저 한 일은 무엇인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":1,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"윤서네 모둠이 면담을 준비하는 과정에서 가장 먼저 한 일은 무엇인가요?","options":[{"t":"면담 모둠 구성하기","correct":true},{"t":"면담 질문 만들기","mis":"K6-2-u2-X05"},{"t":"면담을 요청하고 허락 구하기","mis":"K6-2-u2-X05"},{"t":"면담 역할 정하기","mis":"K6-2-u2-X05"}],"explanation":["윤서네 모둠은 먼저 모둠을 구성했어요.","그다음 목적·대상자·방식을 정하고 자료를 찾아 질문을 만들었어요.","역할을 정한 뒤 마지막으로 요청하고 허락을 구했어요."],"asset":{"type":"passage","lines":["① 면담 모둠 구성하기 → ② 면담 목적 정하기","③ 면담 대상자 정하기 → ④ 면담 방식 정하기","⑤ 면담에 필요한 자료 찾기 → ⑥ 면담 질문 만들기","⑦ 면담 역할 정하기 → ⑧ 면담을 요청하고 허락 구하기"],"numbered":false,"title":"윤서네 모둠이 면담을 준비하는 과정 — 『국어』 82~83쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#2','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C12',1,'sa','auto','윤서네 모둠이 정한 면담 대상자는 누구인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C12","difficulty":1,"kind":"sa","stem":"윤서네 모둠이 정한 면담 대상자는 누구인지 쓰세요.","answer":["공공 도서관 사서","사서","도서관 사서","사서 선생님","공공 도서관 사서 선생님"],"explanation":["윤서네 모둠은 도서관 사서라는 직업을 알리는 글을 쓰려고 했어요.","그래서 공공 도서관 사서를 면담 대상자로 정했어요.","목적이 대상자를 정해 줘요."],"asset":{"type":"passage","lines":["● 면담 목적: 도서관 사서라는 직업을 알리는 글을 쓰려고","● 면담 대상자: 공공 도서관 사서","● 면담 방식: 대면 면담","● 면담 요청하기: 직접 찾아뵙고 면담 허락 구하기","● 날짜와 시간: 20○○년 ○○월 ○○일 ○○시","● 장소: 공공 도서관"],"numbered":false,"title":"면담을 요청하는 대화 연습 — 『국어』 83쪽 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#3','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',1,'mc','auto','면담 개요의 질문 ㉠~㉥ 가운데에서 면담의 목적에 맞지 않는 질문은 무엇인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":3,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"면담 개요의 질문 ㉠~㉥ 가운데에서 면담의 목적에 맞지 않는 질문은 무엇인가요?","options":[{"t":"㉣ 좋아하는 색깔은 무엇인가요?","correct":true},{"t":"㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","mis":"K6-2-u2-X07"},{"t":"㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","mis":"K6-2-u2-X07"},{"t":"㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","mis":"K6-2-u2-X07"}],"explanation":["면담의 목적은 도서관 사서라는 직업에 대해 알아보는 거예요.","좋아하는 색깔은 사서의 일을 알 수 있는 내용이 아니에요.","그래서 ㉣은 목적에 맞지 않아요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#4','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'ox','auto','면담 진행하기는 면담 열기, 질문하기, 면담 마무리하기로 이루어져요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C3","difficulty":1,"kind":"ox","stem":"면담 진행하기는 면담 열기, 질문하기, 면담 마무리하기로 이루어져요.","answer":"O","reason_options":[{"t":"면담 개요에서 면담 진행하기를 이 세 단계로 나누었기 때문에","correct":true},{"t":"면담 진행하기는 질문하기 한 단계뿐이기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["면담 열기에서는 인사하고 목적을 설명해요.","질문하기에서는 질문하고 답변을 들어요.","면담 마무리하기에서는 결과를 확인하고 감사 인사를 해요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#5','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',2,'mc','auto','면담 열기에서 하는 일이 아닌 것은 무엇인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X11']::text[],false,'{"seq":5,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"면담 열기에서 하는 일이 아닌 것은 무엇인가요?","options":[{"t":"면담 결과 확인하기","correct":true},{"t":"인사하기","mis":"K6-2-u2-X05"},{"t":"면담 목적 설명하기","mis":"K6-2-u2-X05"},{"t":"녹음·녹화 동의 구하기","mis":"K6-2-u2-X11"}],"explanation":["면담 열기에서는 인사하고 목적을 설명하고 녹음·녹화 동의를 구해요.","면담 결과 확인하기는 면담 마무리하기에서 해요.","단계마다 할 일을 나누어 기억해요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#6','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',2,'match','auto','면담 개요의 질문을 기준에 따라 나누었어요. 질문과 기준을 바르게 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u2-C4","difficulty":2,"kind":"match","stem":"면담 개요의 질문을 기준에 따라 나누었어요. 질문과 기준을 바르게 이어 보세요.","pairs":[{"l":"㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","r":"구체적인 사실에 대한 질문"},{"l":"㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","r":"생각이나 느낌에 대한 질문"},{"l":"㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["㉠·㉡은 구체적인 사실을 묻는 질문이에요.","㉢·㉤은 생각이나 느낌을 묻는 질문이에요.","㉥은 앞으로의 계획이나 당부를 묻는 질문이에요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#7','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C12',2,'mc','auto','윤서가 녹음이나 녹화를 해도 되는지 묻자 사서는 어떻게 답했나요?',ARRAY['K6-2-u2-X11','K6-2-u2-X12']::text[],false,'{"seq":7,"concept":"K6-2-u2-C12","difficulty":2,"kind":"mc","stem":"윤서가 녹음이나 녹화를 해도 되는지 묻자 사서는 어떻게 답했나요?","options":[{"t":"괜찮다며, 녹음이 더 편하고 학교 과제에만 써 달라고 했다","correct":true},{"t":"녹화는 괜찮으니 영상을 누리집에 올려도 된다고 했다","mis":"K6-2-u2-X11"},{"t":"녹음도 녹화도 하면 안 된다며 거절했다","mis":"K6-2-u2-X12"},{"t":"묻지 않아도 되니 마음대로 하라고 했다","mis":"K6-2-u2-X11"}],"explanation":["면담 열기에서 녹음·녹화 동의를 구했어요.","사서는 녹음이 더 편하다고 했어요.","면담 내용은 학교 과제에만 써 달라고 했어요."],"asset":{"type":"speech","turns":[{"who":"윤서","text":"면담 내용을 다 기억할 수 없어 녹음이나 녹화를 하려고 하는데요, 괜찮으실까요?"},{"who":"사서","text":"(간추림) 괜찮다고 하면서, 녹화보다 녹음이 편하고 면담 내용은 학교 과제에만 써 달라고 했다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#8','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',2,'blank','auto','『국어』 87쪽 4번처럼 면담 진행하기에서 할 일을 정리했어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#9','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C12',2,'mc','auto','「윤서네 모둠의 면담」에서 사서가 말한, 사서에게 가장 필요한 능력은 무엇인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X08']::text[],false,'{"seq":9,"concept":"K6-2-u2-C12","difficulty":2,"kind":"mc","stem":"「윤서네 모둠의 면담」에서 사서가 말한, 사서에게 가장 필요한 능력은 무엇인가요?","options":[{"t":"소통 능력, 검색 능력, 꼼꼼함","correct":true},{"t":"책을 빨리 읽는 능력과 큰 목소리","mis":"K6-2-u2-X13"},{"t":"문헌정보학 공부와 사서 자격증","mis":"K6-2-u2-X08"},{"t":"대출·반납을 돕고 책을 정리하는 일","mis":"K6-2-u2-X08"}],"explanation":["㉢은 사서의 생각을 묻는 질문이에요.","사서는 소통 능력, 검색 능력, 꼼꼼함을 들었어요.","자격증은 ㉡, 대출·반납은 ㉠의 답이에요."],"asset":{"type":"passage","lines":["(간추림) ㉠ 대출·반납 돕기, 새 책 주문, 책 정리, 독서 행사나 프로그램 준비","(간추림) ㉡ 대학에서 문헌정보학 공부 → 사서 자격증 → 도서관 채용 절차","(간추림) ㉢ 소통 능력, 검색 능력, 꼼꼼함","(간추림) ㉤ 추천한 책이 도움이 됐다는 말을 들을 때","(간추림) ㉥ 책을 읽는 습관과 궁금한 것을 스스로 찾아보는 습관 기르기"],"numbered":false,"title":"「윤서네 모둠의 면담」 질문과 답변 정리 (듣기 자료 · 『국어』 86쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_basic#10','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',3,'essay','teacher','『국어』 85쪽 (4)처럼, 자신이라면 사서에게 어떤 질문을 했을지 기준마다 하나씩 쓰세요(구체적인 사실 · 생각이나 느낌 · 앞으로의 계획이나 당부).','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C4","difficulty":3,"kind":"essay","stem":"『국어』 85쪽 (4)처럼, 자신이라면 사서에게 어떤 질문을 했을지 기준마다 하나씩 쓰세요(구체적인 사실 · 생각이나 느낌 · 앞으로의 계획이나 당부).","answer_guide":{"answer":"예: 구체적인 사실 — 도서 대출·반납 외에 어떤 일을 하나요? / 생각이나 느낌 — 일을 하면서 가장 어려운 점은 무엇인가요? / 앞으로의 계획이나 당부 — 올해 도서관에서 어떤 프로그램을 진행하려고 계획 중이신가요?","scoring_points":["세 기준에 맞는 질문을 하나씩 썼는가","모든 질문이 사서라는 직업을 알아보는 목적에 맞는가","면담 대상자가 이해하기 쉬운 질문인가"]},"explanation":["먼저 기준이 무엇을 묻는지 떠올려요.","사서라는 직업을 알아보는 목적에 맞게 만들어요.","질문에 따라 수집하는 정보가 달라져요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#1','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',2,'mc','auto','「면담 요청하기, 자료 찾기, 질문하기, 기록하기 이외에 또 어떤 역할이 필요할까?」에 대한 대답으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X19','K6-2-u2-X03']::text[],false,'{"seq":1,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"「면담 요청하기, 자료 찾기, 질문하기, 기록하기 이외에 또 어떤 역할이 필요할까?」에 대한 대답으로 알맞은 것은 무엇인가요?","options":[{"t":"면담 내용을 녹음하거나 녹화하는 역할","correct":true},{"t":"면담 대상자의 사는 곳을 알아보는 역할","mis":"K6-2-u2-X04"},{"t":"면담이 두려운 친구를 빼는 역할","mis":"K6-2-u2-X19"},{"t":"면담 날짜를 혼자 정해 통보하는 역할","mis":"K6-2-u2-X03"}],"explanation":["『국어』 83쪽 예시 답안은 자료를 찾는 역할, 질문을 만드는 역할, 녹음하거나 녹화하는 역할이에요.","역할을 나누면 모두가 면담에 참여할 수 있어요.","개인 정보를 알아보는 일은 면담 역할이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#2','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C12',2,'mc','auto','윤서네 모둠이 면담을 요청하는 대화를 연습할 때 정한 면담 방식은 무엇인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X05']::text[],false,'{"seq":2,"concept":"K6-2-u2-C12","difficulty":2,"kind":"mc","stem":"윤서네 모둠이 면담을 요청하는 대화를 연습할 때 정한 면담 방식은 무엇인가요?","options":[{"t":"대면 면담","correct":true},{"t":"온라인 화상 회의로 하는 비대면 면담","mis":"K6-2-u2-X12"},{"t":"전자 우편으로 하는 비대면 면담","mis":"K6-2-u2-X12"},{"t":"면담 방식은 정하지 않았다","mis":"K6-2-u2-X05"}],"explanation":["윤서네 모둠은 직접 찾아뵙고 면담 허락을 구하기로 했어요.","공공 도서관에서 만나기로 했으니 대면 면담이에요.","직접 만나지 않고 하면 비대면 면담이에요."],"asset":{"type":"passage","lines":["● 면담 목적: 도서관 사서라는 직업을 알리는 글을 쓰려고","● 면담 대상자: 공공 도서관 사서","● 면담 방식: 대면 면담","● 면담 요청하기: 직접 찾아뵙고 면담 허락 구하기","● 날짜와 시간: 20○○년 ○○월 ○○일 ○○시","● 장소: 공공 도서관"],"numbered":false,"title":"면담을 요청하는 대화 연습 — 『국어』 83쪽 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#3','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',3,'mc','auto','질문 ㉤ 「근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?」는 어떤 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":3,"concept":"K6-2-u2-C4","difficulty":3,"kind":"mc","stem":"질문 ㉤ 「근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?」는 어떤 질문인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적에 맞지 않는 질문","mis":"K6-2-u2-X07"}],"explanation":["「언제」가 들어 있어도 묻는 것은 보람을 느낀 마음이에요.","그래서 생각이나 느낌에 대한 질문이에요.","『국어』 85쪽에서도 ㉢·㉤을 생각이나 느낌에 대한 질문으로 나누었어요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#4','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',3,'error','auto','면담을 요청하는 대화를 연습하며 친구들이 한 말이에요. 잘못된 말을 고르세요.',ARRAY['K6-2-u2-X03','K6-2-u2-X07']::text[],false,'{"seq":4,"concept":"K6-2-u2-C3","difficulty":3,"kind":"error","stem":"면담을 요청하는 대화를 연습하며 친구들이 한 말이에요. 잘못된 말을 고르세요.","options":[{"t":"「날짜와 장소는 우리 모둠이 정해서 알려 드리면 돼.」","correct":true,"mis_target":"K6-2-u2-X03"},{"t":"「먼저 면담 목적을 설명하고 허락을 구하자.」","mis":"K6-2-u2-X07"},{"t":"「날짜와 시간, 장소는 사서 선생님 사정에 맞추어 정하자.」","mis":"K6-2-u2-X03"}],"explanation":["면담을 요청할 때에는 목적을 설명하고 허락을 구해요.","면담 방식, 날짜와 시간, 장소를 함께 정해요.","면담 대상자를 배려해 사정에 맞추어 조율해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#5','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C12',3,'mc','auto','윤서가 「책을 빌려주는 일만 하시는 줄 알았는데 생각보다 일이 많네요.」라고 한 뒤 다음 질문을 했어요. 이 말에서 알 수 있는 윤서의 태도는 무엇인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X01','K6-2-u2-X07']::text[],false,'{"seq":5,"concept":"K6-2-u2-C12","difficulty":3,"kind":"mc","stem":"윤서가 「책을 빌려주는 일만 하시는 줄 알았는데 생각보다 일이 많네요.」라고 한 뒤 다음 질문을 했어요. 이 말에서 알 수 있는 윤서의 태도는 무엇인가요?","options":[{"t":"답변을 귀 기울여 듣고 반응한 뒤 다음 질문으로 자연스럽게 이어 갔다","correct":true},{"t":"답변을 듣지 않고 질문지만 차례대로 읽었다","mis":"K6-2-u2-X06"},{"t":"사서의 답변이 틀렸다고 따지며 다시 말하게 했다","mis":"K6-2-u2-X01"},{"t":"면담 목적과 상관없는 이야기로 바꾸었다","mis":"K6-2-u2-X07"}],"explanation":["윤서는 사서의 답을 듣고 새롭게 안 점을 말했어요.","잘 듣고 있다는 것을 보여 주는 반응이에요.","그다음 준비한 질문으로 자연스럽게 넘어갔어요."],"asset":{"type":"speech","turns":[{"who":"윤서","text":"현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?"},{"who":"사서","text":"(간추림) 대출·반납을 돕고 원하는 책을 찾도록 돕는다. 새 책을 주문하고 책을 정리하며, 독서 행사나 프로그램도 준비한다."},{"who":"윤서","text":"책을 빌려주는 일만 하시는 줄 알았는데 생각보다 일이 많네요. 사서가 되려면 어떤 과정을 거쳐야 하나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#6','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',3,'mc','auto','활동지 예처럼 수집한 내용을 바탕으로 만든 질문이 좋은 까닭은 무엇인가요?',ARRAY['K6-2-u2-X02','K6-2-u2-X10','K6-2-u2-X07']::text[],false,'{"seq":6,"concept":"K6-2-u2-C4","difficulty":3,"kind":"mc","stem":"활동지 예처럼 수집한 내용을 바탕으로 만든 질문이 좋은 까닭은 무엇인가요?","options":[{"t":"찾아보면 아는 것은 미리 알고, 그분만 답할 수 있는 것을 깊이 물을 수 있어서","correct":true},{"t":"경찰의 업무가 무엇인지 처음부터 다시 물어볼 수 있기 때문","mis":"K6-2-u2-X02"},{"t":"질문이 길고 어려울수록 좋은 질문이기 때문","mis":"K6-2-u2-X10"},{"t":"면담 목적과 상관없이 아무것이나 물어볼 수 있기 때문","mis":"K6-2-u2-X07"}],"explanation":["경찰의 업무 분야는 미리 찾아서 알 수 있어요.","그 정보를 바탕으로 「지금 어떤 업무를 하고 계신가요?」라고 물었어요.","그분만 답할 수 있는 것을 물으니 더 깊은 정보를 얻어요."],"asset":{"type":"passage","lines":["수집한 내용 — 경찰의 업무는 수사, 안전, 경비, 교통, 정보 분야로 나뉩니다.","면담 질문 — 경찰의 업무에는 수사, 안전, 경비, 교통, 정보 등이 있다고 하는데,","   지금 어떤 업무를 하고 계신가요?"],"numbered":false,"title":"수집한 내용을 바탕으로 면담 질문 만들기 (활동지 예)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#7','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',3,'mc','auto','「면담을 한 뒤에는 면담 목적을 고려하며 면담 내용을 정리해야 해요.」 면담 내용을 정리하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X14']::text[],false,'{"seq":7,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"「면담을 한 뒤에는 면담 목적을 고려하며 면담 내용을 정리해야 해요.」 면담 내용을 정리하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"질문과 답변을 중심으로 내용을 간략하게 정리한다","correct":true},{"t":"들은 말을 하나도 빼지 않고 그대로 받아 적는다","mis":"K6-2-u2-X13"},{"t":"기억나는 느낌만 한 줄로 적는다","mis":"K6-2-u2-X13"},{"t":"면담 대상자의 옷차림과 목소리를 자세히 적는다","mis":"K6-2-u2-X14"}],"explanation":["『국어』 86쪽 도움말은 질문과 답변을 중심으로 간략하게 정리하라고 해요.","면담 목적을 생각하며 중요한 내용을 골라요.","질문을 기준에 따라 나누어 정리하면 한눈에 보여요."],"asset":{"type":"passage","lines":["(간추림) ㉠ 대출·반납 돕기, 새 책 주문, 책 정리, 독서 행사나 프로그램 준비","(간추림) ㉡ 대학에서 문헌정보학 공부 → 사서 자격증 → 도서관 채용 절차","(간추림) ㉢ 소통 능력, 검색 능력, 꼼꼼함","(간추림) ㉤ 추천한 책이 도움이 됐다는 말을 들을 때","(간추림) ㉥ 책을 읽는 습관과 궁금한 것을 스스로 찾아보는 습관 기르기"],"numbered":false,"title":"「윤서네 모둠의 면담」 질문과 답변 정리 (듣기 자료 · 『국어』 86쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#8','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',4,'essay','teacher','질문 ㉣ 「좋아하는 색깔은 무엇인가요?」가 면담 목적에 맞지 않는 까닭을 쓰고, 목적에 맞는 질문으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u2-C4","difficulty":4,"kind":"essay","stem":"질문 ㉣ 「좋아하는 색깔은 무엇인가요?」가 면담 목적에 맞지 않는 까닭을 쓰고, 목적에 맞는 질문으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 면담의 목적은 도서관 사서라는 직업에 대해 알아보는 것인데, 좋아하는 색깔은 사서의 일을 알 수 있는 내용이 아니기 때문이다. 고친 질문 — 「사서로 일하시면서 가장 어려운 점은 무엇인가요?」","scoring_points":["면담 목적(사서라는 직업 알아보기)을 들어 까닭을 썼는가","고친 질문이 사서의 일과 이어지는가","예의 바르고 명료한 표현인가"]},"explanation":["질문은 면담 목적과 하나씩 견주어 봐요.","목적과 멀면 덜어 내거나 고쳐요.","질문에 따라 대화의 방향과 수집하는 정보가 달라져요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#9','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C12',4,'essay','teacher','『국어』 87쪽 (2)처럼 윤서네 모둠 친구 가운데 한 명이 되었다고 생각하고 면담을 되돌아보세요. 새롭게 안 점, 정보를 얻기에 가장 효과적이었던 질문과 그 까닭, 아쉬웠던 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C12","difficulty":4,"kind":"essay","stem":"『국어』 87쪽 (2)처럼 윤서네 모둠 친구 가운데 한 명이 되었다고 생각하고 면담을 되돌아보세요. 새롭게 안 점, 정보를 얻기에 가장 효과적이었던 질문과 그 까닭, 아쉬웠던 점을 쓰세요.","answer_guide":{"answer":"예: 새롭게 안 점 — 사서가 대출·반납뿐 아니라 책 주문, 책 정리, 독서 행사 준비까지 한다는 것을 알았다. 가장 효과적이었던 질문 — 「현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?」 사서가 하는 여러 가지 일을 한 번에 알 수 있었기 때문이다. 아쉬웠던 점 — 면담 시간이 짧아서 더 묻지 못했다.","scoring_points":["새롭게 안 점을 면담 내용에 근거해 썼는가","가장 효과적이었던 질문과 그 까닭을 썼는가","아쉬웠던 점을 썼는가"]},"explanation":["면담 내용을 정리한 표를 다시 살펴요.","어떤 질문에서 정보를 가장 많이 얻었는지 찾아요.","아쉬웠던 점은 다음 면담에서 고칠 거리예요."],"asset":{"type":"passage","lines":["(간추림) ㉠ 대출·반납 돕기, 새 책 주문, 책 정리, 독서 행사나 프로그램 준비","(간추림) ㉡ 대학에서 문헌정보학 공부 → 사서 자격증 → 도서관 채용 절차","(간추림) ㉢ 소통 능력, 검색 능력, 꼼꼼함","(간추림) ㉤ 추천한 책이 도움이 됐다는 말을 들을 때","(간추림) ㉥ 책을 읽는 습관과 궁금한 것을 스스로 찾아보는 습관 기르기"],"numbered":false,"title":"「윤서네 모둠의 면담」 질문과 답변 정리 (듣기 자료 · 『국어』 86쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L03_challenge#10','kor',6,2,'u2','L03','tb_g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',4,'mc','auto','「면담 질문에 따라 대화의 방향과 수집하는 정보가 달라질 수 있어요.」 ㉠ 대신 「도서관은 몇 시에 문을 닫나요?」라고 물었다면 어떻게 되었을까요?',ARRAY['K6-2-u2-X02','K6-2-u2-X10','K6-2-u2-X05']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":4,"kind":"mc","stem":"「면담 질문에 따라 대화의 방향과 수집하는 정보가 달라질 수 있어요.」 ㉠ 대신 「도서관은 몇 시에 문을 닫나요?」라고 물었다면 어떻게 되었을까요?","options":[{"t":"사서라는 직업에 대해 알 수 있는 정보를 얻기 어려웠을 것이다","correct":true},{"t":"사서가 하는 일을 더 자세히 알 수 있었을 것이다","mis":"K6-2-u2-X02"},{"t":"질문이 짧아서 무조건 더 좋은 면담이 되었을 것이다","mis":"K6-2-u2-X10"},{"t":"면담 열기를 다시 해야 했을 것이다","mis":"K6-2-u2-X05"}],"explanation":["㉠은 사서가 맡고 있는 일을 자세히 듣는 질문이에요.","문 닫는 시간은 누리집에서도 찾을 수 있고 사서의 일과도 멀어요.","질문이 바뀌면 얻는 정보도 달라져요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#1','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C13',1,'sa','auto','「로봇 공학자와의 면담」에서 면담 대상자는 누구인지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C13","difficulty":1,"kind":"sa","stem":"「로봇 공학자와의 면담」에서 면담 대상자는 누구인지 쓰세요.","answer":["로봇 공학자","로봇공학자"],"explanation":["학생들은 로봇 공학자를 만나 면담했어요.","면담 대상자는 질문을 받고 답하는 사람이에요.","면담자는 질문한 6학년 학생들이에요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"안녕하세요? 만나 뵙게 되어 반갑습니다. 저희는 ○○초등학교 6학년 학생들입니다. 바쁘실 텐데 귀한 시간 내어 면담에 참여해 주셔서 감사합니다."},{"who":"로봇 공학자","text":"(간추림) 반갑게 인사하며, 로봇 공학에 관심 있는 학생들과 이야기하게 되어 기쁘다고 했다."},{"who":"학생","text":"면담을 요청드릴 때 말씀드린 것처럼 오늘은 로봇 공학자가 하는 일과 로봇 공학자가 되기 위해 필요한 태도 같은 것들을 여쭈어보고자 합니다."},{"who":"학생","text":"답변을 정확하게 정리하기 위해 녹음이나 녹화를 해도 괜찮을까요?"},{"who":"로봇 공학자","text":"네, 괜찮습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#2','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C13',1,'mc','auto','「로봇 공학자와의 면담」을 한 목적은 무엇인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X04','K6-2-u2-X01']::text[],false,'{"seq":2,"concept":"K6-2-u2-C13","difficulty":1,"kind":"mc","stem":"「로봇 공학자와의 면담」을 한 목적은 무엇인가요?","options":[{"t":"로봇 공학자가 하는 일과 되기 위해 필요한 태도를 알아보려고","correct":true},{"t":"로봇 공학자에게 로봇을 선물 받기 위해서","mis":"K6-2-u2-X07"},{"t":"로봇 공학자의 사는 곳과 나이를 알아보기 위해서","mis":"K6-2-u2-X04"},{"t":"누가 로봇을 더 잘 아는지 겨루기 위해서","mis":"K6-2-u2-X01"}],"explanation":["학생은 면담 열기에서 오늘 여쭈어볼 것을 밝혔어요.","로봇 공학자가 하는 일과 필요한 태도가 목적이에요.","면담 목적은 면담 열기에서 분명히 말해요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"안녕하세요? 만나 뵙게 되어 반갑습니다. 저희는 ○○초등학교 6학년 학생들입니다. 바쁘실 텐데 귀한 시간 내어 면담에 참여해 주셔서 감사합니다."},{"who":"로봇 공학자","text":"(간추림) 반갑게 인사하며, 로봇 공학에 관심 있는 학생들과 이야기하게 되어 기쁘다고 했다."},{"who":"학생","text":"면담을 요청드릴 때 말씀드린 것처럼 오늘은 로봇 공학자가 하는 일과 로봇 공학자가 되기 위해 필요한 태도 같은 것들을 여쭈어보고자 합니다."},{"who":"학생","text":"답변을 정확하게 정리하기 위해 녹음이나 녹화를 해도 괜찮을까요?"},{"who":"로봇 공학자","text":"네, 괜찮습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#3','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',1,'mc','auto','후속 질문의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C5","difficulty":1,"kind":"mc","stem":"후속 질문의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"면담 대상자의 대답을 듣고 더 자세히 알려고 이어서 하는 질문","correct":true},{"t":"면담을 시작하기 전에 미리 적어 둔 질문","mis":"K6-2-u2-X06"},{"t":"면담이 끝난 뒤 친구에게 하는 질문","mis":"K6-2-u2-X05"},{"t":"대답과 상관없이 다음 차례에 읽는 질문","mis":"K6-2-u2-X06"}],"explanation":["후속 질문은 대답을 듣고 나서 생겨요.","앞선 답변과 이어져 더 자세히 알려고 묻는 질문이에요.","그래서 대답을 끝까지 잘 들어야 해요."],"asset":{"type":"passage","lines":["후속 질문은 면담 대상자의 대답을 듣고","더 자세히 알려고 이어서 하는 질문을 말해요."],"title":"『국어』 91쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#4','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',1,'ox','auto','면담 열기에서 「바쁘실 텐데 귀한 시간 내어 면담에 참여해 주셔서 감사합니다.」라고 한 것은 예의를 지키려고 한 말이에요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":4,"concept":"K6-2-u2-C6","difficulty":1,"kind":"ox","stem":"면담 열기에서 「바쁘실 텐데 귀한 시간 내어 면담에 참여해 주셔서 감사합니다.」라고 한 것은 예의를 지키려고 한 말이에요.","answer":"O","reason_options":[{"t":"시간을 내어 준 면담 대상자에게 감사하는 마음을 표현했기 때문에","correct":true},{"t":"면담 목적을 설명하는 말이기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["『국어』 91쪽에서 예의를 지키려고 한 말을 찾았어요.","「만나 뵙게 되어 반갑습니다.」도 예의를 지킨 말이에요.","목적 설명은 그 뒤에 따로 했어요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"안녕하세요? 만나 뵙게 되어 반갑습니다. 저희는 ○○초등학교 6학년 학생들입니다. 바쁘실 텐데 귀한 시간 내어 면담에 참여해 주셔서 감사합니다."},{"who":"로봇 공학자","text":"(간추림) 반갑게 인사하며, 로봇 공학에 관심 있는 학생들과 이야기하게 되어 기쁘다고 했다."},{"who":"학생","text":"면담을 요청드릴 때 말씀드린 것처럼 오늘은 로봇 공학자가 하는 일과 로봇 공학자가 되기 위해 필요한 태도 같은 것들을 여쭈어보고자 합니다."},{"who":"학생","text":"답변을 정확하게 정리하기 위해 녹음이나 녹화를 해도 괜찮을까요?"},{"who":"로봇 공학자","text":"네, 괜찮습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#5','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',2,'mc','auto','학생이 「로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?」라고 물은 것은 어떤 질문인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"학생이 「로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?」라고 물은 것은 어떤 질문인가요?","options":[{"t":"앞선 대답에 이어서 더 자세히 알려고 한 후속 질문","correct":true},{"t":"면담 목적에서 벗어나 다른 이야기로 바꾼 질문","mis":"K6-2-u2-X07"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 마무리하며 감사를 전하는 질문","mis":"K6-2-u2-X05"}],"explanation":["로봇 공학자는 프로그램을 만들고 여러 번 시험한다고 답했어요.","학생은 그 대답을 듣고 「여러 번」의 까닭이 궁금해졌어요.","대답을 붙들어 이어서 물었으니 후속 질문이에요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"로봇 공학자가 로봇을 만들 때 가장 먼저 해야 하는 일은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 로봇이 풀어야 할 문제부터 정한다. 사람을 도울지, 위험한 곳에 대신 갈지 정한 뒤 모양과 기능을 설계하고 부품을 고르고, 프로그램을 만들어 여러 번 시험한다."},{"who":"학생","text":"로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 시험하면서 오류를 찾아 고치고 성능을 높여 로봇이 더 정확하고 안전하게 움직이게 하려는 것이다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#6','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C13',2,'match','auto','『국어』 90쪽 (2)처럼 「로봇 공학자와의 면담」에서 학생이 한 질문을 기준에 따라 나누었어요. 바르게 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u2-C13","difficulty":2,"kind":"match","stem":"『국어』 90쪽 (2)처럼 「로봇 공학자와의 면담」에서 학생이 한 질문을 기준에 따라 나누었어요. 바르게 이어 보세요.","pairs":[{"l":"로봇을 만들 때 가장 먼저 해야 하는 일은 무엇인가요?","r":"구체적인 사실에 대한 질문"},{"l":"로봇 공학자가 된 뒤에 가장 보람 있었던 순간은 언제인가요?","r":"생각이나 느낌에 대한 질문"},{"l":"로봇 공학자로서 앞으로 이루고 싶은 목표는 무엇인가요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["로봇을 만드는 차례는 구체적인 사실이에요.","보람 있었던 순간은 생각이나 느낌이에요.","앞으로의 목표와 학생들에게 해 줄 말은 계획이나 당부예요."],"asset":{"type":"passage","lines":["(간추림) 면담 열기 — 인사, 목적(로봇 공학자가 하는 일과 필요한 태도), 녹음·녹화 동의","(간추림) 질문하기 — 가장 먼저 하는 일 → 여러 번 시험하는 까닭","(간추림)   → 가장 보람 있었던 순간 → 앞으로의 목표 → 학생들에게 해 줄 말","(간추림) 면담 마무리하기 — 인상 깊었던 점을 말하고 감사 인사"],"numbered":false,"title":"「로봇 공학자와의 면담」 흐름 — 『국어』 88~89쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#7','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','『국어』 91쪽 「면담 예절 알기」처럼 면담 대상자에게 예의를 지키는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X07']::text[],false,'{"seq":7,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"『국어』 91쪽 「면담 예절 알기」처럼 면담 대상자에게 예의를 지키는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"녹음이나 녹화를 할 때에는 먼저 동의를 구한다","correct":true},{"t":"대답이 길어지면 중간에 끊고 다음 질문으로 넘어간다","mis":"K6-2-u2-X10"},{"t":"면담 목적은 밝히지 않고 바로 질문한다","mis":"K6-2-u2-X07"},{"t":"면담이 끝나면 인사 없이 자료를 정리하러 간다","mis":"K6-2-u2-X10"}],"explanation":["처음에 인사를 바르게 하고 목적을 분명하게 전달해요.","상대의 말을 끝까지 잘 듣고, 녹음·녹화는 동의를 구해요.","면담이 끝나면 감사 인사를 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 대상자에게 면담에 응해 주셔서 감사하다고 표현해야 해."},{"who":"친구 2","text":"면담 목적과 관련 있는 질문을 해야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#8','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','수의사가 되는 방법에 대한 정보를 찾을 때 출처를 믿을 만한 자료는 무엇인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":8,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"수의사가 되는 방법에 대한 정보를 찾을 때 출처를 믿을 만한 자료는 무엇인가요?","options":[{"t":"진로 정보를 안내하는 커리어넷 같은 누리집의 자료","correct":true},{"t":"누가 썼는지 알 수 없는 글","mis":"K6-2-u2-X09"},{"t":"조회 수가 가장 많은 재미있는 영상","mis":"K6-2-u2-X09"},{"t":"검색했을 때 맨 처음 나온 광고 글","mis":"K6-2-u2-X09"}],"explanation":["『국어』 93쪽 도움말은 정보의 출처가 믿을 만한지 확인하라고 해요.","누가 언제 만들었는지 밝혀진 자료를 골라요.","재미나 검색 순서로 고르지 않아요."],"asset":{"type":"passage","lines":["면담 목적 — 내 진로를 더 깊이 이해하려고","면담 대상자 — 수의사 · 면담 방식 — 대면 면담 / 비대면 면담","정보 — 수의사가 되려면 수의학과에서 공부하고 수의사 국가시험에","   합격해야 한다. (출처: 커리어넷)","정보 — 수의사는 반려동물뿐 아니라 가축이나 야생 동물을 돌보기도 한다.","   (출처: 동영상 플랫폼)"],"numbered":false,"title":"자신과 관련짓기 예시 — 『국어』 92~93쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#9','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C13',2,'mc','auto','『국어』 88쪽에서 친구들은 진로와 관련 있는 정보를 누리집과 책에서 찾을 수 있다고 했어요. 이 차시에서 살펴보는, 또 하나의 유용한 정보 수집 방법은 무엇인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X09','K6-2-u2-X01']::text[],false,'{"seq":9,"concept":"K6-2-u2-C13","difficulty":2,"kind":"mc","stem":"『국어』 88쪽에서 친구들은 진로와 관련 있는 정보를 누리집과 책에서 찾을 수 있다고 했어요. 이 차시에서 살펴보는, 또 하나의 유용한 정보 수집 방법은 무엇인가요?","options":[{"t":"그 일을 하는 분을 만나 묻고 답하는 면담","correct":true},{"t":"친구들끼리 모여 그 일을 짐작해 보기","mis":"K6-2-u2-X07"},{"t":"눈에 띄는 광고를 아무거나 많이 보기","mis":"K6-2-u2-X09"},{"t":"그날 있었던 일을 일기로 쓰기","mis":"K6-2-u2-X01"}],"explanation":["누리집 검색과 책 찾아보기도 정보를 얻는 방법이에요.","면담은 그 일을 하는 분에게 직접 생생한 정보를 들을 수 있어요.","그래서 진로 탐색에 유용한 방법이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"누리집에서 진로와 관련 있는 정보를 검색할 수도 있어."},{"who":"친구 2","text":"진로와 관련 있는 책을 찾아볼 수도 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_basic#10','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',3,'essay','teacher','로봇 공학자는 자기가 만든 로봇이 사람들에게 실제로 도움이 되었을 때 가장 큰 보람을 느꼈다고 했어요. 이 대답을 듣고 할 수 있는 후속 질문을 하나 만들고, 그렇게 물은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C5","difficulty":3,"kind":"essay","stem":"로봇 공학자는 자기가 만든 로봇이 사람들에게 실제로 도움이 되었을 때 가장 큰 보람을 느꼈다고 했어요. 이 대답을 듣고 할 수 있는 후속 질문을 하나 만들고, 그렇게 물은 까닭을 쓰세요.","answer_guide":{"answer":"예: 후속 질문 — 「그 로봇은 사람들에게 어떤 도움을 주었나요?」 까닭 — 로봇 공학자가 말한 도움이 무엇인지 더 자세히 알고 싶기 때문이다.","scoring_points":["앞선 대답(실제로 도움이 된 로봇)과 이어지는 질문인가","더 자세히 알려는 질문인가","물은 까닭을 썼는가"]},"explanation":["후속 질문은 대답 속의 말을 붙들어 만들어요.","「도움」이 무엇이었는지 더 물을 수 있어요.","그러면 대화가 자연스럽게 이어져요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"(간추림) 여러 번 고쳐 가며 로봇이 완성된다는 점이 흥미로웠다고 말한 뒤) 그렇다면 로봇 공학자가 된 뒤에 가장 보람 있었던 순간은 언제인가요?"},{"who":"로봇 공학자","text":"(간추림) 자기가 만든 로봇이 사람들에게 실제로 도움이 되었을 때 가장 큰 보람을 느꼈다."},{"who":"학생","text":"그렇군요. 로봇 공학자로서 앞으로 이루고 싶은 목표는 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 아픈 사람이나 어르신을 돕는 로봇, 재난 현장에서 위험한 일을 대신하는 로봇처럼 사람들에게 실제적인 도움을 주는 로봇을 만들고 싶다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#1','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C13',2,'mc','auto','「로봇 공학자와의 면담」으로 학생들이 새롭게 안 점이 아닌 것은 무엇인가요?',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":1,"concept":"K6-2-u2-C13","difficulty":2,"kind":"mc","stem":"「로봇 공학자와의 면담」으로 학생들이 새롭게 안 점이 아닌 것은 무엇인가요?","options":[{"t":"로봇 공학자의 나이와 사는 곳","correct":true},{"t":"로봇을 만드는 과정","mis":"K6-2-u2-X04"},{"t":"일을 하며 느끼는 보람","mis":"K6-2-u2-X04"},{"t":"앞으로 이루고 싶은 목표","mis":"K6-2-u2-X04"}],"explanation":["학생들은 필요한 공부, 만드는 과정, 보람, 목표를 새롭게 알았어요.","나이와 사는 곳은 묻지도 않았어요.","개인 정보는 면담에서 묻지 않아요."],"asset":{"type":"passage","lines":["(간추림) 면담 열기 — 인사, 목적(로봇 공학자가 하는 일과 필요한 태도), 녹음·녹화 동의","(간추림) 질문하기 — 가장 먼저 하는 일 → 여러 번 시험하는 까닭","(간추림)   → 가장 보람 있었던 순간 → 앞으로의 목표 → 학생들에게 해 줄 말","(간추림) 면담 마무리하기 — 인상 깊었던 점을 말하고 감사 인사"],"numbered":false,"title":"「로봇 공학자와의 면담」 흐름 — 『국어』 88~89쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#2','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',2,'ox','auto','면담할 때에는 미리 준비한 질문만 차례대로 해야 하고, 대화 중에 궁금한 점이 생겨도 묻지 않아요.',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":2,"concept":"K6-2-u2-C5","difficulty":2,"kind":"ox","stem":"면담할 때에는 미리 준비한 질문만 차례대로 해야 하고, 대화 중에 궁금한 점이 생겨도 묻지 않아요.","answer":"X","reason_options":[{"t":"대답을 듣고 궁금한 점이 생기면 후속 질문을 할 수 있기 때문에","correct":true},{"t":"질문지에 없는 질문을 하면 예의에 어긋나기 때문에","mis":"K6-2-u2-X06"}],"mis":"K6-2-u2-X06","explanation":["미리 준비한 질문은 면담의 길잡이예요.","대화하며 궁금한 점이 생기면 후속 질문을 해요.","그래서 X예요."],"asset":{"type":"passage","lines":["후속 질문은 면담 대상자의 대답을 듣고","더 자세히 알려고 이어서 하는 질문을 말해요."],"title":"『국어』 91쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#3','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C13',3,'mc','auto','로봇 공학자가 되고 싶은 학생들에게 로봇 공학자가 해 준 말의 핵심은 무엇인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":3,"concept":"K6-2-u2-C13","difficulty":3,"kind":"mc","stem":"로봇 공학자가 되고 싶은 학생들에게 로봇 공학자가 해 준 말의 핵심은 무엇인가요?","options":[{"t":"기술과 함께, 로봇이 생활에 주는 영향이 옳은지 따져 보는 태도가 필요하다","correct":true},{"t":"기술만 잘 배우면 다른 것은 생각하지 않아도 된다","mis":"K6-2-u2-X07"},{"t":"로봇은 위험하니 만들지 않는 것이 좋다","mis":"K6-2-u2-X07"},{"t":"어른이 될 때까지 로봇에 관심을 두지 말아야 한다","mis":"K6-2-u2-X07"}],"explanation":["로봇 공학자는 기술과 함께 생활에 주는 영향을 생각하라고 했어요.","그것이 옳은지 따져 보는 태도가 필요하다고 했어요.","학생도 이 점이 인상 깊었다고 마무리했어요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"마지막으로, 로봇 공학자가 되고 싶은 학생들에게 해 주고 싶으신 말씀이 있나요?"},{"who":"로봇 공학자","text":"(간추림) 기술을 배우는 것과 함께, 로봇이 우리 생활에 어떤 영향을 주는지 생각하고 그것이 옳은지 따져 보는 태도가 필요하다. 로봇과 기계에 관심을 갖고 동아리나 만들기 활동에 참여해 보면 좋다."},{"who":"학생","text":"로봇을 만들 때 기술뿐만 아니라 우리 생활에 어떤 영향을 줄지도 생각해야 한다는 점이 인상 깊었습니다. (간추림) 오늘 말씀으로 많이 알게 되었다며 감사 인사를 했다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#4','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',3,'mc','auto','후속 질문을 하면 좋은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X04']::text[],false,'{"seq":4,"concept":"K6-2-u2-C5","difficulty":3,"kind":"mc","stem":"후속 질문을 하면 좋은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"궁금한 점을 더 깊이 이해하고 필요한 정보를 구체적으로 얻으며 대화가 자연스럽게 이어진다","correct":true},{"t":"준비한 질문을 하지 않아도 되어 면담이 빨리 끝난다","mis":"K6-2-u2-X07"},{"t":"면담 대상자의 개인 정보를 더 많이 알 수 있다","mis":"K6-2-u2-X04"},{"t":"면담 목적과 상관없는 이야기를 마음껏 할 수 있다","mis":"K6-2-u2-X07"}],"explanation":["『국어』 91쪽 예시 답안을 떠올려요.","후속 질문으로 궁금한 점을 더 깊이, 구체적으로 알 수 있어요.","앞선 답변과 이어져 대화도 자연스러워요."],"asset":{"type":"passage","lines":["후속 질문은 면담 대상자의 대답을 듣고","더 자세히 알려고 이어서 하는 질문을 말해요."],"title":"『국어』 91쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#5','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'error','auto','수의사를 면담하려고 만든 질문이에요. 「내 진로를 더 깊이 이해하려고」라는 면담 목적에 어울리지 않아 고쳐야 할 질문을 고르세요.',ARRAY['K6-2-u2-X07','K6-2-u2-X08']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"수의사를 면담하려고 만든 질문이에요. 「내 진로를 더 깊이 이해하려고」라는 면담 목적에 어울리지 않아 고쳐야 할 질문을 고르세요.","options":[{"t":"「좋아하는 음식은 무엇인가요?」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"「주로 어떤 동물을 치료하나요?」","mis":"K6-2-u2-X07"},{"t":"「동물을 치료할 때 어떤 마음이 드나요?」","mis":"K6-2-u2-X08"}],"explanation":["질문을 만들면 먼저 면담 목적에 맞는지 확인해요.","좋아하는 음식은 수의사라는 진로를 이해하는 것과 멀어요.","친구도 「두 번째 질문이 목적에 어울리지 않아 고쳤어.」라고 했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"내가 만든 두 번째 질문이 면담 목적에 어울리지 않는 질문 같아서 고쳤어."},{"who":"친구 2","text":"면담 대상자가 이해할 수 있게 명료한 표현으로 고쳐 보았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#6','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'mc','auto','「면담 대상자가 이해할 수 있게 명료한 표현으로 고쳐 보았어.」 명료하게 고친 질문으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X08']::text[],false,'{"seq":6,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「면담 대상자가 이해할 수 있게 명료한 표현으로 고쳐 보았어.」 명료하게 고친 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"「동물을 치료하실 때 가장 힘든 점은 무엇인가요?」","correct":true},{"t":"「그거 할 때 뭐가 제일 그랬어요?」","mis":"K6-2-u2-X10"},{"t":"「동물을 치료하는 일, 그러니까 그 일을 하면서, 혹시 힘들거나 어렵거나 아니면 다른 느낌이 드신 적이 있나요?」","mis":"K6-2-u2-X10"},{"t":"「힘들죠?」","mis":"K6-2-u2-X08"}],"explanation":["명료한 질문은 무엇을 묻는지 분명해요.","「그거」, 「그랬어요」처럼 흐릿한 말을 쓰지 않아요.","질문은 짧고 분명하게 다듬어요."],"asset":{"type":"passage","lines":["● 면담 목적에 맞게 질문을 만들었나요?","● 면담 대상자에게 예의를 갖추어 표현했나요?","● 면담 대상자가 이해할 수 있는 명료한 표현을 사용했나요?"],"numbered":false,"title":"자신이 만든 질문 스스로 확인하기 — 『국어』 93쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#7','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C13',3,'match','auto','『국어』 90쪽 (1)처럼 「로봇 공학자와의 면담」에서 단계를 표시했어요. 학생의 말과 단계를 바르게 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C13","difficulty":3,"kind":"match","stem":"『국어』 90쪽 (1)처럼 「로봇 공학자와의 면담」에서 단계를 표시했어요. 학생의 말과 단계를 바르게 이어 보세요.","pairs":[{"l":"「답변을 정확하게 정리하기 위해 녹음이나 녹화를 해도 괜찮을까요?」","r":"면담 열기"},{"l":"「로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?」","r":"질문하기"},{"l":"「로봇을 만들 때 기술뿐만 아니라 우리 생활에 어떤 영향을 줄지도 생각해야 한다는 점이 인상 깊었습니다.」","r":"면담 마무리하기"}],"mis":"K6-2-u2-X05","explanation":["녹음·녹화 동의는 면담 열기에서 구해요.","궁금한 점을 묻는 것은 질문하기예요.","인상 깊었던 점을 말하고 감사 인사를 하는 것은 면담 마무리하기예요."],"asset":{"type":"passage","lines":["(간추림) 면담 열기 — 인사, 목적(로봇 공학자가 하는 일과 필요한 태도), 녹음·녹화 동의","(간추림) 질문하기 — 가장 먼저 하는 일 → 여러 번 시험하는 까닭","(간추림)   → 가장 보람 있었던 순간 → 앞으로의 목표 → 학생들에게 해 줄 말","(간추림) 면담 마무리하기 — 인상 깊었던 점을 말하고 감사 인사"],"numbered":false,"title":"「로봇 공학자와의 면담」 흐름 — 『국어』 88~89쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#8','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',4,'essay','teacher','『국어』 92~93쪽처럼 자신의 진로를 떠올려 면담 대상자와 면담 방식을 정하고, 믿을 만한 출처에서 얻은 정보 하나와 그 정보를 바탕으로 만든 질문을 세 기준에 따라 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u2-C6","difficulty":4,"kind":"essay","stem":"『국어』 92~93쪽처럼 자신의 진로를 떠올려 면담 대상자와 면담 방식을 정하고, 믿을 만한 출처에서 얻은 정보 하나와 그 정보를 바탕으로 만든 질문을 세 기준에 따라 하나씩 쓰세요.","answer_guide":{"answer":"예: 면담 대상자 — 제빵사 · 면담 방식 — 대면 면담. 정보 — 제빵사는 빵 반죽과 굽기뿐 아니라 새 빵을 연구하기도 한다(출처: 커리어넷). 구체적인 사실 — 새 빵은 어떤 과정으로 만드시나요? / 생각이나 느낌 — 손님이 빵을 맛있게 드실 때 어떤 마음이 드나요? / 앞으로의 계획이나 당부 — 제빵사가 되고 싶은 학생들에게 해 주실 말씀이 있나요?","scoring_points":["진로와 이어지는 면담 대상자와 방식을 정했는가","정보와 출처를 썼는가","정보를 바탕으로 세 기준의 질문을 하나씩 만들었는가"]},"explanation":["면담 목적은 「내 진로를 더 깊이 이해하려고」예요.","정보의 출처가 믿을 만한지 확인해요.","수집한 정보가 질문을 만드는 데 도움이 되게 해요."],"asset":{"type":"passage","lines":["면담 목적 — 내 진로를 더 깊이 이해하려고","면담 대상자 — 수의사 · 면담 방식 — 대면 면담 / 비대면 면담","정보 — 수의사가 되려면 수의학과에서 공부하고 수의사 국가시험에","   합격해야 한다. (출처: 커리어넷)","정보 — 수의사는 반려동물뿐 아니라 가축이나 야생 동물을 돌보기도 한다.","   (출처: 동영상 플랫폼)"],"numbered":false,"title":"자신과 관련짓기 예시 — 『국어』 92~93쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#9','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',4,'essay','teacher','「로봇 공학자와의 면담」을 읽고 물음에 답하세요. 「면담의 절차를 잘 지키며 진행하고 있나요? 그렇게 생각한 까닭은 무엇인가요?」','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":4,"kind":"essay","stem":"「로봇 공학자와의 면담」을 읽고 물음에 답하세요. 「면담의 절차를 잘 지키며 진행하고 있나요? 그렇게 생각한 까닭은 무엇인가요?」","answer_guide":{"answer":"예: 잘 지키며 진행하고 있다. 면담 열기에서 인사하고 목적을 설명하며 녹음·녹화 동의를 구했고, 질문하기에서 세 기준의 질문과 후속 질문을 했으며, 면담 마무리하기에서 인상 깊었던 점을 말하고 감사 인사를 했기 때문이다.","scoring_points":["절차를 지켰는지 판단을 밝혔는가","면담 열기·질문하기·면담 마무리하기에서 한 일을 근거로 들었는가","면담 자료 속 말에 근거했는가"]},"explanation":["면담 진행하기의 세 단계를 떠올려요.","단계마다 면담 자료에서 근거를 찾아요.","판단과 까닭을 함께 써요."],"asset":{"type":"passage","lines":["(간추림) 면담 열기 — 인사, 목적(로봇 공학자가 하는 일과 필요한 태도), 녹음·녹화 동의","(간추림) 질문하기 — 가장 먼저 하는 일 → 여러 번 시험하는 까닭","(간추림)   → 가장 보람 있었던 순간 → 앞으로의 목표 → 학생들에게 해 줄 말","(간추림) 면담 마무리하기 — 인상 깊었던 점을 말하고 감사 인사"],"numbered":false,"title":"「로봇 공학자와의 면담」 흐름 — 『국어』 88~89쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L05_challenge#10','kor',6,2,'u2','L05','tb_g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',4,'mc','auto','「수의사는 반려동물뿐 아니라 가축이나 야생 동물을 돌보기도 한다.」는 정보를 바탕으로 만든 질문으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X02','K6-2-u2-X04','K6-2-u2-X07']::text[],false,'{"seq":10,"concept":"K6-2-u2-C6","difficulty":4,"kind":"mc","stem":"「수의사는 반려동물뿐 아니라 가축이나 야생 동물을 돌보기도 한다.」는 정보를 바탕으로 만든 질문으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「반려동물이 아닌 가축이나 야생 동물을 돌볼 때는 어떤 점이 다른가요?」","correct":true},{"t":"「수의사는 주로 어떤 동물들을 돌보는 사람인가요?」","mis":"K6-2-u2-X02"},{"t":"「수의사 선생님은 집에서 어떤 동물을 키우시나요?」","mis":"K6-2-u2-X04"},{"t":"「동물을 좋아하셔서 수의사가 되셨나요?」","mis":"K6-2-u2-X07"}],"explanation":["수집한 정보는 질문을 깊게 만드는 바탕이에요.","이미 찾은 내용을 그대로 다시 물으면 새 정보를 얻기 어려워요.","정보를 딛고 그분만 답할 수 있는 것을 물어요."],"asset":{"type":"passage","lines":["면담 목적 — 내 진로를 더 깊이 이해하려고","면담 대상자 — 수의사 · 면담 방식 — 대면 면담 / 비대면 면담","정보 — 수의사가 되려면 수의학과에서 공부하고 수의사 국가시험에","   합격해야 한다. (출처: 커리어넷)","정보 — 수의사는 반려동물뿐 아니라 가축이나 야생 동물을 돌보기도 한다.","   (출처: 동영상 플랫폼)"],"numbered":false,"title":"자신과 관련짓기 예시 — 『국어』 92~93쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#1','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'mc','auto','『국어』 94쪽처럼 면담 방식을 정리했어요. 대면 면담의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X01']::text[],false,'{"seq":1,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"『국어』 94쪽처럼 면담 방식을 정리했어요. 대면 면담의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"면담 대상자를 직접 만나서 서로 얼굴을 마주 보고 대하는 면담","correct":true},{"t":"전자 우편으로 질문을 보내고 답을 받는 면담","mis":"K6-2-u2-X12"},{"t":"스마트폰 영상 통화로 하는 면담","mis":"K6-2-u2-X12"},{"t":"면담 대상자 없이 친구끼리 하는 면담","mis":"K6-2-u2-X01"}],"explanation":["대면 면담은 직접 만나 얼굴을 마주 보고 해요.","직접 만나지 않거나 마주 보지 않으면 비대면 면담이에요.","영상 통화와 전자 우편은 비대면 면담이에요."],"asset":{"type":"passage","lines":["보기: 대면 · 비대면","(    ㉠    ) 면담 — 면담 대상자를 직접 만나서 서로 얼굴을 마주 보고 대하는 면담","(    ㉡    ) 면담 — 면담 대상자를 직접 만나지 않거나 서로 얼굴을 마주 보고","   대하지 않는 면담"],"numbered":false,"title":"면담 방식 정리하기 — 『국어』 94쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#2','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C14',1,'sa','auto','민수네 모둠이 면담하기로 한 주변 인물은 누구인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C14","difficulty":1,"kind":"sa","stem":"민수네 모둠이 면담하기로 한 주변 인물은 누구인지 쓰세요.","answer":["상담 선생님","박○○ 상담 선생님","상담 교사","박 상담 선생님"],"explanation":["민수네 모둠은 우리 학교에서 알아보고 싶은 인물을 이야기했어요.","상담 교사가 꿈인 민수의 이야기로 목적을 정했어요.","그래서 박○○ 상담 선생님을 면담하기로 했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리 학교 학생들을 상담해 주시는 박○○ 상담 선생님은 어떨까? 늘 친절하고 따뜻하게 우리 이야기를 들어 주시잖아."},{"who":"친구 2","text":"(간추림) 면담 방식은 직접 만나는 대면 면담으로 정하고, 박○○ 상담 선생님께 연락드려 면담을 요청하자고 했다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#3','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C8',1,'mc','auto','『국어』 99쪽 역할표에서 ㉯의 일을 하는 역할은 무엇인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":3,"concept":"K6-2-u2-C8","difficulty":1,"kind":"mc","stem":"『국어』 99쪽 역할표에서 ㉯의 일을 하는 역할은 무엇인가요?","options":[{"t":"약속 담당","correct":true},{"t":"진행 담당","mis":"K6-2-u2-X19"},{"t":"질문 담당","mis":"K6-2-u2-X19"},{"t":"정리 담당","mis":"K6-2-u2-X19"}],"explanation":["㉯는 예의를 갖추어 면담 약속을 잡고 모둠원에게 알려요.","날짜, 시간, 장소를 정하는 일이에요.","그래서 약속 담당이에요."],"asset":{"type":"passage","lines":["㉮ 면담의 전 과정을 살피고, 시간을 조정하며 질문하고 면담을 진행한다.","㉯ 예의를 갖추어 면담 약속(날짜, 시간, 장소)을 잡고 모둠원에게 알린다.","㉰ 친구들과 작성한 질문을 모아 의논해 정하고, 예의 바른 표현으로 다듬는다.","㉱ 녹음·녹화 기기를 준비하고, 면담 내용을 녹음·녹화해 친구들과 공유한다.","㉲ 면담 내용을 귀 기울여 듣고 핵심을 메모해, 보고서에 필요한 자료를 정리한다."],"numbered":false,"title":"역할마다 해야 할 일 — 『국어』 99쪽 (6) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#4','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'ox','auto','면담 내용을 녹음·녹화한 자료는 면담 보고서 작성에만 활용해야 해요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":4,"concept":"K6-2-u2-C7","difficulty":1,"kind":"ox","stem":"면담 내용을 녹음·녹화한 자료는 면담 보고서 작성에만 활용해야 해요.","answer":"O","reason_options":[{"t":"면담 대상자의 동의를 얻은 자료라도 인터넷에 올리거나 퍼뜨리면 안 되기 때문에","correct":true},{"t":"녹음·녹화한 자료는 모두의 것이라 어디에 써도 되기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["녹음·녹화하기 전에 먼저 동의를 얻어요.","그 자료는 면담 보고서를 쓸 때에만 써요.","그래서 O예요."],"asset":{"type":"passage","lines":["보기: 목적 · 자료 · 녹음·녹화","● 인터넷이나 책에서 면담에 필요한 (    ㉠    )을/를 찾을 때에는","   면담 (    ㉡    )에 알맞은지 살펴봐야 해.","● 면담 내용을 (    ㉢    )한 자료는 면담 보고서 작성에만 활용해야 해."],"numbered":false,"title":"면담 예절 확인하기 — 『국어』 95쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#5','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',2,'mc','auto','면담 정리하기에서 매체를 활용하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X11','K6-2-u2-X12']::text[],false,'{"seq":5,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"면담 정리하기에서 매체를 활용하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"녹음한 내용을 다시 듣고 중요한 내용을 간추리면서 면담 내용을 정리한다","correct":true},{"t":"녹음한 내용을 누리집에 올려 친구들이 듣게 한다","mis":"K6-2-u2-X11"},{"t":"녹음기를 켜 두고 면담 대상자를 처음 만나 인사한다","mis":"K6-2-u2-X12"},{"t":"면담 전에 누리집에서 자료를 찾는다","mis":"K6-2-u2-X12"}],"explanation":["준비할 때는 인터넷이나 책으로 자료를 찾아요.","진행할 때는 녹음기나 영상 통화를 써요.","정리할 때는 녹음한 내용을 다시 들으며 간추려요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인터넷이나 책에서 면담에 필요한 자료를 찾아 면담을 준비할 수 있어."},{"who":"친구 2","text":"녹음기로 면담 내용을 녹음하며 대면 면담을 진행할 수 있어. 스마트폰으로 영상 통화를 하며 비대면 면담도 할 수 있어."},{"who":"친구 3","text":"그리고 녹음한 내용을 다시 듣고 중요한 내용을 간추리면서 면담 내용을 정리할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#6','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C14',2,'mc','auto','민수네 모둠의 면담 목적은 무엇인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X02','K6-2-u2-X04']::text[],false,'{"seq":6,"concept":"K6-2-u2-C14","difficulty":2,"kind":"mc","stem":"민수네 모둠의 면담 목적은 무엇인가요?","options":[{"t":"상담 교사가 되는 방법과 상담 교사의 역할을 알아보기","correct":true},{"t":"상담 선생님께 고민 상담을 받기","mis":"K6-2-u2-X01"},{"t":"상담실이 몇 층에 있는지 알아보기","mis":"K6-2-u2-X02"},{"t":"상담 선생님의 가족에 대해 알아보기","mis":"K6-2-u2-X04"}],"explanation":["민수는 상담 교사가 되는 것이 꿈이라고 했어요.","현지는 되는 방법과 역할을 알아볼 목적으로 면담하자고 했어요.","모둠이 함께 궁금해하는 것을 목적으로 정했어요."],"asset":{"type":"speech","turns":[{"who":"친구들","text":"(간추림) 상담 교사가 되는 방법과 역할을 알려 주실 분이 누구일지, 상담 선생님은 어떻게 상담 교사가 되셨고 학교에서 어떤 일을 하시는지 궁금하다고 이야기했다."},{"who":"민수","text":"나는 상담 교사가 되는 것이 꿈이야. 내 꿈을 더 자세히 알아보고 싶어서 면담하려고 해."},{"who":"현지","text":"그럼 우리 모둠은 상담 교사가 되는 방법과 상담 교사의 역할을 알아볼 목적으로 면담을 해 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#7','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C8',2,'blank','auto','면담 내용을 정리하는 방법이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#8','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C14',2,'mc','auto','기철이 「저희가 면담 내용을 정확히 남기고자 녹화를 하려는데 괜찮으실까요?」라고 한 것은 무엇을 한 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X08']::text[],false,'{"seq":8,"concept":"K6-2-u2-C14","difficulty":2,"kind":"mc","stem":"기철이 「저희가 면담 내용을 정확히 남기고자 녹화를 하려는데 괜찮으실까요?」라고 한 것은 무엇을 한 것인가요?","options":[{"t":"면담 열기에서 녹음·녹화 동의를 구했다","correct":true},{"t":"면담 마무리하기에서 면담 결과를 확인했다","mis":"K6-2-u2-X05"},{"t":"질문하기에서 구체적인 사실을 물었다","mis":"K6-2-u2-X08"},{"t":"면담 준비하기에서 자료를 찾았다","mis":"K6-2-u2-X05"}],"explanation":["민수가 인사하고 목적을 설명한 뒤 기철이 말했어요.","녹화하기 전에 먼저 허락을 구한 거예요.","면담 열기의 할 일이에요."],"asset":{"type":"speech","turns":[{"who":"민수","text":"안녕하세요? 상담 선생님, 면담을 허락해 주셔서 감사합니다. 상담 교사가 되려면 어떤 준비를 해야 하는지, 상담 교사는 어떤 일을 하는지와 같은 질문을 준비했습니다."},{"who":"기철","text":"저희가 면담 내용을 정확히 남기고자 녹화를 하려는데 괜찮으실까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#9','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C8',2,'match','auto','『국어』 99쪽 역할표를 보고 역할과 해야 할 일을 바르게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C8","difficulty":2,"kind":"match","stem":"『국어』 99쪽 역할표를 보고 역할과 해야 할 일을 바르게 이어 보세요.","pairs":[{"l":"진행 담당","r":"시간을 조정하며 질문하고 면담을 진행한다"},{"l":"매체(녹음·녹화) 담당","r":"녹음·녹화 기기를 준비하고 면담 내용을 녹음·녹화한다"},{"l":"정리 담당","r":"핵심 내용을 메모하고 보고서에 필요한 자료를 정리한다"}],"mis":"K6-2-u2-X19","explanation":["진행 담당은 면담의 전 과정을 살피며 이끌어요.","매체 담당은 기기를 준비하고 녹음·녹화해요.","정리 담당은 메모하고 보고서 자료를 정리해요."],"asset":{"type":"passage","lines":["㉮ 면담의 전 과정을 살피고, 시간을 조정하며 질문하고 면담을 진행한다.","㉯ 예의를 갖추어 면담 약속(날짜, 시간, 장소)을 잡고 모둠원에게 알린다.","㉰ 친구들과 작성한 질문을 모아 의논해 정하고, 예의 바른 표현으로 다듬는다.","㉱ 녹음·녹화 기기를 준비하고, 면담 내용을 녹음·녹화해 친구들과 공유한다.","㉲ 면담 내용을 귀 기울여 듣고 핵심을 메모해, 보고서에 필요한 자료를 정리한다."],"numbered":false,"title":"역할마다 해야 할 일 — 『국어』 99쪽 (6) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_basic#10','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C14',3,'essay','teacher','민수네 모둠처럼 면담을 마무리하는 말을 쓰세요. 면담으로 알게 된 것을 확인하는 말과 감사 인사를 모두 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C14","difficulty":3,"kind":"essay","stem":"민수네 모둠처럼 면담을 마무리하는 말을 쓰세요. 면담으로 알게 된 것을 확인하는 말과 감사 인사를 모두 넣으세요.","answer_guide":{"answer":"예: 오늘 면담으로 상담 교사가 되려면 관련 공부를 하고 임용 시험에 합격해야 한다는 것과, 학생의 고민을 들어 주고 해결 방법을 함께 찾는 일을 하신다는 것을 알았습니다. 바쁘신 가운데 면담을 허락해 주셔서 정말 감사합니다.","scoring_points":["면담으로 알게 된 것을 확인하는 말이 있는가","감사 인사가 있는가","예의 바른 표현을 썼는가"]},"explanation":["면담 마무리하기에서는 결과를 확인해요.","그리고 시간을 내어 주신 분께 감사 인사를 해요.","보고서를 보여 드리겠다는 약속도 좋아요."],"asset":{"type":"speech","turns":[{"who":"민수","text":"(간추림) 면담으로 상담 교사의 역할과 상담 교사가 되는 방법을 잘 알게 되었고, 상담 교사를 꿈꾸는 친구들에게 도움이 될 것 같다고 말했다."},{"who":"민수","text":"바쁘신 가운데 저희에게 면담을 허락해 주셔서 감사합니다. 면담 보고서가 완성되면 다시 연락드려서 보여 드리고 싶습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#1','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',2,'mc','auto','비대면 면담의 예로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X12']::text[],false,'{"seq":1,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"비대면 면담의 예로 알맞은 것은 무엇인가요?","options":[{"t":"스마트폰으로 영상 통화를 하며 하는 면담","correct":true},{"t":"상담실에 찾아가 얼굴을 마주 보고 하는 면담","mis":"K6-2-u2-X12"},{"t":"녹음기를 켜고 마주 앉아 하는 면담","mis":"K6-2-u2-X12"},{"t":"도서관에서 직접 만나 하는 면담","mis":"K6-2-u2-X12"}],"explanation":["비대면 면담은 직접 만나지 않거나 얼굴을 마주 보지 않고 해요.","영상 통화, 화상 회의, 전자 우편이 그 예예요.","녹음기를 켜고 마주 앉으면 대면 면담이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인터넷이나 책에서 면담에 필요한 자료를 찾아 면담을 준비할 수 있어."},{"who":"친구 2","text":"녹음기로 면담 내용을 녹음하며 대면 면담을 진행할 수 있어. 스마트폰으로 영상 통화를 하며 비대면 면담도 할 수 있어."},{"who":"친구 3","text":"그리고 녹음한 내용을 다시 듣고 중요한 내용을 간추리면서 면담 내용을 정리할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#2','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C14',2,'ox','auto','면담을 요청할 때에는 면담 목적과 대강의 질문 내용을 면담 대상자에게 미리 알려 드리는 것이 좋아요.',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":2,"concept":"K6-2-u2-C14","difficulty":2,"kind":"ox","stem":"면담을 요청할 때에는 면담 목적과 대강의 질문 내용을 면담 대상자에게 미리 알려 드리는 것이 좋아요.","answer":"O","reason_options":[{"t":"면담 대상자가 무엇을 답할지 미리 생각해 둘 수 있기 때문에","correct":true},{"t":"질문 내용은 면담 당일까지 비밀로 해야 하기 때문에","mis":"K6-2-u2-X03"}],"mis":"K6-2-u2-X03","explanation":["『국어』 99쪽 도움말에 나온 내용이에요.","요청할 때에는 예의를 지키고 날짜, 시간, 장소를 함께 정해요.","목적과 대강의 질문을 알려 드리면 준비하시기 좋아요."],"asset":{"type":"passage","lines":["면담을 요청할 때에는 예의를 지켜야 해요.","면담 목적과 대강의 질문 내용을 면담 대상자에게 미리 알려 주는 것이 좋아요."],"title":"『국어』 99쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#3','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C14',3,'mc','auto','민수네 모둠이 박○○ 상담 선생님을 면담 대상자로 정한 것이 알맞은 까닭은 무엇인가요?',ARRAY['K6-2-u2-X20','K6-2-u2-X12']::text[],false,'{"seq":3,"concept":"K6-2-u2-C14","difficulty":3,"kind":"mc","stem":"민수네 모둠이 박○○ 상담 선생님을 면담 대상자로 정한 것이 알맞은 까닭은 무엇인가요?","options":[{"t":"목적에 맞고, 연락할 수 있으며 학생들과 면담이 가능한 분이기 때문","correct":true},{"t":"텔레비전에 나오는 가장 유명한 상담 전문가이기 때문","mis":"K6-2-u2-X20"},{"t":"연락이 닿지 않아도 목적에만 맞으면 되기 때문","mis":"K6-2-u2-X20"},{"t":"대면 면담이라 면담 방식을 따로 정하지 않아도 되기 때문","mis":"K6-2-u2-X12"}],"explanation":["대상자는 목적에 맞아야 해요.","또 학생들과 면담이 가능하고 우리가 연락할 수 있는 분이어야 해요.","평소 친절하게 상담해 주시는 우리 학교 선생님이라 알맞아요."],"asset":{"type":"passage","lines":["면담 대상자를 정할 때에는 학생들과 면담이 가능한 분인지가 중요해요.","또 우리가 연락할 수 있는 주변 인물인지 생각해 봐요."],"title":"『국어』 97쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#4','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',3,'mc','auto','비대면 면담을 할 때 미리 챙겨야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X21','K6-2-u2-X07']::text[],false,'{"seq":4,"concept":"K6-2-u2-C7","difficulty":3,"kind":"mc","stem":"비대면 면담을 할 때 미리 챙겨야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"기기 연결 확인 · 카메라 렌즈 보며 말하기 · 말하지 않을 때 마이크 끄기","correct":true},{"t":"얼굴을 마주하지 않으니 인사와 목적 설명은 생략한다","mis":"K6-2-u2-X21"},{"t":"화면 너머라서 녹화는 동의를 구하지 않고 해도 된다","mis":"K6-2-u2-X21"},{"t":"준비한 질문 없이 그때그때 떠오르는 대로 묻는다","mis":"K6-2-u2-X07"}],"explanation":["비대면 면담도 면담 대상자를 만나는 자리예요.","기기 연결, 카메라 렌즈, 마이크를 점검해요.","인사와 녹음·녹화 동의도 대면 면담과 똑같이 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#5','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',3,'error','auto','면담에서 매체를 고려할 때 주의할 점을 말했어요. 잘못된 말을 고르세요.',ARRAY['K6-2-u2-X11','K6-2-u2-X09']::text[],false,'{"seq":5,"concept":"K6-2-u2-C7","difficulty":3,"kind":"error","stem":"면담에서 매체를 고려할 때 주의할 점을 말했어요. 잘못된 말을 고르세요.","options":[{"t":"「동의를 얻어 녹화했으니 면담 영상을 학급 누리집에 올려도 돼.」","correct":true,"mis_target":"K6-2-u2-X11"},{"t":"「녹음·녹화하기 전에 먼저 면담 대상자의 동의를 얻어야 해.」","mis":"K6-2-u2-X11"},{"t":"「인터넷에서 찾은 자료는 면담 목적에 알맞은지 살펴봐야 해.」","mis":"K6-2-u2-X09"}],"explanation":["녹음·녹화하기 전에 동의를 얻어요.","동의를 얻은 자료라도 인터넷에 올리거나 퍼뜨리면 안 돼요.","면담 보고서를 쓸 때에만 활용해요."],"asset":{"type":"passage","lines":["여러 가지 매체를 고려해 면담 내용을 녹음·녹화할 때에는","먼저 면담 대상자의 동의를 얻어야 해요.","면담 대상자의 동의를 얻어서 녹음·녹화한 자료는","인터넷에 올리거나 다른 사람에게 퍼뜨리면 안 돼요."],"title":"『국어』 95쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#6','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C14',3,'mc','auto','민수네 모둠이 매체로 찾은 자료를 확인할 때 물어볼 것이 아닌 것은 무엇인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":6,"concept":"K6-2-u2-C14","difficulty":3,"kind":"mc","stem":"민수네 모둠이 매체로 찾은 자료를 확인할 때 물어볼 것이 아닌 것은 무엇인가요?","options":[{"t":"가장 재미있어 보이는 자료인가요?","correct":true},{"t":"믿을 만한 곳에서 얻은 자료인가요?","mis":"K6-2-u2-X09"},{"t":"면담 목적과 관련 있는 자료인가요?","mis":"K6-2-u2-X09"},{"t":"질문을 만들 때 도움이 되는 자료인가요?","mis":"K6-2-u2-X09"}],"explanation":["자료를 찾으면 세 가지로 확인해요.","믿을 만한가, 목적과 관련 있는가, 질문에 도움이 되는가예요.","재미는 자료를 고르는 기준이 아니에요."],"asset":{"type":"passage","lines":["● 믿을 만한 곳에서 얻은 자료인가요?","● 면담 목적과 관련 있는 자료인가요?","● 질문을 만들 때 도움이 되는 자료인가요?"],"numbered":false,"title":"찾은 자료 확인하기 — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#7','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',3,'mc','auto','면담 내용을 정리하는 네 가지 방법 가운데에서 「세부적인 내용은 일반적인 어휘로 바꾸어 쓴다」에 해당하는 것은 무엇인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":7,"concept":"K6-2-u2-C8","difficulty":3,"kind":"mc","stem":"면담 내용을 정리하는 네 가지 방법 가운데에서 「세부적인 내용은 일반적인 어휘로 바꾸어 쓴다」에 해당하는 것은 무엇인가요?","options":[{"t":"대체","correct":true},{"t":"삭제","mis":"K6-2-u2-X13"},{"t":"선택","mis":"K6-2-u2-X13"},{"t":"구성","mis":"K6-2-u2-X13"}],"explanation":["삭제는 중요하지 않은 정보를 지우는 방법이에요.","대체는 세부적인 내용을 일반적인 어휘로 바꾸는 방법이에요.","선택은 중요한 정보를 고르고, 구성은 일반적인 진술을 만들어 써요."],"asset":{"type":"passage","lines":["삭제 — 중요하지 않은 정보는 삭제한다.","대체 — 세부적인 내용은 일반적인 어휘로 대체한다.","선택 — 많은 내용 가운데에서 중요한 정보를 선택한다.","구성 — 명확하지 않은 내용은 일반적인 진술을 만들어 쓴다."],"numbered":false,"title":"면담 내용을 정리하는 네 가지 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#8','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',4,'mc','auto','민수네 모둠이 정리한 면담 내용에서 잘한 점으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":8,"concept":"K6-2-u2-C8","difficulty":4,"kind":"mc","stem":"민수네 모둠이 정리한 면담 내용에서 잘한 점으로 알맞은 것은 무엇인가요?","options":[{"t":"답변을 그대로 옮기지 않고 중요한 내용을 네 가지로 짧게 간추렸다","correct":true},{"t":"상담 선생님의 말씀을 한 글자도 빼지 않고 받아 적었다","mis":"K6-2-u2-X13"},{"t":"「좋은 면담이었다.」라고 한 줄로 뭉뚱그렸다","mis":"K6-2-u2-X13"},{"t":"답변의 뜻을 바꾸어 더 멋있게 고쳐 썼다","mis":"K6-2-u2-X13"}],"explanation":["정리는 짧게, 불필요한 내용은 덜고 중요한 내용만 남겨요.","민수네 모둠은 첫째~넷째로 묶어 간추렸어요.","자기 말로 쓰되 답변의 뜻은 바꾸지 않아요."],"asset":{"type":"passage","lines":["면담 열기 — 상담 교사가 되는 방법과 역할을 알아보려고 면담을 했다.","질문하기 — 첫째, 관련 공부를 하고 자격증을 따서 임용 시험에 합격해야 한다.","   둘째, 학생의 고민을 들어 주고 해결 방법을 찾도록 도우며 학교생활을 돕는다.","   셋째, 상담 교사로 일하며 정신적으로 힘들 때가 많다.","   넷째, 고민 해결에 도움을 줄 때 가장 큰 보람을 느끼며, 전망은 매우 밝다.","면담 마무리하기 — 공감 능력과 끈기가 필요한 직업임을 알았다."],"numbered":false,"title":"민수네 모둠이 정리한 면담 내용 — 『국어』 101쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#9','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C14',4,'essay','teacher','민수네 모둠이 찾은 자료 가운데 하나를 골라, 그 자료를 바탕으로 상담 선생님께 할 질문을 두 개 만드세요. 만든 질문이 곤란한 질문이나 개인 정보에 대한 질문이 아닌지, 면담 목적에 알맞은지도 확인해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C14","difficulty":4,"kind":"essay","stem":"민수네 모둠이 찾은 자료 가운데 하나를 골라, 그 자료를 바탕으로 상담 선생님께 할 질문을 두 개 만드세요. 만든 질문이 곤란한 질문이나 개인 정보에 대한 질문이 아닌지, 면담 목적에 알맞은지도 확인해 쓰세요.","answer_guide":{"answer":"예: 고른 자료 — 상담 교사의 전망(마음 건강이 중요해지면서 상담 교사를 찾는 학교가 더 많아질 것이다). 질문 1 — 「마음 건강이 중요해지면서 상담 교사의 일은 어떻게 달라지고 있나요?」 질문 2 — 「앞으로 상담 교사가 되려는 학생은 무엇을 준비하면 좋을까요?」 확인 — 두 질문 모두 상담 교사가 되는 방법과 역할을 알아보는 목적에 맞고, 곤란하거나 개인 정보를 묻는 질문이 아니다.","scoring_points":["자료를 바탕으로 질문 두 개를 만들었는가","면담 목적(되는 방법과 역할)에 맞는가","곤란한 질문·개인 정보 질문인지 확인했는가"]},"explanation":["찾은 자료는 질문을 만드는 바탕이에요.","면담 대상자가 곤란해할 질문이나 개인 정보 질문은 빼요.","목적에 알맞은지 마지막으로 확인해요."],"asset":{"type":"passage","lines":["인터넷(주니어 커리어넷 누리집) — 상담 교사가 되는 방법: 심리학, 교육학 같은","   학문을 전공한 뒤에 전문 지식을 쌓는다.","책(어린이 진로 백과) — 상담 교사의 역할: 학생들의 고민을 들어 주고","   해결 방법을 함께 찾아 준다.","태블릿 피시(어린이 ○○일보) — 상담 교사의 전망: 마음 건강이 중요해지면서","   상담 교사를 찾는 학교가 더 많아질 것이다."],"numbered":false,"title":"매체를 고려하여 찾은 자료 — 『국어』 98쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L07_challenge#10','kor',6,2,'u2','L07','tb_g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',4,'essay','teacher','우리 모둠이 비대면 면담을 한다고 생각해 보세요. 면담 준비하기·진행하기·정리하기에서 매체를 어떻게 활용할지와 주의할 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C7","difficulty":4,"kind":"essay","stem":"우리 모둠이 비대면 면담을 한다고 생각해 보세요. 면담 준비하기·진행하기·정리하기에서 매체를 어떻게 활용할지와 주의할 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 준비하기 — 인터넷과 책에서 면담 목적과 관련 있는 자료만 찾고, 화상 회의 기기 연결을 미리 확인한다. 진행하기 — 화상 회의로 면담하며 카메라 렌즈를 보고 말하고, 녹화하기 전에 먼저 동의를 얻는다. 정리하기 — 녹화한 내용을 다시 보며 중요한 내용을 간추리고, 녹화 자료는 보고서를 쓸 때에만 쓰고 퍼뜨리지 않는다.","scoring_points":["세 절차마다 매체 활용 방법을 썼는가","동의 얻기·퍼뜨리지 않기 등 주의할 점을 썼는가","비대면 면담에 맞는 준비(기기·카메라·마이크)를 썼는가"]},"explanation":["절차에 따라 매체의 쓰임이 달라요.","녹음·녹화는 동의를 얻고 보고서에만 써요.","비대면이라도 준비와 예절은 똑같이 챙겨요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인터넷이나 책에서 면담에 필요한 자료를 찾아 면담을 준비할 수 있어."},{"who":"친구 2","text":"녹음기로 면담 내용을 녹음하며 대면 면담을 진행할 수 있어. 스마트폰으로 영상 통화를 하며 비대면 면담도 할 수 있어."},{"who":"친구 3","text":"그리고 녹음한 내용을 다시 듣고 중요한 내용을 간추리면서 면담 내용을 정리할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#1','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'mc','auto','『국어』 102쪽 (2)에서 자신의 면담 과정을 돌아보며 정리하는 세 가지는 무엇인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":1,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"『국어』 102쪽 (2)에서 자신의 면담 과정을 돌아보며 정리하는 세 가지는 무엇인가요?","options":[{"t":"잘한 점 · 보완할 점 · 더 알고 싶은 점","correct":true},{"t":"좋았던 기분 · 싫었던 기분 · 배고팠던 때","mis":"K6-2-u2-X14"},{"t":"잘한 친구 · 못한 친구 · 빠진 친구","mis":"K6-2-u2-X14"},{"t":"면담 대상자의 옷차림 · 목소리 · 표정","mis":"K6-2-u2-X14"}],"explanation":["자신의 면담 과정은 잘한 점, 보완할 점, 더 알고 싶은 점으로 돌아봐요.","모둠의 과정은 잘한 점, 보완할 점, 다음 면담에서 실천할 점으로 돌아봐요.","기분이나 겉모습이 아니라 면담 절차를 돌아봐요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 면담 목적에 맞는 질문을 잘 만들었다.","보완할 점 — 면담을 마무리하고 난 뒤에 면담 대상자에게 감사 인사를","   제대로 못 했다.","더 알고 싶은 점 — 상담 교사가 꿈인 친구들에게 도움이 되는 책이 무엇인지 궁금하다."],"numbered":false,"title":"자신의 면담 과정 정리 — 『국어』 102쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#2','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C15',1,'sa','auto','「상담 교사, 마음의 길을 밝히는 사람들」에서 하늘 모둠의 면담은 얼마 동안 진행되었는지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C15","difficulty":1,"kind":"sa","stem":"「상담 교사, 마음의 길을 밝히는 사람들」에서 하늘 모둠의 면담은 얼마 동안 진행되었는지 쓰세요.","answer":["한 시간","한 시간 정도","1시간","1시간 정도"],"explanation":["보고서 가운데 부분 첫머리에 나와요.","면담은 한 시간 정도 진행했어요.","그리고 주요 내용을 네 가지로 요약했어요."],"asset":{"type":"passage","lines":["(간추림) 면담은 한 시간 정도 했고, 주요 내용은 네 가지로 요약할 수 있다.","(간추림) 첫째, 되는 과정 — 심리학이나 상담학, 교육학 같은 것을 전공하고","(간추림)   자격증을 따서 교원 임용 시험을 치른다. 고민을 경청하는 자세도 필요하다.","(간추림) 둘째, 하는 일 — 학교생활의 고민을 들어 주고 해결 방법을 찾도록 돕는다.","(간추림) 셋째, 힘든 점 — 정신적으로 힘들 때가 많고, 인내심이 필요하다.","(간추림) 넷째, 보람과 전망 — 고민 해결을 도울 때 가장 보람 있고, 전망이 밝다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 가운데 부분 — 『국어』 104~105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#3','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'mc','auto','면담 보고서의 가운데 부분에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":3,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 보고서의 가운데 부분에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"면담으로 새롭게 안 사실 소개하기","correct":true},{"t":"면담 목적과 면담 대상자 밝히기","mis":"K6-2-u2-X15"},{"t":"면담하고 난 뒤 느낀 점 밝히기","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 개인 정보 소개하기","mis":"K6-2-u2-X04"}],"explanation":["앞부분에는 목적·대상자와 준비 과정을 써요.","가운데 부분에는 면담으로 새롭게 안 사실을 소개해요.","뒷부분에는 면담하고 난 뒤 느낀 점을 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#4','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C15',1,'ox','auto','하늘 모둠에서 상담 선생님과 상담한 적이 있는 현지가 약속 담당을 맡아 면담 요청을 쉽게 할 수 있었어요.',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":4,"concept":"K6-2-u2-C15","difficulty":1,"kind":"ox","stem":"하늘 모둠에서 상담 선생님과 상담한 적이 있는 현지가 약속 담당을 맡아 면담 요청을 쉽게 할 수 있었어요.","answer":"O","reason_options":[{"t":"보고서 앞부분에 현지가 약속 담당을 해 주어 요청을 쉽게 할 수 있었다고 썼기 때문에","correct":true},{"t":"보고서 뒷부분에 현지가 진행을 맡았다고 썼기 때문에","mis":"K6-2-u2-X19"}],"mis":"K6-2-u2-X19","explanation":["보고서 앞부분에는 준비 과정과 역할이 나와요.","현지는 상담 선생님과 상담한 적이 있어 약속 담당을 맡았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 우리 모둠은 상담 교사가 되는 방법과 역할을 알아보자는 목적으로","(간추림) 상담 선생님과 면담을 했다.","(간추림) 선생님과 상담한 적이 있는 현지가 약속 담당을 맡아 요청이 쉬웠다.","(간추림) 원주는 질문, 기철이는 매체(녹음·녹화), 현수는 정리,","(간추림) 나는 면담 진행을 맡았다. 각자의 역할을 충실히 하며 면담을 마쳤다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 앞부분 — 『국어』 104쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#5','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','우리 모둠의 보완할 점이 「면담 대상자의 말에 집중하지 않은 친구가 있었다.」였어요. 다음 면담에서 실천할 점으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X19','K6-2-u2-X14']::text[],false,'{"seq":5,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"우리 모둠의 보완할 점이 「면담 대상자의 말에 집중하지 않은 친구가 있었다.」였어요. 다음 면담에서 실천할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"다음 면담에서는 면담 대상자의 말을 경청하기로 약속한다","correct":true},{"t":"집중하지 않은 친구를 다음 면담에서 빼기로 한다","mis":"K6-2-u2-X19"},{"t":"집중하지 않은 친구가 누구인지 보고서에 적는다","mis":"K6-2-u2-X14"},{"t":"면담을 다시는 하지 않기로 한다","mis":"K6-2-u2-X14"}],"explanation":["보완할 점은 사람 탓이 아니라 다음 약속으로 바꾸어요.","『국어』 103쪽 예시는 「경청하기로 약속한다.」예요.","모둠 모두가 지킬 수 있는 약속으로 정해요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 모둠 친구들이 사이좋게 의논해서","   면담 역할을 잘 정했다.","보완할 점 — 면담을 진행할 때 면담 대상자의 말에 집중하지 않은 친구가 있었다.","다음 면담에서 실천할 점(우리 모둠의 약속) — 다음 면담에서는","   면담 대상자의 말을 경청하기로 약속한다."],"numbered":false,"title":"우리 모둠의 면담 과정 정리 — 『국어』 103쪽 (3) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#6','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C15',2,'mc','auto','「상담 교사, 마음의 길을 밝히는 사람들」에서 소개한, 상담 교사가 되고자 할 때 필요한 과정은 무엇인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X13']::text[],false,'{"seq":6,"concept":"K6-2-u2-C15","difficulty":2,"kind":"mc","stem":"「상담 교사, 마음의 길을 밝히는 사람들」에서 소개한, 상담 교사가 되고자 할 때 필요한 과정은 무엇인가요?","options":[{"t":"심리학·상담학·교육학 같은 것을 전공하고 자격증을 따서 임용 시험을 치른다","correct":true},{"t":"간호학을 전공하고 간호사 면허와 보건 교사 자격증을 딴다","mis":"K6-2-u2-X15"},{"t":"대학에서 문헌정보학을 공부하고 사서 자격증을 딴다","mis":"K6-2-u2-X15"},{"t":"따로 공부하지 않아도 마음만 따뜻하면 누구나 된다","mis":"K6-2-u2-X13"}],"explanation":["첫째로 소개한 내용이 상담 교사가 되는 과정이에요.","관련 학문을 전공하고 자격증을 따서 임용 시험을 치러요.","간호학은 보건 교사, 문헌정보학은 사서의 과정이에요."],"asset":{"type":"passage","lines":["(간추림) 면담은 한 시간 정도 했고, 주요 내용은 네 가지로 요약할 수 있다.","(간추림) 첫째, 되는 과정 — 심리학이나 상담학, 교육학 같은 것을 전공하고","(간추림)   자격증을 따서 교원 임용 시험을 치른다. 고민을 경청하는 자세도 필요하다.","(간추림) 둘째, 하는 일 — 학교생활의 고민을 들어 주고 해결 방법을 찾도록 돕는다.","(간추림) 셋째, 힘든 점 — 정신적으로 힘들 때가 많고, 인내심이 필요하다.","(간추림) 넷째, 보람과 전망 — 고민 해결을 도울 때 가장 보람 있고, 전망이 밝다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 가운데 부분 — 『국어』 104~105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#7','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'match','auto','『국어』 105쪽 「면담 보고서의 특징 정리하기」를 떠올리며 보고서의 부분과 담는 내용을 바르게 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":2,"kind":"match","stem":"『국어』 105쪽 「면담 보고서의 특징 정리하기」를 떠올리며 보고서의 부분과 담는 내용을 바르게 이어 보세요.","pairs":[{"l":"면담 보고서 앞부분","r":"면담 목적·대상자를 밝히고 준비 과정을 돌아봄"},{"l":"면담 보고서 가운데 부분","r":"면담으로 새롭게 안 사실을 소개함"},{"l":"면담 보고서 뒷부분","r":"면담하고 난 뒤 느낀 점을 밝힘"}],"mis":"K6-2-u2-X15","explanation":["앞부분은 계획과 준비 상황을 요약해요.","가운데 부분은 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리해요.","뒷부분은 깨달은 점과 달라진 생각을 정리해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#8','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C15',2,'blank','auto','하늘 모둠은 상담 교사의 전망이 밝은 까닭을 이렇게 정리했어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#9','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','면담할 때 자신과 모둠의 태도와 실천 정도를 확인하는 세 항목에 들지 않는 것은 무엇인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":9,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"면담할 때 자신과 모둠의 태도와 실천 정도를 확인하는 세 항목에 들지 않는 것은 무엇인가요?","options":[{"t":"면담 대상자의 옷차림과 목소리를 잘 기억했나요?","correct":true},{"t":"면담 절차에 따라 자신이 맡은 역할을 잘 실천했나요?","mis":"K6-2-u2-X14"},{"t":"예의를 지키며 면담 대상자의 답변을 경청했나요?","mis":"K6-2-u2-X14"},{"t":"매체를 고려해 면담 목적에 맞는 정보를 수집하고 정리했나요?","mis":"K6-2-u2-X14"}],"explanation":["세 항목은 역할 실천, 예의와 경청, 매체를 고려한 정보 수집과 정리예요.","겉모습을 기억했는지는 면담을 돌아보는 기준이 아니에요.","나와 모둠을 따로 확인해요."],"asset":{"type":"passage","lines":["● 면담 절차에 따라 자신이 맡은 역할을 잘 실천했나요?","● 예의를 지키며 면담 대상자의 답변을 경청했나요?","● 면담 과정에서 매체를 고려해 면담 목적에 맞는 정보를 수집하고 정리했나요?","매우 잘함: ●●● · 잘함: ●● · 보통임: ●"],"numbered":false,"title":"면담할 때 자신과 모둠의 태도와 실천 정도 확인하기 — 『국어』 103쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_basic#10','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',3,'essay','teacher','자신이 했던 면담이나 이 단원에서 살펴본 면담 하나를 떠올려, 『국어』 102쪽 (2)처럼 잘한 점, 보완할 점, 더 알고 싶은 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C9","difficulty":3,"kind":"essay","stem":"자신이 했던 면담이나 이 단원에서 살펴본 면담 하나를 떠올려, 『국어』 102쪽 (2)처럼 잘한 점, 보완할 점, 더 알고 싶은 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 면담을 준비할 때 면담 목적에 맞는 질문을 잘 만들었다. 보완할 점 — 면담 대상자의 대답을 끝까지 듣지 않고 다음 질문을 서둘러 했다. 더 알고 싶은 점 — 상담 교사가 학생과 보호자를 함께 만날 때는 어떻게 하는지 궁금하다.","scoring_points":["잘한 점·보완할 점·더 알고 싶은 점을 모두 썼는가","면담 절차(준비·진행·정리)에 근거했는가","보완할 점을 사람 탓이 아니라 자신의 행동으로 썼는가"]},"explanation":["면담 준비하기·진행하기·정리하기를 차례로 떠올려요.","잘한 점과 보완할 점은 자신이 한 일에서 찾아요.","더 알고 싶은 점은 다음 면담의 질문이 돼요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 면담을 준비할 때 책과 인터넷을 활용해서 면담 대상자의 정보를 모았어."},{"who":"친구 2","text":"나는 면담을 진행할 때 면담 대상자에게 먼저 동의를 구하고 녹화를 했어."},{"who":"친구 3","text":"면담 내용을 메모하고 녹화한 자료를 활용해서 면담 내용을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#1','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C15',2,'mc','auto','하늘 모둠에서 기철이가 맡은 역할은 무엇인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":1,"concept":"K6-2-u2-C15","difficulty":2,"kind":"mc","stem":"하늘 모둠에서 기철이가 맡은 역할은 무엇인가요?","options":[{"t":"매체 담당","correct":true},{"t":"질문 담당","mis":"K6-2-u2-X19"},{"t":"정리 담당","mis":"K6-2-u2-X19"},{"t":"약속 담당","mis":"K6-2-u2-X19"}],"explanation":["원주는 질문 담당, 현수는 정리 담당이에요.","기철이는 매체(녹음·녹화) 담당이에요.","보고서를 쓴 친구는 면담 진행을 맡았어요."],"asset":{"type":"passage","lines":["(간추림) 우리 모둠은 상담 교사가 되는 방법과 역할을 알아보자는 목적으로","(간추림) 상담 선생님과 면담을 했다.","(간추림) 선생님과 상담한 적이 있는 현지가 약속 담당을 맡아 요청이 쉬웠다.","(간추림) 원주는 질문, 기철이는 매체(녹음·녹화), 현수는 정리,","(간추림) 나는 면담 진행을 맡았다. 각자의 역할을 충실히 하며 면담을 마쳤다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 앞부분 — 『국어』 104쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#2','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',2,'ox','auto','면담 과정을 성찰할 때에는 면담이 잘되지 않은 까닭을 한 친구의 탓으로 정리하는 것이 좋아요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":2,"concept":"K6-2-u2-C9","difficulty":2,"kind":"ox","stem":"면담 과정을 성찰할 때에는 면담이 잘되지 않은 까닭을 한 친구의 탓으로 정리하는 것이 좋아요.","answer":"X","reason_options":[{"t":"성찰은 잘잘못을 가리는 일이 아니라 절차마다 돌아보고 다음에 실천할 점을 정하는 일이기 때문에","correct":true},{"t":"잘못한 친구를 밝혀야 다음에 그 친구를 뺄 수 있기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["성찰은 절차마다 무엇을 했는지 돌아보는 일이에요.","보완할 점은 모두가 지킬 약속으로 바꾸어요.","그래서 X예요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 모둠 친구들이 사이좋게 의논해서","   면담 역할을 잘 정했다.","보완할 점 — 면담을 진행할 때 면담 대상자의 말에 집중하지 않은 친구가 있었다.","다음 면담에서 실천할 점(우리 모둠의 약속) — 다음 면담에서는","   면담 대상자의 말을 경청하기로 약속한다."],"numbered":false,"title":"우리 모둠의 면담 과정 정리 — 『국어』 103쪽 (3) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#3','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C15',3,'mc','auto','하늘 모둠은 상담 교사로서 일할 때에 힘든 점으로 무엇을 소개했나요?',ARRAY['K6-2-u2-X15','K6-2-u2-X13']::text[],false,'{"seq":3,"concept":"K6-2-u2-C15","difficulty":3,"kind":"mc","stem":"하늘 모둠은 상담 교사로서 일할 때에 힘든 점으로 무엇을 소개했나요?","options":[{"t":"고민을 듣고 도와야 해서 정신적으로 힘들 때가 많고, 인내심이 필요하다","correct":true},{"t":"응급 환자가 생기거나 전염병이 유행할 때 특히 힘들다","mis":"K6-2-u2-X15"},{"t":"책 주문·정리와 독서 행사 준비가 겹쳐 늘 바쁘다","mis":"K6-2-u2-X15"},{"t":"힘든 점은 하나도 없고 보람만 있다고 소개했다","mis":"K6-2-u2-X13"}],"explanation":["셋째로 소개한 내용이 힘든 점이에요.","고민을 듣고 돕는 일이라 정신적으로 힘들 때가 많아요.","응급 환자 이야기는 보건 교사 예시 보고서에 나와요."],"asset":{"type":"passage","lines":["(간추림) 면담은 한 시간 정도 했고, 주요 내용은 네 가지로 요약할 수 있다.","(간추림) 첫째, 되는 과정 — 심리학이나 상담학, 교육학 같은 것을 전공하고","(간추림)   자격증을 따서 교원 임용 시험을 치른다. 고민을 경청하는 자세도 필요하다.","(간추림) 둘째, 하는 일 — 학교생활의 고민을 들어 주고 해결 방법을 찾도록 돕는다.","(간추림) 셋째, 힘든 점 — 정신적으로 힘들 때가 많고, 인내심이 필요하다.","(간추림) 넷째, 보람과 전망 — 고민 해결을 도울 때 가장 보람 있고, 전망이 밝다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 가운데 부분 — 『국어』 104~105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#4','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'mc','auto','보건 교사를 면담하고 쓴 보고서 예시의 문장 ㉮~㉲ 가운데에서 보고서 앞부분에 들어갈 문장끼리 묶은 것은 무엇인가요?',ARRAY['K6-2-u2-X15']::text[],false,'{"seq":4,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"보건 교사를 면담하고 쓴 보고서 예시의 문장 ㉮~㉲ 가운데에서 보고서 앞부분에 들어갈 문장끼리 묶은 것은 무엇인가요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉰, ㉱","mis":"K6-2-u2-X15"},{"t":"㉲","mis":"K6-2-u2-X15"},{"t":"㉯, ㉲","mis":"K6-2-u2-X15"}],"explanation":["앞부분에는 목적과 준비 과정이 들어가요(㉮·㉯).","가운데 부분에는 새롭게 안 사실이 들어가요(㉰·㉱).","뒷부분에는 느낀 점이 들어가요(㉲)."],"asset":{"type":"passage","lines":["(간추림) ㉮ 보건 교사가 되는 방법과 역할을 알아보려고 보건 선생님과 면담을 했다.","(간추림) ㉯ 약속 담당이 보건 선생님께 면담 목적을 말씀드리고 약속을 정했다.","(간추림) ㉰ 보건 교사가 되려면 간호학을 전공하고 간호사 면허와 자격증을 따야 한다.","(간추림) ㉱ 응급 환자가 생기거나 전염병이 유행할 때 특히 힘들다고 한다.","(간추림) ㉲ 전문 지식뿐만 아니라 학생에 대한 사랑이 필요하다는 것을 배웠다."],"numbered":false,"title":"면담 보고서 예시 — 『국어』 106~107쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#5','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'error','auto','친구들이 면담 보고서를 쓰고 서로 살펴보았어요. 잘못 쓴 것을 고르세요.',ARRAY['K6-2-u2-X15']::text[],false,'{"seq":5,"concept":"K6-2-u2-C9","difficulty":3,"kind":"error","stem":"친구들이 면담 보고서를 쓰고 서로 살펴보았어요. 잘못 쓴 것을 고르세요.","options":[{"t":"가운데 부분에 「면담이 정말 재미있었고 신기했다.」라는 느낌만 썼다.","correct":true,"mis_target":"K6-2-u2-X15"},{"t":"앞부분에 면담 목적과 면담 대상자, 모둠의 역할을 썼다.","mis":"K6-2-u2-X15"},{"t":"뒷부분에 면담을 마친 뒤 달라진 생각을 썼다.","mis":"K6-2-u2-X15"}],"explanation":["가운데 부분에는 면담으로 새롭게 안 사실을 써야 해요.","느낌은 뒷부분에 써요.","면담 대상자의 답변을 중심으로 정리해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#6','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C15',3,'mc','auto','「상담 교사, 마음의 길을 밝히는 사람들」의 뒷부분에 담긴 내용으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X15']::text[],false,'{"seq":6,"concept":"K6-2-u2-C15","difficulty":3,"kind":"mc","stem":"「상담 교사, 마음의 길을 밝히는 사람들」의 뒷부분에 담긴 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"전문 지식과 함께 공감 능력·끈기가 필요함을 배워 그 역할을 더 존중하게 되었다","correct":true},{"t":"상담 교사가 되려면 관련 학문을 전공하고 교원 임용 시험을 치른다","mis":"K6-2-u2-X15"},{"t":"면담은 한 시간 정도 했고 주요 내용을 네 가지로 요약했다","mis":"K6-2-u2-X15"},{"t":"원주는 질문 담당, 기철이는 매체 담당을 맡았다","mis":"K6-2-u2-X15"}],"explanation":["뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 써요.","하늘 모둠은 공감 능력과 끈기가 필요하다는 것을 배웠어요.","역할을 존중하게 되고 상담 분야에 관심이 생겼어요."],"asset":{"type":"passage","lines":["(간추림) 면담을 하며 상담 교사라는 직업을 더 자세히 알았다.","(간추림) 전문적인 지식뿐만 아니라 공감 능력과 끈기가 필요하다는 것도 배웠다.","(간추림) 상담 교사의 역할을 더욱 존중하게 되었고, 상담 분야에 더 관심이 생겼다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 뒷부분 — 『국어』 105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#7','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'mc','auto','『국어』 107쪽 「공유하기」에서 면담 보고서를 나누는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X11','K6-2-u2-X04','K6-2-u2-X14']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"『국어』 107쪽 「공유하기」에서 면담 보고서를 나누는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"면담 보고서를 친구들과 공유하고 다른 모둠의 면담 내용을 이야기한다","correct":true},{"t":"면담 대상자의 녹화 영상을 보고서와 함께 누리집에 올린다","mis":"K6-2-u2-X11"},{"t":"면담 대상자의 개인 정보를 보고서 앞에 크게 쓴다","mis":"K6-2-u2-X04"},{"t":"우리 모둠 보고서만 읽고 다른 모둠 보고서는 읽지 않는다","mis":"K6-2-u2-X14"}],"explanation":["보고서는 친구들과 나누려고 써요.","다른 모둠의 면담 내용도 함께 이야기해요.","녹화 자료와 개인 정보는 나누지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#8','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'essay','teacher','『국어』 106~107쪽 「글쓰기」처럼 면담 보고서의 짜임을 계획하세요. 면담 대상자를 정하고, 앞부분·가운데 부분·뒷부분에 쓸 내용을 각각 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"『국어』 106~107쪽 「글쓰기」처럼 면담 보고서의 짜임을 계획하세요. 면담 대상자를 정하고, 앞부분·가운데 부분·뒷부분에 쓸 내용을 각각 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 면담 대상자 — 학교 영양 선생님. 앞부분 — 영양 교사가 되는 방법과 역할을 알아보려고 영양 선생님과 면담했다. 약속·질문·매체·정리·진행 역할을 나누어 준비했다. 가운데 부분 — 영양 교사가 되는 과정, 학교에서 하는 일, 힘든 점, 보람과 전망을 선생님의 답변 중심으로 소개한다. 뒷부분 — 급식 하나에도 많은 준비가 필요하다는 것을 알게 되었고, 앞으로 급식을 소중히 여기겠다는 생각이 들었다.","scoring_points":["앞부분에 목적·대상자·준비 과정을 계획했는가","가운데 부분에 새롭게 안 사실을 답변 중심으로 계획했는가","뒷부분에 느낀 점과 달라진 생각을 계획했는가"]},"explanation":["앞부분에는 준비 과정에서 세웠던 계획이 드러나게 써요.","가운데 부분은 면담 대상자의 답변을 중심으로 써요.","뒷부분은 인상 깊었던 부분을 중심으로 소감을 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#9','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C15',4,'essay','teacher','「상담 교사, 마음의 길을 밝히는 사람들」의 가운데 부분에서 가장 인상 깊은 내용 하나를 고르고, 그 까닭과 함께 보고서 뒷부분처럼 느낀 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C15","difficulty":4,"kind":"essay","stem":"「상담 교사, 마음의 길을 밝히는 사람들」의 가운데 부분에서 가장 인상 깊은 내용 하나를 고르고, 그 까닭과 함께 보고서 뒷부분처럼 느낀 점을 쓰세요.","answer_guide":{"answer":"예: 상담 교사가 바로 변화를 이끌어 내기 어려울 때도 있어 인내심이 필요하다는 내용이 가장 인상 깊었다. 고민을 들어 주면 금방 해결될 줄 알았기 때문이다. 상담 교사는 오래 기다려 주는 직업이라는 것을 알게 되었고, 고민을 이야기하는 친구의 말을 끝까지 들어 주어야겠다고 생각했다.","scoring_points":["가운데 부분의 내용 하나를 정확히 골랐는가","인상 깊은 까닭을 썼는가","깨달은 점이나 달라진 생각을 썼는가"]},"explanation":["가운데 부분의 네 가지 내용을 다시 읽어요.","하나를 골라 왜 인상 깊었는지 써요.","뒷부분처럼 깨달은 점과 달라진 생각으로 마무리해요."],"asset":{"type":"passage","lines":["(간추림) 면담은 한 시간 정도 했고, 주요 내용은 네 가지로 요약할 수 있다.","(간추림) 첫째, 되는 과정 — 심리학이나 상담학, 교육학 같은 것을 전공하고","(간추림)   자격증을 따서 교원 임용 시험을 치른다. 고민을 경청하는 자세도 필요하다.","(간추림) 둘째, 하는 일 — 학교생활의 고민을 들어 주고 해결 방법을 찾도록 돕는다.","(간추림) 셋째, 힘든 점 — 정신적으로 힘들 때가 많고, 인내심이 필요하다.","(간추림) 넷째, 보람과 전망 — 고민 해결을 도울 때 가장 보람 있고, 전망이 밝다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 가운데 부분 — 『국어』 104~105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L09_challenge#10','kor',6,2,'u2','L09','tb_g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'mc','auto','자신의 보완할 점이 「면담을 마무리하고 난 뒤에 면담 대상자에게 감사 인사를 제대로 못 했다.」였어요. 다음 면담에서 실천할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X14','K6-2-u2-X05']::text[],false,'{"seq":10,"concept":"K6-2-u2-C9","difficulty":4,"kind":"mc","stem":"자신의 보완할 점이 「면담을 마무리하고 난 뒤에 면담 대상자에게 감사 인사를 제대로 못 했다.」였어요. 다음 면담에서 실천할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"면담을 마칠 때 알게 된 것을 확인하고 감사 인사를 끝까지 드린다","correct":true},{"t":"감사 인사는 쑥스러우니 다음에도 생략한다","mis":"K6-2-u2-X10"},{"t":"감사 인사를 못 한 까닭을 친구 탓으로 돌린다","mis":"K6-2-u2-X14"},{"t":"면담 시작 때 인사했으니 마무리 인사는 하지 않는다","mis":"K6-2-u2-X05"}],"explanation":["보완할 점은 다음 면담에서 할 행동으로 바꾸어요.","면담 마무리하기에서는 결과를 확인하고 감사 인사를 해요.","구체적으로 무엇을 할지 정하면 지키기 쉬워요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 면담 목적에 맞는 질문을 잘 만들었다.","보완할 점 — 면담을 마무리하고 난 뒤에 면담 대상자에게 감사 인사를","   제대로 못 했다.","더 알고 싶은 점 — 상담 교사가 꿈인 친구들에게 도움이 되는 책이 무엇인지 궁금하다."],"numbered":false,"title":"자신의 면담 과정 정리 — 『국어』 102쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#1','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',1,'mc','auto','「작품 속 인물과 면담하기」 활동에서 가장 먼저 하는 일은 무엇인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":1,"concept":"K6-2-u2-C10","difficulty":1,"kind":"mc","stem":"「작품 속 인물과 면담하기」 활동에서 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"모둠 친구들과 작품 속 인물 떠올리기","correct":true},{"t":"한 명이 작품 속 인물이 되어 면담하기","mis":"K6-2-u2-X05"},{"t":"소감 나누기","mis":"K6-2-u2-X05"},{"t":"작품 속 인물에게 질문 만들기","mis":"K6-2-u2-X05"}],"explanation":["먼저 모둠 친구들과 작품 속 인물을 떠올려요.","그다음 궁금한 점을 떠올려 질문을 만들어요.","한 명이 인물이 되어 면담하고 소감을 나누어요."],"asset":{"type":"passage","lines":["① 모둠 친구들과 작품 속 인물 떠올리기 (예: 이순신 장군 · 흥부 · 강아지똥)","② 작품 속 인물에게 궁금한 점을 떠올리고 질문 만들기","③ 모둠 친구 가운데 한 명이 작품 속 인물이 되어 면담하기","④ 소감 나누기"],"numbered":false,"title":"이런 활동도 있어요 — 작품 속 인물과 면담하기 (『국어』 108쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#2','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',1,'sa','auto','「사과가 수박보다 값이 싸구나!」에서 「값이」는 어떻게 소리 내야 하는지 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C11","difficulty":1,"kind":"sa","stem":"「사과가 수박보다 값이 싸구나!」에서 「값이」는 어떻게 소리 내야 하는지 소리 나는 대로 쓰세요.","answer":["갑씨","[갑씨]"],"explanation":["「값」은 겹받침 ㅄ이 있는 낱말이에요.","뒤에 모음으로 시작하는 「이」가 붙으면 ㅅ이 넘어가며 [갑씨]로 소리 나요.","『국어』 113쪽 가 장면이에요."],"asset":{"type":"passage","lines":["가 사과가 수박보다 값이[갑씨] 싸구나!","나 밥 먹을 때에는 자리에 앉아서[안자서] 먹자.","다 자연환경을 보호하면 우리 삶이[살ː미] 풍요로워질 거예요.","라 블록이 무너질 것 같아 불안해요. — 걱정할 필요 없어[업ː써]. 지금 잘하고 있어."],"numbered":false,"title":"기초 다지기 1 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#3','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',1,'mc','auto','「밥 먹을 때에는 자리에 앉아서 먹자.」에서 「앉아서」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":3,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「밥 먹을 때에는 자리에 앉아서 먹자.」에서 「앉아서」의 바른 발음은 무엇인가요?","options":[{"t":"[안자서]","correct":true},{"t":"[안아서]","mis":"K6-2-u2-X18"},{"t":"[아나서]","mis":"K6-2-u2-X18"},{"t":"[앉아서]","mis":"K6-2-u2-X18"}],"explanation":["「앉」의 겹받침은 ㄵ이에요.","뒤에 모음 「아」가 오면 ㅈ이 넘어가 [안자서]로 소리 나요.","앞 자음 ㄴ은 받침으로 남아요."],"asset":{"type":"passage","lines":["가 사과가 수박보다 값이[갑씨] 싸구나!","나 밥 먹을 때에는 자리에 앉아서[안자서] 먹자.","다 자연환경을 보호하면 우리 삶이[살ː미] 풍요로워질 거예요.","라 블록이 무너질 것 같아 불안해요. — 걱정할 필요 없어[업ː써]. 지금 잘하고 있어."],"numbered":false,"title":"기초 다지기 1 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#4','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',1,'ox','auto','친구가 작품 속 인물이 되어 대답할 때에는 작품 속 사건이나 대사, 행동을 근거로 말해야 해요.',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":4,"concept":"K6-2-u2-C10","difficulty":1,"kind":"ox","stem":"친구가 작품 속 인물이 되어 대답할 때에는 작품 속 사건이나 대사, 행동을 근거로 말해야 해요.","answer":"O","reason_options":[{"t":"답을 상상으로만 꾸미지 않고 작품에 근거해야 하기 때문에","correct":true},{"t":"인물이 되면 작품과 상관없이 마음대로 지어내도 되기 때문에","mis":"K6-2-u2-X16"}],"mis":"K6-2-u2-X16","explanation":["작품 속 인물에게 묻는 것은 작품을 더 깊이 이해하려는 거예요.","그래서 대답은 작품 속 사건·대사·행동에 근거해요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 모둠 친구들과 작품 속 인물 떠올리기 (예: 이순신 장군 · 흥부 · 강아지똥)","② 작품 속 인물에게 궁금한 점을 떠올리고 질문 만들기","③ 모둠 친구 가운데 한 명이 작품 속 인물이 되어 면담하기","④ 소감 나누기"],"numbered":false,"title":"이런 활동도 있어요 — 작품 속 인물과 면담하기 (『국어』 108쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#5','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'match','auto','작품 속 인물 「강아지똥」에게 할 질문이에요. 질문과 기준을 바르게 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C10","difficulty":2,"kind":"match","stem":"작품 속 인물 「강아지똥」에게 할 질문이에요. 질문과 기준을 바르게 이어 보세요.","pairs":[{"l":"민들레꽃을 피우려고 어떤 일을 했나요?","r":"구체적인 사실에 대한 질문"},{"l":"다른 인물들이 자신을 하찮게 볼 때 스스로를 어떻게 생각했나요?","r":"생각이나 느낌에 대한 질문"},{"l":"자신이 쓸모없다고 생각하는 친구에게 해 줄 말이 있나요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["한 일을 묻는 것은 구체적인 사실이에요.","스스로를 어떻게 생각했는지는 생각이나 느낌이에요.","친구에게 해 줄 말은 당부예요."],"asset":{"type":"passage","lines":["구체적인 사실에 대한 질문 — 민들레꽃을 피우려고 어떤 일을 했나요?","생각이나 느낌에 대한 질문 — 다른 인물들이 자신을 하찮게 볼 때","   스스로를 어떻게 생각했나요?","앞으로의 계획이나 당부에 대한 질문 — 자신이 쓸모없다고","   생각하는 친구에게 해 줄 말이 있나요?"],"numbered":false,"title":"작품 속 인물 「강아지똥」에게 할 질문 — 『국어』 108쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#6','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',2,'mc','auto','「닭이 새벽을 알리며 울었다.」에서 「닭이」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":6,"concept":"K6-2-u2-C11","difficulty":2,"kind":"mc","stem":"「닭이 새벽을 알리며 울었다.」에서 「닭이」의 바른 발음은 무엇인가요?","options":[{"t":"[달기]","correct":true},{"t":"[다기]","mis":"K6-2-u2-X18"},{"t":"[닥이]","mis":"K6-2-u2-X18"},{"t":"[닥기]","mis":"K6-2-u2-X18"}],"explanation":["「닭」의 겹받침은 ㄺ이에요.","낱말 하나로는 [닥]이지만, 모음 「이」가 붙으면 ㄱ이 넘어가요.","그래서 [달기]로 소리 나요."],"asset":{"type":"passage","lines":["● 닭이[달기] 새벽을 알리며 울었다.","● 진수의 신발에 흙이[흘기] 묻었다.","● 노력하는 사람의 삶은[살ː믄] 아름답다."],"numbered":false,"title":"기초 다지기 2 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#7','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','「바람직한 질문, 불쾌한 질문」 활동에서 「공부 잘하니?」를 바람직한 질문으로 바꾼 것은 무엇인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":7,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"「바람직한 질문, 불쾌한 질문」 활동에서 「공부 잘하니?」를 바람직한 질문으로 바꾼 것은 무엇인가요?","options":[{"t":"「공부가 재밌으려면 어떻게 하면 좋을까?」","correct":true},{"t":"「너는 왜 공부를 못하니?」","mis":"K6-2-u2-X17"},{"t":"「공부 몇 등 하니?」","mis":"K6-2-u2-X17"},{"t":"「공부 잘하니? 솔직하게 말해 봐.」","mis":"K6-2-u2-X17"}],"explanation":["「공부 잘하니?」는 대답하기 난감할 수 있는 질문이에요.","상대의 기분이 나쁘지 않도록 바꾸어요.","함께 방법을 찾는 질문이 바람직한 질문이에요."],"asset":{"type":"passage","lines":["① 질문을 받았던 기억 떠올리기 — 예: “공부 잘하니?”, “그게 재밌니?”","② 불쾌한 질문의 조건 생각하기 — 예: 사람의 단점을 파고드는 질문,","   비난하려는 의도가 분명하게 느껴지는 질문","③ 바람직한 질문으로 변신시키기 — 예: 공부가 재밌으려면 어떻게 하면 좋을까?","④ 질문 태도 점검표 만들기","⑤ 정리하기 — 점검표를 모둠원과 공유하고 자신의 질문 태도를 점검한다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 1 — 바람직한 질문, 불쾌한 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#8','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',2,'blank','auto','『국어』 113쪽 기초 다지기 2의 문장이에요. 빈칸에 들어갈 발음으로 알맞은 것은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#9','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','「네가 궁금해 놀이」의 놀이 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X10','K6-2-u2-X05']::text[],false,'{"seq":9,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"「네가 궁금해 놀이」의 놀이 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"한 번 나온 질문은 표시해 두고 다시 묻고 답하지 않는다","correct":true},{"t":"대답하기 곤란한 질문일수록 재미있으니 많이 넣는다","mis":"K6-2-u2-X17"},{"t":"주사위를 던진 사람은 질문에 대답하지 않아도 된다","mis":"K6-2-u2-X10"},{"t":"같은 질문이 나오면 계속 다시 대답한다","mis":"K6-2-u2-X05"}],"explanation":["질문 카드에 궁금한 내용 여섯 가지를 문장으로 만들어요.","불편하거나 민감한 질문은 만들지 않아요.","한 번 나온 질문은 표시해 다시 묻지 않아요."],"asset":{"type":"passage","lines":["① 모둠 친구끼리 의논해 질문 카드에 궁금한 내용 여섯 가지를 문장으로 만든다.","   (서로 묻고 답하기에 불편하거나 민감한 질문은 만들지 않는다.)","② 모둠에서 한 사람을 정해 주사위를 던진다.","③ 주사위 번호의 질문을 읽고 대답한다. 한 번 나온 질문은 표시해 다시 묻지 않는다.","④ 다른 사람이 주사위를 던지고 질문에 답한다.","⑤ 질문 카드의 질문에 모두 대답할 때까지 놀이를 진행한다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 2 — 네가 궁금해 놀이 (질문 카드 · 주사위)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_basic#10','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',3,'essay','teacher','재미있게 읽은 작품 속 인물을 한 명 고르고, 그 인물에게 할 질문을 기준마다 하나씩 만드세요(구체적인 사실 · 생각이나 느낌 · 앞으로의 계획이나 당부).','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C10","difficulty":3,"kind":"essay","stem":"재미있게 읽은 작품 속 인물을 한 명 고르고, 그 인물에게 할 질문을 기준마다 하나씩 만드세요(구체적인 사실 · 생각이나 느낌 · 앞으로의 계획이나 당부).","answer_guide":{"answer":"예: 인물 — 흥부. 구체적인 사실 — 다친 제비를 보고 어떻게 했나요? / 생각이나 느낌 — 제비의 다리를 고쳐 줄 때는 어떤 생각을 했나요? / 앞으로의 계획이나 당부 — 형 놀부에게 앞으로 해 주고 싶은 말이 있나요?","scoring_points":["작품 속 인물을 골랐는가","세 기준에 맞는 질문을 하나씩 만들었는가","작품 내용과 이어지는 질문인가"]},"explanation":["관심 있게 읽은 작품이 없으면 영화나 만화 영화 속 인물도 좋아요.","세 기준으로 나누어 질문을 만들어요.","작품을 읽은 사람이 답할 수 있는 질문으로 만들어요."],"asset":{"type":"passage","lines":["(이순신 장군) 장군님께서는 전쟁이 힘들 때 어떤 마음으로 버티셨나요?","(흥부) 제비의 다리를 고쳐 줄 때는 어떤 생각을 했나요?","(강아지똥) 자신이 쓸모없다고 생각하는 친구에게 해 줄 말이 있나요?"],"numbered":false,"title":"작품 속 인물에게 할 질문 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#1','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',2,'mc','auto','겹받침이 있는 낱말을 낱말 하나로 발음할 때의 규칙으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":1,"concept":"K6-2-u2-C11","difficulty":2,"kind":"mc","stem":"겹받침이 있는 낱말을 낱말 하나로 발음할 때의 규칙으로 알맞은 것은 무엇인가요?","options":[{"t":"대부분 둘 가운데 하나만 발음된다(닭[닥], 값[갑])","correct":true},{"t":"두 받침을 모두 이어서 또렷하게 소리 낸다","mis":"K6-2-u2-X18"},{"t":"받침은 하나도 발음하지 않고 넘어간다","mis":"K6-2-u2-X18"},{"t":"어느 낱말이든 언제나 뒤 받침만 발음한다","mis":"K6-2-u2-X18"}],"explanation":["겹받침은 받침에 자음이 두 개 있어요.","낱말 하나로 발음할 때는 대부분 하나만 소리 나요.","닭은 [닥], 값은 [갑]으로 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#2','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',2,'ox','auto','「진수의 신발에 흙이 묻었다.」에서 「흙이」는 [흑이]로 소리 내요.',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":2,"concept":"K6-2-u2-C11","difficulty":2,"kind":"ox","stem":"「진수의 신발에 흙이 묻었다.」에서 「흙이」는 [흑이]로 소리 내요.","answer":"X","reason_options":[{"t":"모음 「이」가 붙으면 ㄱ이 넘어가 [흘기]로 소리 나기 때문에","correct":true},{"t":"겹받침은 모음 앞에서도 하나만 소리 나기 때문에","mis":"K6-2-u2-X18"}],"mis":"K6-2-u2-X18","explanation":["「흙」의 겹받침은 ㄺ이에요.","모음으로 시작하는 말이 붙으면 뒤 자음이 넘어가요.","그래서 [흘기]가 바른 발음이고 X예요."],"asset":{"type":"passage","lines":["● 닭이[달기] 새벽을 알리며 울었다.","● 진수의 신발에 흙이[흘기] 묻었다.","● 노력하는 사람의 삶은[살ː믄] 아름답다."],"numbered":false,"title":"기초 다지기 2 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#3','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'mc','auto','「장군님께서는 전쟁이 힘들 때 어떤 마음으로 버티셨나요?」는 이순신 장군에게 하는 어떤 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":3,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"「장군님께서는 전쟁이 힘들 때 어떤 마음으로 버티셨나요?」는 이순신 장군에게 하는 어떤 질문인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"작품과 상관없는 질문","mis":"K6-2-u2-X07"}],"explanation":["이 질문은 힘들 때의 마음을 물어요.","마음과 생각을 묻는 질문은 생각이나 느낌에 대한 질문이에요.","있었던 일을 묻는다면 구체적인 사실에 대한 질문이에요."],"asset":{"type":"passage","lines":["(이순신 장군) 장군님께서는 전쟁이 힘들 때 어떤 마음으로 버티셨나요?","(흥부) 제비의 다리를 고쳐 줄 때는 어떤 생각을 했나요?","(강아지똥) 자신이 쓸모없다고 생각하는 친구에게 해 줄 말이 있나요?"],"numbered":false,"title":"작품 속 인물에게 할 질문 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#4','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'mc','auto','친구가 흥부가 되어 「제비의 다리를 고쳐 줄 때는 어떤 생각을 했나요?」라는 질문에 대답했어요. 작품에 근거한 대답으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X16','K6-2-u2-X10']::text[],false,'{"seq":4,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"친구가 흥부가 되어 「제비의 다리를 고쳐 줄 때는 어떤 생각을 했나요?」라는 질문에 대답했어요. 작품에 근거한 대답으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「다친 제비가 불쌍해서 정성껏 고쳐 주고 싶었어요.」","correct":true},{"t":"「사실은 처음부터 박씨를 받으려고 고쳐 주었어요.」","mis":"K6-2-u2-X16"},{"t":"「저는 제비를 본 적이 없어요.」","mis":"K6-2-u2-X16"},{"t":"「그건 비밀이라 말할 수 없어요.」","mis":"K6-2-u2-X10"}],"explanation":["「흥부와 놀부」에서 흥부는 다친 제비 다리를 정성스레 고쳐 주었어요.","인물의 대답은 작품 속 사건과 행동에 근거해야 해요.","작품에 없는 속마음을 지어내지 않아요."],"asset":{"type":"passage","lines":["(이순신 장군) 장군님께서는 전쟁이 힘들 때 어떤 마음으로 버티셨나요?","(흥부) 제비의 다리를 고쳐 줄 때는 어떤 생각을 했나요?","(강아지똥) 자신이 쓸모없다고 생각하는 친구에게 해 줄 말이 있나요?"],"numbered":false,"title":"작품 속 인물에게 할 질문 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#5','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'error','auto','질문 태도 점검표로 질문을 점검했어요. 대답하기 난감할 수 있어 고쳐야 할 질문을 고르세요.',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":5,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"질문 태도 점검표로 질문을 점검했어요. 대답하기 난감할 수 있어 고쳐야 할 질문을 고르세요.","options":[{"t":"「공부 잘하니?」","correct":true,"mis_target":"K6-2-u2-X17"},{"t":"「당신이 가장 좋아하는 계절은 무엇인가요? 그 까닭은 무엇인가요?」","mis":"K6-2-u2-X17"},{"t":"「당신의 희망 진로는 무엇인가요? 그 까닭은 무엇인가요?」","mis":"K6-2-u2-X17"}],"explanation":["점검표는 상대가 불쾌하거나 난감하지 않은지 물어요.","「공부 잘하니?」는 대답하기 난감할 수 있는 질문의 예예요.","계절이나 희망 진로를 묻는 카드 질문은 편하게 답할 수 있어요."],"asset":{"type":"passage","lines":["● 상대의 기분을 불쾌하게 할 수 있는 질문인가?","● 대답하기 난감한 질문인가?","● 상대의 단점을 공격하는 질문인가?","● 재미를 위해 장난으로 하는 질문인가?","● 말하고 싶지 않은 것을 억지로 대답하게 하는 질문인가?"],"numbered":false,"title":"질문 태도 점검표 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#6','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',3,'mc','auto','겹받침 뒤에 모음으로 시작하는 말이 붙은 「젊어」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":6,"concept":"K6-2-u2-C11","difficulty":3,"kind":"mc","stem":"겹받침 뒤에 모음으로 시작하는 말이 붙은 「젊어」의 바른 발음은 무엇인가요?","options":[{"t":"[절머]","correct":true},{"t":"[저머]","mis":"K6-2-u2-X18"},{"t":"[점어]","mis":"K6-2-u2-X18"},{"t":"[절어]","mis":"K6-2-u2-X18"}],"explanation":["「젊」의 겹받침은 ㄻ이에요.","모음 「어」가 붙으면 ㅁ이 넘어가요.","ㄹ은 받침으로 남아 [절머]로 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#7','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'mc','auto','작품 속 인물과 면담하려는데 관심 있게 읽은 책이 없다면 어떻게 하면 좋을까요?',ARRAY['K6-2-u2-X16','K6-2-u2-X19','K6-2-u2-X04']::text[],false,'{"seq":7,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"작품 속 인물과 면담하려는데 관심 있게 읽은 책이 없다면 어떻게 하면 좋을까요?","options":[{"t":"영화나 만화 영화, 다른 단원에서 읽은 작품 속 인물을 떠올린다","correct":true},{"t":"작품에 없는 인물을 마음대로 지어내서 면담한다","mis":"K6-2-u2-X16"},{"t":"읽은 책이 없으니 면담 활동에서 빠진다","mis":"K6-2-u2-X19"},{"t":"친구의 개인 정보를 묻는 질문을 대신 만든다","mis":"K6-2-u2-X04"}],"explanation":["평소 재미있게 읽은 작품과 인물을 먼저 떠올려요.","책이 없으면 영화나 만화 영화 속 인물도 좋아요.","다른 단원에서 읽은 작품 속 인물도 떠올릴 수 있어요."],"asset":{"type":"passage","lines":["① 모둠 친구들과 작품 속 인물 떠올리기 (예: 이순신 장군 · 흥부 · 강아지똥)","② 작품 속 인물에게 궁금한 점을 떠올리고 질문 만들기","③ 모둠 친구 가운데 한 명이 작품 속 인물이 되어 면담하기","④ 소감 나누기"],"numbered":false,"title":"이런 활동도 있어요 — 작품 속 인물과 면담하기 (『국어』 108쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#8','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',4,'essay','teacher','「그게 재밌니?」라는 질문이 상대에게 어떻게 들릴 수 있는지 쓰고, 질문 태도 점검표의 항목을 하나 들어 상대를 배려하는 바람직한 질문으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u2-C10","difficulty":4,"kind":"essay","stem":"「그게 재밌니?」라는 질문이 상대에게 어떻게 들릴 수 있는지 쓰고, 질문 태도 점검표의 항목을 하나 들어 상대를 배려하는 바람직한 질문으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 「그게 재밌니?」는 상대가 좋아하는 것을 깎아내리는 것처럼 들려 기분이 나쁠 수 있다. 「상대의 기분을 불쾌하게 할 수 있는 질문인가?」라는 항목에 걸린다. 바꾼 질문 — 「그것의 어떤 점이 가장 재미있니?」","scoring_points":["질문이 상대에게 어떻게 들릴지 썼는가","점검표 항목을 근거로 들었는가","상대를 배려하는 질문으로 바꾸었는가"]},"explanation":["질문을 받는 사람의 입장이 되어 들어 봐요.","점검표 항목으로 어떤 점이 문제인지 찾아요.","궁금함은 그대로 두고 표현을 바꾸어요."],"asset":{"type":"passage","lines":["● 상대의 기분을 불쾌하게 할 수 있는 질문인가?","● 대답하기 난감한 질문인가?","● 상대의 단점을 공격하는 질문인가?","● 재미를 위해 장난으로 하는 질문인가?","● 말하고 싶지 않은 것을 억지로 대답하게 하는 질문인가?"],"numbered":false,"title":"질문 태도 점검표 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#9','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',4,'essay','teacher','『국어』 113쪽 기초 다지기에서 겹받침 낱말 두 개를 골라 소리 나는 대로 쓰고, 겹받침 뒤에 모음으로 시작하는 말이 붙을 때 어떻게 소리 나는지 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C11","difficulty":4,"kind":"essay","stem":"『국어』 113쪽 기초 다지기에서 겹받침 낱말 두 개를 골라 소리 나는 대로 쓰고, 겹받침 뒤에 모음으로 시작하는 말이 붙을 때 어떻게 소리 나는지 설명하세요.","answer_guide":{"answer":"예: 값이[갑씨], 흙이[흘기]. 겹받침 뒤에 모음으로 시작하는 조사가 붙으면 앞 자음은 받침으로 남고 뒤 자음은 다음 글자의 첫소리로 넘어가 소리 난다. 「값이」는 넘어간 ㅅ이 된소리 [씨]로 난다.","scoring_points":["겹받침 낱말 두 개의 발음을 바르게 썼는가","앞 자음은 받침으로 남고 뒤 자음이 넘어간다고 설명했는가","『국어』 113쪽의 낱말을 골랐는가"]},"explanation":["기초 다지기의 파란색 낱말을 떠올려요.","모음 앞에서는 뒤 자음이 넘어가 소리 나요.","정확하게 발음해야 소통에 오해가 없어요."],"asset":{"type":"passage","lines":["가 사과가 수박보다 값이[갑씨] 싸구나!","나 밥 먹을 때에는 자리에 앉아서[안자서] 먹자.","다 자연환경을 보호하면 우리 삶이[살ː미] 풍요로워질 거예요.","라 블록이 무너질 것 같아 불안해요. — 걱정할 필요 없어[업ː써]. 지금 잘하고 있어."],"numbered":false,"title":"기초 다지기 1 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_L11_challenge#10','kor',6,2,'u2','L11','tb_g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',4,'mc','auto','겹받침 뒤에 「-히-」가 붙은 「앉히다」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":10,"concept":"K6-2-u2-C11","difficulty":4,"kind":"mc","stem":"겹받침 뒤에 「-히-」가 붙은 「앉히다」의 바른 발음은 무엇인가요?","options":[{"t":"[안치다]","correct":true},{"t":"[안히다]","mis":"K6-2-u2-X18"},{"t":"[아치다]","mis":"K6-2-u2-X18"},{"t":"[안지다]","mis":"K6-2-u2-X18"}],"explanation":["「앉」의 겹받침은 ㄵ이에요.","ㅈ과 뒤의 ㅎ이 만나 [ㅊ]으로 소리 나요.","그래서 [안치다]로 소리 나요(「읽히다」는 [일키다])."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#1','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C1',1,'mc','auto','『국어』 111쪽 3번의 ㉠에 들어갈 말은 무엇인가요?',ARRAY['K6-2-u2-X01']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 111쪽 3번의 ㉠에 들어갈 말은 무엇인가요?","options":[{"t":"면담","correct":true},{"t":"토론","mis":"K6-2-u2-X01"},{"t":"발표","mis":"K6-2-u2-X01"},{"t":"일상 대화","mis":"K6-2-u2-X01"}],"explanation":["특정 인물이나 주제의 정보를 수집하려는 대화예요.","면담자와 면담 대상자가 주고받아요.","이런 대화를 면담이라고 해요."],"asset":{"type":"passage","lines":["보기: 면담 · 목적 · 면담 대상자","● (    ㉠    )은/는 특정 인물이나 주제의 정보를 수집하려고","   면담자와 면담 대상자가 주고받는 대화를 말한다.","● (    ㉡    )이/가 말하는 도중에 끼어들어 말하지 않는다.","● 면담 (    ㉢    )에서 벗어난 질문을 하지 않는다."],"numbered":false,"title":"공부한 내용 되돌아보기 — 『국어』 111쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#2','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C1',1,'mc','auto','『국어』 80쪽 만화에서 신문 동아리 친구들이 면담하려고 찾아간 곳은 어디인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":2,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 80쪽 만화에서 신문 동아리 친구들이 면담하려고 찾아간 곳은 어디인가요?","options":[{"t":"유기 동물 보호 센터","correct":true},{"t":"공공 도서관 사서실","mis":"K6-2-u2-X07"},{"t":"동네 동물 병원","mis":"K6-2-u2-X07"},{"t":"학교 전담 경찰관실","mis":"K6-2-u2-X07"}],"explanation":["친구들은 유기 동물 보호와 관련한 기사를 쓰려고 했어요.","그래서 유기 동물 보호 센터를 찾아갔어요.","목적에 맞는 곳을 찾아간 거예요."],"asset":{"type":"speech","turns":[{"who":"신문 동아리","text":"안녕하세요? ○○초등학교 신문 동아리입니다. 학교 신문에 유기 동물 보호와 관련한 기사를 싣고 싶습니다. 혹시 면담에 참여해 주실 수 있을까요?"},{"who":"보호 센터","text":"네, 다음 주 이 시간에 면담이 가능합니다."},{"who":"신문 동아리","text":"(일주일 뒤) 면담에 응해 주셔서 감사합니다. 미리 수집한 정보를 바탕으로 유기 동물 보호와 관련 있는 질문을 드리려고 합니다."},{"who":"신문 동아리","text":"유기 동물 보호 센터에서 하는 일은 무엇인가요?"},{"who":"신문 동아리","text":"(답을 듣고 나서) 감사합니다."},{"who":"보호 센터","text":"유기 동물 보호 센터에 관심을 가져 주어서 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#3','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',1,'mc','auto','면담의 절차를 차례대로 바르게 나타낸 것은 무엇인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"면담의 절차를 차례대로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"면담 준비하기 → 면담 진행하기 → 면담 정리하기","correct":true},{"t":"면담 진행하기 → 면담 준비하기 → 면담 정리하기","mis":"K6-2-u2-X05"},{"t":"면담 정리하기 → 면담 진행하기 → 면담 준비하기","mis":"K6-2-u2-X05"},{"t":"면담 준비하기 → 면담 정리하기 → 면담 진행하기","mis":"K6-2-u2-X05"}],"explanation":["만나기 전에 준비해요.","만나서 면담을 진행해요.","만난 뒤에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#4','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',1,'mc','auto','「사서가 되려면 어떤 과정을 거쳐야 하나요?」는 어떤 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"「사서가 되려면 어떤 과정을 거쳐야 하나요?」는 어떤 질문인가요?","options":[{"t":"구체적인 사실에 대한 질문","correct":true},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적에 맞지 않는 질문","mis":"K6-2-u2-X07"}],"explanation":["사서가 되는 과정은 실제로 있는 사실이에요.","그래서 구체적인 사실에 대한 질문이에요.","『국어』 85쪽에서 ㉠·㉡이 여기에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#5','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C5',1,'mc','auto','후속 질문을 바르게 설명한 것은 무엇인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X06','K6-2-u2-X05']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":1,"kind":"mc","stem":"후속 질문을 바르게 설명한 것은 무엇인가요?","options":[{"t":"면담 대상자의 대답을 듣고 더 자세히 알려고 이어서 하는 질문","correct":true},{"t":"면담을 요청할 때 하는 질문","mis":"K6-2-u2-X03"},{"t":"면담 대상자의 대답을 듣기 전에 미리 정해 둔 마지막 질문","mis":"K6-2-u2-X06"},{"t":"면담이 끝난 뒤 친구들끼리 하는 질문","mis":"K6-2-u2-X05"}],"explanation":["후속 질문은 대답을 듣고 생겨요.","앞선 대답과 이어져 더 자세히 알려고 해요.","대답을 끝까지 들어야 할 수 있어요."],"asset":{"type":"passage","lines":["후속 질문은 면담 대상자의 대답을 듣고","더 자세히 알려고 이어서 하는 질문을 말해요."],"title":"『국어』 91쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#6','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',1,'mc','auto','비대면 면담의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X12']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"비대면 면담의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"면담 대상자를 직접 만나지 않거나 서로 얼굴을 마주 보고 대하지 않는 면담","correct":true},{"t":"면담 대상자를 직접 만나 얼굴을 마주 보고 하는 면담","mis":"K6-2-u2-X12"},{"t":"면담 대상자 없이 혼자 질문하고 답하는 면담","mis":"K6-2-u2-X12"},{"t":"녹음기를 켜고 마주 앉아 하는 면담","mis":"K6-2-u2-X12"}],"explanation":["비대면 면담은 직접 만나지 않고 해요.","화상 회의, 영상 통화, 전자 우편이 그 예예요.","직접 만나 마주 보면 대면 면담이에요."],"asset":{"type":"passage","lines":["보기: 대면 · 비대면","(    ㉠    ) 면담 — 면담 대상자를 직접 만나서 서로 얼굴을 마주 보고 대하는 면담","(    ㉡    ) 면담 — 면담 대상자를 직접 만나지 않거나 서로 얼굴을 마주 보고","   대하지 않는 면담"],"numbered":false,"title":"면담 방식 정리하기 — 『국어』 94쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#7','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',1,'mc','auto','면담 보고서 앞부분에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 보고서 앞부분에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"면담 목적과 대상자를 밝히고 면담 준비 과정을 돌아보기","correct":true},{"t":"면담으로 새롭게 안 사실 소개하기","mis":"K6-2-u2-X15"},{"t":"면담하고 난 뒤 느낀 점 밝히기","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 개인 정보 적기","mis":"K6-2-u2-X04"}],"explanation":["앞부분에는 계획과 준비 상황을 요약해요.","가운데 부분에는 새롭게 안 사실을 써요.","뒷부분에는 느낀 점을 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#8','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C11',1,'mc','auto','「자연환경을 보호하면 우리 삶이 풍요로워질 거예요.」에서 「삶이」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「자연환경을 보호하면 우리 삶이 풍요로워질 거예요.」에서 「삶이」의 바른 발음은 무엇인가요?","options":[{"t":"[살ː미]","correct":true},{"t":"[사미]","mis":"K6-2-u2-X18"},{"t":"[삼이]","mis":"K6-2-u2-X18"},{"t":"[살이]","mis":"K6-2-u2-X18"}],"explanation":["「삶」의 겹받침은 ㄻ이에요.","모음 「이」가 붙으면 ㅁ이 넘어가요.","그래서 [살ː미]로 소리 나요."],"asset":{"type":"passage","lines":["가 사과가 수박보다 값이[갑씨] 싸구나!","나 밥 먹을 때에는 자리에 앉아서[안자서] 먹자.","다 자연환경을 보호하면 우리 삶이[살ː미] 풍요로워질 거예요.","라 블록이 무너질 것 같아 불안해요. — 걱정할 필요 없어[업ː써]. 지금 잘하고 있어."],"numbered":false,"title":"기초 다지기 1 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#9','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C12',2,'mc','auto','윤서가 면담 열기에서 밝힌 면담 목적은 무엇인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X04']::text[],false,'{"seq":9,"concept":"K6-2-u2-C12","difficulty":2,"kind":"mc","stem":"윤서가 면담 열기에서 밝힌 면담 목적은 무엇인가요?","options":[{"t":"친구들에게 도서관 사서라는 직업을 알리는 글을 쓰려고","correct":true},{"t":"도서관에서 읽고 싶은 책을 빌리려고","mis":"K6-2-u2-X07"},{"t":"사서 선생님의 집과 가족을 알아보려고","mis":"K6-2-u2-X04"},{"t":"도서관 독서 행사에 참여 신청을 하려고","mis":"K6-2-u2-X07"}],"explanation":["윤서는 인사한 뒤 면담 목적을 설명했어요.","친구들에게 사서라는 직업을 알리는 글을 쓰고 싶다고 했어요.","그다음 녹음·녹화 동의를 구했어요."],"asset":{"type":"passage","lines":["안녕하세요? 오늘 면담을 요청드린 장윤서입니다.","면담을 허락해 주셔서 감사합니다.","친구들에게 도서관 사서라는 직업을 알리는 글을 쓰고 싶어 면담을 요청드렸습니다.","면담 내용을 다 기억할 수 없어 녹음이나 녹화를 하려고 하는데요, 괜찮으실까요?"],"title":"면담 개요의 면담 열기에서 할 말 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#10','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C13',2,'mc','auto','로봇 공학자가 로봇을 만들 때 가장 먼저 해야 한다고 말한 일은 무엇인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":10,"concept":"K6-2-u2-C13","difficulty":2,"kind":"mc","stem":"로봇 공학자가 로봇을 만들 때 가장 먼저 해야 한다고 말한 일은 무엇인가요?","options":[{"t":"로봇이 어떤 문제를 풀어야 하는지 정하는 일","correct":true},{"t":"필요한 부품을 사러 가게에 가는 일","mis":"K6-2-u2-X13"},{"t":"로봇에 칠할 예쁜 색깔을 고르는 일","mis":"K6-2-u2-X13"},{"t":"프로그램을 바로 만드는 일","mis":"K6-2-u2-X13"}],"explanation":["먼저 사람을 도울지, 위험한 곳에 갈지처럼 로봇이 할 일을 정해요.","그다음 모양과 기능을 설계하고 부품을 골라요.","마지막으로 프로그램을 만들어 여러 번 시험해요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"로봇 공학자가 로봇을 만들 때 가장 먼저 해야 하는 일은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 로봇이 풀어야 할 문제부터 정한다. 사람을 도울지, 위험한 곳에 대신 갈지 정한 뒤 모양과 기능을 설계하고 부품을 고르고, 프로그램을 만들어 여러 번 시험한다."},{"who":"학생","text":"로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 시험하면서 오류를 찾아 고치고 성능을 높여 로봇이 더 정확하고 안전하게 움직이게 하려는 것이다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#11','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C14',2,'mc','auto','민수네 모둠이 정한 면담 방식은 무엇인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X05']::text[],false,'{"seq":11,"concept":"K6-2-u2-C14","difficulty":2,"kind":"mc","stem":"민수네 모둠이 정한 면담 방식은 무엇인가요?","options":[{"t":"대면 면담","correct":true},{"t":"영상 통화로 하는 비대면 면담","mis":"K6-2-u2-X12"},{"t":"전자 우편으로 하는 비대면 면담","mis":"K6-2-u2-X12"},{"t":"면담 방식은 정하지 않았다","mis":"K6-2-u2-X05"}],"explanation":["친구는 면담 방식을 대면 면담으로 결정하자고 했어요.","같은 학교의 상담 선생님이라 직접 만날 수 있어요.","그래서 대면 면담이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리 학교 학생들을 상담해 주시는 박○○ 상담 선생님은 어떨까? 늘 친절하고 따뜻하게 우리 이야기를 들어 주시잖아."},{"who":"친구 2","text":"(간추림) 면담 방식은 직접 만나는 대면 면담으로 정하고, 박○○ 상담 선생님께 연락드려 면담을 요청하자고 했다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#12','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C15',2,'mc','auto','「상담 교사, 마음의 길을 밝히는 사람들」에서 소개한, 상담 교사가 학교에서 하는 일은 무엇인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X13']::text[],false,'{"seq":12,"concept":"K6-2-u2-C15","difficulty":2,"kind":"mc","stem":"「상담 교사, 마음의 길을 밝히는 사람들」에서 소개한, 상담 교사가 학교에서 하는 일은 무엇인가요?","options":[{"t":"학생들의 학교생활 고민을 들어 주고 해결 방법을 찾도록 돕는다","correct":true},{"t":"아픈 학생들을 치료하고 건강 상담과 보건 수업을 한다","mis":"K6-2-u2-X15"},{"t":"새 책을 주문하고 정리하며 독서 행사를 준비한다","mis":"K6-2-u2-X15"},{"t":"학생들의 시험 문제를 내고 성적을 매긴다","mis":"K6-2-u2-X13"}],"explanation":["둘째로 소개한 내용이 학교에서 하는 일이에요.","고민을 들어 주고 해결 방법을 찾도록 도와요.","치료와 보건 수업은 보건 교사의 일이에요."],"asset":{"type":"passage","lines":["(간추림) 면담은 한 시간 정도 했고, 주요 내용은 네 가지로 요약할 수 있다.","(간추림) 첫째, 되는 과정 — 심리학이나 상담학, 교육학 같은 것을 전공하고","(간추림)   자격증을 따서 교원 임용 시험을 치른다. 고민을 경청하는 자세도 필요하다.","(간추림) 둘째, 하는 일 — 학교생활의 고민을 들어 주고 해결 방법을 찾도록 돕는다.","(간추림) 셋째, 힘든 점 — 정신적으로 힘들 때가 많고, 인내심이 필요하다.","(간추림) 넷째, 보람과 전망 — 고민 해결을 도울 때 가장 보람 있고, 전망이 밝다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 가운데 부분 — 『국어』 104~105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#13','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C6',2,'mc','auto','면담 열기에서 예의를 지키려고 한 말로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X11']::text[],false,'{"seq":13,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"면담 열기에서 예의를 지키려고 한 말로 알맞은 것은 무엇인가요?","options":[{"t":"「바쁘실 텐데 귀한 시간 내어 면담에 참여해 주셔서 감사합니다.」","correct":true},{"t":"「시간이 없으니 빨리빨리 대답해 주세요.」","mis":"K6-2-u2-X10"},{"t":"「질문이 많으니 대답은 짧게만 말씀해 주세요.」","mis":"K6-2-u2-X10"},{"t":"「녹화는 저희가 알아서 할게요. 시작하겠습니다.」","mis":"K6-2-u2-X11"}],"explanation":["면담 열기에서는 인사하고 감사한 마음을 표현해요.","「만나 뵙게 되어 반갑습니다.」도 예의를 지킨 말이에요.","녹음·녹화는 반드시 동의를 구해요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"안녕하세요? 만나 뵙게 되어 반갑습니다. 저희는 ○○초등학교 6학년 학생들입니다. 바쁘실 텐데 귀한 시간 내어 면담에 참여해 주셔서 감사합니다."},{"who":"로봇 공학자","text":"(간추림) 반갑게 인사하며, 로봇 공학에 관심 있는 학생들과 이야기하게 되어 기쁘다고 했다."},{"who":"학생","text":"면담을 요청드릴 때 말씀드린 것처럼 오늘은 로봇 공학자가 하는 일과 로봇 공학자가 되기 위해 필요한 태도 같은 것들을 여쭈어보고자 합니다."},{"who":"학생","text":"답변을 정확하게 정리하기 위해 녹음이나 녹화를 해도 괜찮을까요?"},{"who":"로봇 공학자","text":"네, 괜찮습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#14','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',2,'mc','auto','여러 가지 매체를 고려해 면담 내용을 녹음·녹화할 때 먼저 해야 할 일은 무엇인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":14,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"여러 가지 매체를 고려해 면담 내용을 녹음·녹화할 때 먼저 해야 할 일은 무엇인가요?","options":[{"t":"면담 대상자의 동의를 얻는다","correct":true},{"t":"녹음 버튼을 몰래 누른다","mis":"K6-2-u2-X11"},{"t":"친구들에게 녹화 영상을 먼저 보낸다","mis":"K6-2-u2-X11"},{"t":"녹음기만 준비하고 아무 말도 하지 않는다","mis":"K6-2-u2-X11"}],"explanation":["녹음·녹화는 동의를 얻은 뒤에 해요.","면담 열기에서 동의를 구해요.","『국어』 95쪽 도움말의 내용이에요."],"asset":{"type":"passage","lines":["여러 가지 매체를 고려해 면담 내용을 녹음·녹화할 때에는","먼저 면담 대상자의 동의를 얻어야 해요.","면담 대상자의 동의를 얻어서 녹음·녹화한 자료는","인터넷에 올리거나 다른 사람에게 퍼뜨리면 안 돼요."],"title":"『국어』 95쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#15','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C8',2,'mc','auto','면담 역할 가운데에서 질문 담당이 하는 일은 무엇인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":15,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"면담 역할 가운데에서 질문 담당이 하는 일은 무엇인가요?","options":[{"t":"질문을 모아 의논해 정하고 예의 바른 표현으로 다듬는다","correct":true},{"t":"면담 대상자와 날짜, 시간, 장소를 정하고 알린다","mis":"K6-2-u2-X19"},{"t":"녹음·녹화 기기를 준비하고 면담 내용을 담는다","mis":"K6-2-u2-X19"},{"t":"메모한 내용을 정리해 보고서 자료를 만든다","mis":"K6-2-u2-X19"}],"explanation":["약속 담당은 날짜, 시간, 장소를 정해요.","매체 담당은 녹음·녹화 기기를 준비해요.","질문 담당은 질문을 모으고 다듬어요."],"asset":{"type":"passage","lines":["㉮ 면담의 전 과정을 살피고, 시간을 조정하며 질문하고 면담을 진행한다.","㉯ 예의를 갖추어 면담 약속(날짜, 시간, 장소)을 잡고 모둠원에게 알린다.","㉰ 친구들과 작성한 질문을 모아 의논해 정하고, 예의 바른 표현으로 다듬는다.","㉱ 녹음·녹화 기기를 준비하고, 면담 내용을 녹음·녹화해 친구들과 공유한다.","㉲ 면담 내용을 귀 기울여 듣고 핵심을 메모해, 보고서에 필요한 자료를 정리한다."],"numbered":false,"title":"역할마다 해야 할 일 — 『국어』 99쪽 (6) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#16','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C10',2,'mc','auto','「강아지똥」에게 한 질문 「민들레꽃을 피우려고 어떤 일을 했나요?」는 어떤 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":16,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"「강아지똥」에게 한 질문 「민들레꽃을 피우려고 어떤 일을 했나요?」는 어떤 질문인가요?","options":[{"t":"구체적인 사실에 대한 질문","correct":true},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"작품과 상관없는 질문","mis":"K6-2-u2-X07"}],"explanation":["강아지똥이 한 일을 물었어요.","있었던 일을 묻는 질문은 구체적인 사실에 대한 질문이에요.","마음을 물으면 생각이나 느낌에 대한 질문이에요."],"asset":{"type":"passage","lines":["구체적인 사실에 대한 질문 — 민들레꽃을 피우려고 어떤 일을 했나요?","생각이나 느낌에 대한 질문 — 다른 인물들이 자신을 하찮게 볼 때","   스스로를 어떻게 생각했나요?","앞으로의 계획이나 당부에 대한 질문 — 자신이 쓸모없다고","   생각하는 친구에게 해 줄 말이 있나요?"],"numbered":false,"title":"작품 속 인물 「강아지똥」에게 할 질문 — 『국어』 108쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#17','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',3,'match','auto','『국어』 110쪽 1번처럼 면담에서 할 일과 절차를 바르게 이어 보세요.','{}'::text[],false,'{"seq":17,"concept":"K6-2-u2-C3","difficulty":3,"kind":"match","stem":"『국어』 110쪽 1번처럼 면담에서 할 일과 절차를 바르게 이어 보세요.","pairs":[{"l":"녹음·녹화 동의 구하기","r":"면담 진행하기"},{"l":"면담 과정 성찰하기","r":"면담 정리하기"},{"l":"면담 목적에 알맞은 자료 찾기","r":"면담 준비하기"}],"mis":"K6-2-u2-X05","explanation":["자료 찾기는 만나기 전에 하는 준비예요.","녹음·녹화 동의는 만나서 면담을 열 때 구해요.","성찰은 면담을 마친 뒤 정리하며 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#18','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',3,'mc','auto','보기의 ㉠~㉥ 가운데에서 「면담 열기」에서 할 일을 모두 고른 것은 무엇인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":18,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"보기의 ㉠~㉥ 가운데에서 「면담 열기」에서 할 일을 모두 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉢, ㉣, ㉥","mis":"K6-2-u2-X05"},{"t":"㉤","mis":"K6-2-u2-X05"},{"t":"㉠, ㉤","mis":"K6-2-u2-X05"}],"explanation":["면담 열기에서는 가벼운 인사말을 나누고 목적을 설명해요.","질문하기에서는 세 기준의 질문을 해요.","감사 인사는 면담 마무리하기에서 해요."],"asset":{"type":"passage","lines":["보기","㉠ 면담 목적 설명하기","㉡ 가벼운 인사말 나누기","㉢ 구체적인 사실에 대한 질문하기","㉣ 생각이나 느낌에 대한 질문하기","㉤ 면담을 마친 뒤 감사 인사하기","㉥ 앞으로의 계획이나 당부에 대한 질문하기"],"numbered":false,"title":"면담 진행하기에서 할 일 — 『국어』 111쪽 2번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#19','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',3,'mc','auto','윤서네 모둠의 질문 ㉣ 「좋아하는 색깔은 무엇인가요?」가 면담 목적에 맞지 않는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X08']::text[],false,'{"seq":19,"concept":"K6-2-u2-C4","difficulty":3,"kind":"mc","stem":"윤서네 모둠의 질문 ㉣ 「좋아하는 색깔은 무엇인가요?」가 면담 목적에 맞지 않는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"사서라는 직업을 알아보는 면담 목적과 이어지지 않기 때문","correct":true},{"t":"질문이 너무 짧아서 대답도 짧게 나오기 때문","mis":"K6-2-u2-X10"},{"t":"면담 대상자가 대답하기 어려운 사실을 묻기 때문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부를 묻는 질문이기 때문","mis":"K6-2-u2-X08"}],"explanation":["질문은 면담 목적과 견주어 봐요.","좋아하는 색깔은 사서라는 직업과 이어지지 않아요.","목적에 맞지 않는 질문은 덜어 내거나 고쳐요."],"asset":{"type":"passage","lines":["면담 열기 — 인사하기 · 목적 설명하기 · 녹음·녹화 동의 구하기","질문하기 — ㉠ 현재 맡고 계신 일을 자세히 설명해 주실 수 있나요?","  ㉡ 사서가 되려면 어떤 과정을 거쳐야 하나요?","  ㉢ 사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?","  ㉣ 좋아하는 색깔은 무엇인가요?","  ㉤ 근무하시면서 가장 보람을 느꼈던 순간은 언제이고, 그 까닭은 무엇인가요?","  ㉥ 사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?","면담 마무리하기 — 면담 결과 확인하기 · 감사 인사 하기"],"numbered":false,"title":"면담 개요 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#20','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',3,'mc','auto','모둠의 보완할 점을 다음 면담에서 실천할 점으로 바르게 바꾼 것은 무엇인가요?',ARRAY['K6-2-u2-X19','K6-2-u2-X14']::text[],false,'{"seq":20,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"모둠의 보완할 점을 다음 면담에서 실천할 점으로 바르게 바꾼 것은 무엇인가요?","options":[{"t":"보완할 점: 면담 대상자의 말에 집중하지 않은 친구가 있었다. → 실천할 점: 다음 면담에서는 면담 대상자의 말을 경청하기로 약속한다.","correct":true},{"t":"보완할 점: 집중하지 않은 친구가 있었다. → 실천할 점: 그 친구를 다음 면담에서 뺀다.","mis":"K6-2-u2-X19"},{"t":"보완할 점: 집중하지 않은 친구가 있었다. → 실천할 점: 그 친구의 이름을 보고서에 쓴다.","mis":"K6-2-u2-X14"},{"t":"보완할 점: 집중하지 않은 친구가 있었다. → 실천할 점: 실천할 점은 없다.","mis":"K6-2-u2-X14"}],"explanation":["보완할 점은 사람 탓이 아니라 다음 약속으로 바꾸어요.","모둠 모두가 지킬 수 있게 정해요.","『국어』 103쪽 예시는 「경청하기로 약속한다.」예요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 모둠 친구들이 사이좋게 의논해서","   면담 역할을 잘 정했다.","보완할 점 — 면담을 진행할 때 면담 대상자의 말에 집중하지 않은 친구가 있었다.","다음 면담에서 실천할 점(우리 모둠의 약속) — 다음 면담에서는","   면담 대상자의 말을 경청하기로 약속한다."],"numbered":false,"title":"우리 모둠의 면담 과정 정리 — 『국어』 103쪽 (3) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#21','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C14',3,'mc','auto','「면담 대상자를 정할 때에는 학생들과 면담이 가능한 분인지가 중요해요.」 우리 학교 학생들의 진로를 알아보려는 모둠이 면담 대상자를 고르는 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X20','K6-2-u2-X07']::text[],false,'{"seq":21,"concept":"K6-2-u2-C14","difficulty":3,"kind":"mc","stem":"「면담 대상자를 정할 때에는 학생들과 면담이 가능한 분인지가 중요해요.」 우리 학교 학생들의 진로를 알아보려는 모둠이 면담 대상자를 고르는 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"목적에 맞고, 우리가 연락할 수 있으며 학생들과 면담이 가능한 주변 인물을 고른다","correct":true},{"t":"텔레비전에 나오는 가장 유명한 사람을 고른다","mis":"K6-2-u2-X20"},{"t":"연락할 방법이 없어도 만나고 싶은 사람이면 고른다","mis":"K6-2-u2-X20"},{"t":"목적과 상관없이 가장 친한 친구를 면담 대상자로 고른다","mis":"K6-2-u2-X07"}],"explanation":["면담 대상자는 먼저 목적에 맞아야 해요.","학생들과 면담이 가능한 분인지 살펴요.","우리가 연락할 수 있는 주변 인물인지도 생각해요."],"asset":{"type":"passage","lines":["면담 대상자를 정할 때에는 학생들과 면담이 가능한 분인지가 중요해요.","또 우리가 연락할 수 있는 주변 인물인지 생각해 봐요."],"title":"『국어』 97쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#22','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',3,'mc','auto','「스스로 확인하기」에서 면담 준비하기에 매체를 고려할 때 주의할 점으로 정리한 것은 무엇인가요?',ARRAY['K6-2-u2-X09','K6-2-u2-X11','K6-2-u2-X04']::text[],false,'{"seq":22,"concept":"K6-2-u2-C7","difficulty":3,"kind":"mc","stem":"「스스로 확인하기」에서 면담 준비하기에 매체를 고려할 때 주의할 점으로 정리한 것은 무엇인가요?","options":[{"t":"면담 목적과 관련 있는 정보만 검색하기","correct":true},{"t":"찾은 정보는 출처를 확인하지 않고 모두 쓰기","mis":"K6-2-u2-X09"},{"t":"녹음·녹화한 자료를 친구들에게 보내기","mis":"K6-2-u2-X11"},{"t":"면담 대상자의 개인 정보를 검색하기","mis":"K6-2-u2-X04"}],"explanation":["준비하기에서는 인터넷이나 책으로 자료를 찾아요.","이때 면담 목적과 관련 있는 정보만 검색해요.","개인 정보는 찾지도 묻지도 않아요."],"asset":{"type":"passage","lines":["면담 준비하기 — 주의할 점: 면담 목적과 관련 있는 정보만 검색하기","   매체 활용: 인터넷이나 책을 활용해 면담에 필요한 자료 찾기","면담 진행하기 — 주의할 점: 녹음·녹화할 때에는 먼저 면담 대상자의 동의 얻기","   매체 활용: 녹음기로 녹음하며 대면 면담, 영상 통화로 비대면 면담","면담 정리하기 — 주의할 점: 녹음·녹화한 자료는 퍼뜨리지 않고 보고서에만 쓰기","   매체 활용: 녹음한 내용을 확인하며 중요한 내용 요약하기"],"numbered":false,"title":"스스로 확인하기 — 『국어』 112쪽 (1) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#23','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C6',4,'essay','teacher','면담 목적과 면담 대상자를 정하고, 면담 대상자에게 할 질문을 세 기준(구체적인 사실 · 생각이나 느낌 · 앞으로의 계획이나 당부)마다 하나씩 만드세요. 그리고 만든 질문을 점검 기준 하나로 확인해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u2-C6","difficulty":4,"kind":"essay","stem":"면담 목적과 면담 대상자를 정하고, 면담 대상자에게 할 질문을 세 기준(구체적인 사실 · 생각이나 느낌 · 앞으로의 계획이나 당부)마다 하나씩 만드세요. 그리고 만든 질문을 점검 기준 하나로 확인해 쓰세요.","answer_guide":{"answer":"예: 면담 목적 — 소방관이 하는 일을 알아보려고 · 면담 대상자 — 우리 동네 소방서의 소방관. 구체적인 사실 — 출동하지 않을 때에는 어떤 일을 하시나요? / 생각이나 느낌 — 출동할 때 어떤 마음이 드시나요? / 앞으로의 계획이나 당부 — 불이 났을 때 학생들이 꼭 기억해야 할 것이 있나요? 점검 — 세 질문 모두 소방관이 하는 일을 알아보는 목적에 맞는다.","scoring_points":["면담 목적과 면담 대상자를 정했는가","세 기준의 질문을 하나씩 만들었는가","점검 기준(목적·예의·명료한 표현)으로 확인했는가"]},"explanation":["먼저 무엇을 알고 싶은지 목적을 정해요.","세 기준으로 질문을 골고루 만들어요.","면담 대상자를 배려해 불편한 질문은 고치거나 빼요."],"asset":{"type":"passage","lines":["● 면담 목적에 맞게 질문을 만들었나요?","● 면담 대상자에게 예의를 갖추어 표현했나요?","● 면담 대상자가 이해할 수 있는 명료한 표현을 사용했나요?"],"numbered":false,"title":"자신이 만든 질문 스스로 확인하기 — 『국어』 93쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#24','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',4,'essay','teacher','미래에 꿈을 이룬 친구를 면담한다고 생각해 보세요. 그 친구의 직업을 정하고, 매체를 고려해 면담 질문을 세 기준마다 하나씩 만드세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C7","difficulty":4,"kind":"essay","stem":"미래에 꿈을 이룬 친구를 면담한다고 생각해 보세요. 그 친구의 직업을 정하고, 매체를 고려해 면담 질문을 세 기준마다 하나씩 만드세요.","answer_guide":{"answer":"예: 면담 대상자 직업 — 로봇 공학자가 된 친구(영상 통화로 비대면 면담). 구체적인 사실 — 요즘 어떤 로봇을 만들고 있니? / 생각이나 느낌 — 그 로봇이 처음 움직였을 때 어떤 기분이 들었니? / 앞으로의 계획이나 당부 — 앞으로 꼭 만들고 싶은 로봇이 있니?","scoring_points":["미래 친구의 직업과 면담 방식을 정했는가","세 기준의 질문을 하나씩 만들었는가","직업과 이어지는 질문인가"]},"explanation":["친구가 꿈을 이룬 모습을 떠올려요.","대면인지 비대면인지 매체를 고려해 정해요.","세 기준으로 질문을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_a#25','kor',6,2,'u2','','tb_g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',4,'essay','teacher','이 단원에서 살펴본 면담 하나(윤서네 모둠 · 로봇 공학자 · 민수네 모둠)를 골라, 그 면담으로 면담 보고서를 쓴다면 앞부분·가운데 부분·뒷부분에 무엇을 쓸지 한두 문장씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"이 단원에서 살펴본 면담 하나(윤서네 모둠 · 로봇 공학자 · 민수네 모둠)를 골라, 그 면담으로 면담 보고서를 쓴다면 앞부분·가운데 부분·뒷부분에 무엇을 쓸지 한두 문장씩 쓰세요.","answer_guide":{"answer":"예: 고른 면담 — 「윤서네 모둠의 면담」. 앞부분 — 친구들에게 도서관 사서라는 직업을 알리는 글을 쓰려고 공공 도서관 사서와 대면 면담을 했다. 가운데 부분 — 사서가 하는 일, 사서가 되는 과정, 필요한 능력, 보람, 학생들에게 해 준 말을 소개한다. 뒷부분 — 사서가 하는 일이 생각보다 많다는 것을 알았고, 도서관을 이용할 때 사서 선생님께 더 감사하게 되었다.","scoring_points":["앞부분에 목적·대상자·준비를 썼는가","가운데 부분에 면담으로 새롭게 안 사실을 썼는가","뒷부분에 느낀 점이나 달라진 생각을 썼는가"]},"explanation":["보고서는 앞·가운데·뒤가 하는 일이 달라요.","가운데 부분은 면담 대상자의 답변이 중심이에요.","뒷부분에는 깨달은 점과 달라진 생각을 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#1','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C1',1,'ox','auto','면담은 친해지려고 아무 이야기나 나누는 일상 대화와 같아요.',ARRAY['K6-2-u2-X01']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"ox","stem":"면담은 친해지려고 아무 이야기나 나누는 일상 대화와 같아요.","answer":"X","reason_options":[{"t":"면담은 정보를 얻으려는 목적이 있고 준비와 예의가 필요한 대화이기 때문에","correct":true},{"t":"면담과 일상 대화는 모두 목적 없이 나누는 말이기 때문에","mis":"K6-2-u2-X01"}],"mis":"K6-2-u2-X01","explanation":["면담은 정보를 얻으려고 주고받는 대화예요.","그래서 사전 준비와 예의가 필요해요.","일상 대화와 다르니 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#2','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C2',1,'mc','auto','『국어』 80쪽 도움말에 나온 면담 요청 방법이 아닌 것은 무엇인가요?',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 80쪽 도움말에 나온 면담 요청 방법이 아닌 것은 무엇인가요?","options":[{"t":"약속 없이 면담 대상자의 집 앞에서 기다리기","correct":true},{"t":"면담할 곳에 직접 방문해 요청하기","mis":"K6-2-u2-X03"},{"t":"전자 우편으로 요청하는 글 보내기","mis":"K6-2-u2-X03"},{"t":"누리집에 문의하는 글 올리기","mis":"K6-2-u2-X03"}],"explanation":["면담 요청은 방문, 전화, 전자 우편, 누리집 글로 할 수 있어요.","어느 방법이든 먼저 허락을 구해요.","약속 없이 기다리는 것은 요청이 아니에요."],"asset":{"type":"passage","lines":["면담 요청은 현장에 직접 방문하거나 전화하기,","전자 우편 보내기, 누리집에 문의하는 글 올리기처럼","다양한 방법으로 할 수 있어요."],"title":"『국어』 80쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#3','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',1,'sa','auto','면담 진행하기는 면담 열기, (    ), 면담 마무리하기로 이루어져요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"sa","stem":"면담 진행하기는 면담 열기, (    ), 면담 마무리하기로 이루어져요. 빈칸에 알맞은 말을 쓰세요.","answer":["질문하기","질문"],"explanation":["면담 열기에서는 인사하고 목적을 설명해요.","질문하기에서는 질문하고 답변을 들어요.","면담 마무리하기에서는 결과를 확인하고 감사 인사를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#4','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C4',1,'mc','auto','「사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?」는 어떤 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"「사서가 되고 싶은 학생들에게 해 주고 싶은 말씀은 무엇인가요?」는 어떤 질문인가요?","options":[{"t":"앞으로의 계획이나 당부에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적에 맞지 않는 질문","mis":"K6-2-u2-X07"}],"explanation":["학생들에게 해 주고 싶은 말은 당부예요.","그래서 앞으로의 계획이나 당부에 대한 질문이에요.","『국어』 85쪽에서 ㉥이 여기에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#5','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C5',1,'ox','auto','후속 질문은 면담 대상자의 대답과 상관없이 미리 준비한 다음 질문을 읽는 거예요.',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":1,"kind":"ox","stem":"후속 질문은 면담 대상자의 대답과 상관없이 미리 준비한 다음 질문을 읽는 거예요.","answer":"X","reason_options":[{"t":"후속 질문은 앞선 대답을 듣고 이어서 하는 질문이기 때문에","correct":true},{"t":"후속 질문은 질문지 맨 뒤에 적어 둔 질문이기 때문에","mis":"K6-2-u2-X06"}],"mis":"K6-2-u2-X06","explanation":["미리 준비한 질문을 차례대로 읽는 것은 후속 질문이 아니에요.","대답 속의 말을 붙들어 이어서 물어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#6','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C7',1,'sa','auto','면담 대상자를 직접 만나서 서로 얼굴을 마주 보고 대하는 면담을 무엇이라고 하는지 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"sa","stem":"면담 대상자를 직접 만나서 서로 얼굴을 마주 보고 대하는 면담을 무엇이라고 하는지 쓰세요.","answer":["대면 면담","대면"],"explanation":["직접 만나 얼굴을 마주 보아요.","이런 면담을 대면 면담이라고 해요.","그렇지 않으면 비대면 면담이에요."],"asset":{"type":"passage","lines":["보기: 대면 · 비대면","(    ㉠    ) 면담 — 면담 대상자를 직접 만나서 서로 얼굴을 마주 보고 대하는 면담","(    ㉡    ) 면담 — 면담 대상자를 직접 만나지 않거나 서로 얼굴을 마주 보고","   대하지 않는 면담"],"numbered":false,"title":"면담 방식 정리하기 — 『국어』 94쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#7','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',1,'mc','auto','면담 보고서 뒷부분에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X15']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 보고서 뒷부분에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"면담을 마친 뒤 깨달은 점과 달라진 생각","correct":true},{"t":"면담 목적과 면담 대상자","mis":"K6-2-u2-X15"},{"t":"모둠 친구들의 역할","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 답변을 옮긴 내용","mis":"K6-2-u2-X15"}],"explanation":["뒷부분은 면담 소감을 쓰는 곳이에요.","깨달은 점과 달라진 생각을 정리해요.","인상 깊었던 답변을 들어 쓰면 좋아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#8','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C11',1,'mc','auto','「걱정할 필요 없어.」에서 「없어」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「걱정할 필요 없어.」에서 「없어」의 바른 발음은 무엇인가요?","options":[{"t":"[업ː써]","correct":true},{"t":"[어버]","mis":"K6-2-u2-X18"},{"t":"[업어]","mis":"K6-2-u2-X18"},{"t":"[엇어]","mis":"K6-2-u2-X18"}],"explanation":["「없」의 겹받침은 ㅄ이에요.","모음 「어」가 붙으면 ㅅ이 넘어가며 된소리로 나요.","그래서 [업ː써]로 소리 나요."],"asset":{"type":"passage","lines":["가 사과가 수박보다 값이[갑씨] 싸구나!","나 밥 먹을 때에는 자리에 앉아서[안자서] 먹자.","다 자연환경을 보호하면 우리 삶이[살ː미] 풍요로워질 거예요.","라 블록이 무너질 것 같아 불안해요. — 걱정할 필요 없어[업ː써]. 지금 잘하고 있어."],"numbered":false,"title":"기초 다지기 1 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#9','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C12',2,'mc','auto','「윤서네 모둠의 면담」에서 사서가 말한, 사서가 되는 과정은 무엇인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X13']::text[],false,'{"seq":9,"concept":"K6-2-u2-C12","difficulty":2,"kind":"mc","stem":"「윤서네 모둠의 면담」에서 사서가 말한, 사서가 되는 과정은 무엇인가요?","options":[{"t":"문헌정보학을 공부하고 사서 자격증을 딴 뒤 채용 절차를 거친다","correct":true},{"t":"심리학을 전공하고 자격증을 따서 교원 임용 시험을 치른다","mis":"K6-2-u2-X15"},{"t":"간호학을 전공하고 간호사 면허와 자격증을 딴다","mis":"K6-2-u2-X15"},{"t":"따로 공부하지 않고 책을 많이 읽으면 된다","mis":"K6-2-u2-X13"}],"explanation":["㉡ 「사서가 되려면 어떤 과정을 거쳐야 하나요?」의 답이에요.","문헌정보학 공부, 사서 자격증, 채용 절차예요.","면담 내용을 질문과 답변 중심으로 정리해요."],"asset":{"type":"passage","lines":["(간추림) ㉠ 대출·반납 돕기, 새 책 주문, 책 정리, 독서 행사나 프로그램 준비","(간추림) ㉡ 대학에서 문헌정보학 공부 → 사서 자격증 → 도서관 채용 절차","(간추림) ㉢ 소통 능력, 검색 능력, 꼼꼼함","(간추림) ㉤ 추천한 책이 도움이 됐다는 말을 들을 때","(간추림) ㉥ 책을 읽는 습관과 궁금한 것을 스스로 찾아보는 습관 기르기"],"numbered":false,"title":"「윤서네 모둠의 면담」 질문과 답변 정리 (듣기 자료 · 『국어』 86쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#10','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C13',2,'mc','auto','로봇을 여러 번 시험해야 하는 까닭은 무엇이라고 했나요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":10,"concept":"K6-2-u2-C13","difficulty":2,"kind":"mc","stem":"로봇을 여러 번 시험해야 하는 까닭은 무엇이라고 했나요?","options":[{"t":"오류를 찾아 고치고 성능을 높여 더 정확하고 안전하게 움직이게 하려고","correct":true},{"t":"시험하는 과정이 재미있어서 여러 번 해 보려고","mis":"K6-2-u2-X13"},{"t":"부품을 많이 써서 로봇을 더 크게 만들려고","mis":"K6-2-u2-X13"},{"t":"면담 시간에 보여 줄 장면을 많이 찍어 두려고","mis":"K6-2-u2-X13"}],"explanation":["학생이 후속 질문으로 까닭을 물었어요.","시험하며 오류를 찾고 문제점을 고쳐요.","그래서 로봇이 더 정확하고 안전해져요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"로봇 공학자가 로봇을 만들 때 가장 먼저 해야 하는 일은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 로봇이 풀어야 할 문제부터 정한다. 사람을 도울지, 위험한 곳에 대신 갈지 정한 뒤 모양과 기능을 설계하고 부품을 고르고, 프로그램을 만들어 여러 번 시험한다."},{"who":"학생","text":"로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 시험하면서 오류를 찾아 고치고 성능을 높여 로봇이 더 정확하고 안전하게 움직이게 하려는 것이다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#11','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C14',2,'mc','auto','민수네 모둠의 질문 ㉥ 「이 직업의 전망과 관련해 학생들에게 해 주실 말씀은 무엇인가요?」는 어떤 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":11,"concept":"K6-2-u2-C14","difficulty":2,"kind":"mc","stem":"민수네 모둠의 질문 ㉥ 「이 직업의 전망과 관련해 학생들에게 해 주실 말씀은 무엇인가요?」는 어떤 질문인가요?","options":[{"t":"앞으로의 계획이나 당부에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적에 맞지 않는 질문","mis":"K6-2-u2-X07"}],"explanation":["학생들에게 해 주실 말씀을 물었어요.","앞일과 당부를 묻는 질문이에요.","㉤·㉥이 앞으로의 계획이나 당부에 대한 질문이에요."],"asset":{"type":"passage","lines":["㉠ 상담 교사가 되려면 어떤 준비를 해야 하나요?","㉡ 상담 교사는 학교에서 주로 어떤 일을 하나요?","㉢ 상담 교사가 되고 난 뒤 가장 보람 있었던 일은 무엇인가요?","㉣ 상담 교사로서 학생들을 만날 때 가장 힘든 점은 무엇인가요?","㉤ 상담 교사로서 앞으로 꼭 하고 싶은 일은 무엇인가요?","㉥ 이 직업의 전망과 관련해 학생들에게 해 주실 말씀은 무엇인가요?"],"numbered":false,"title":"민수네 모둠의 질문하기 — 『국어』 100쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#12','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C15',2,'mc','auto','하늘 모둠에서 정리 담당을 맡은 친구는 누구인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":12,"concept":"K6-2-u2-C15","difficulty":2,"kind":"mc","stem":"하늘 모둠에서 정리 담당을 맡은 친구는 누구인가요?","options":[{"t":"현수","correct":true},{"t":"현지","mis":"K6-2-u2-X19"},{"t":"원주","mis":"K6-2-u2-X19"},{"t":"기철","mis":"K6-2-u2-X19"}],"explanation":["현지는 약속 담당, 원주는 질문 담당이에요.","기철이는 매체(녹음·녹화) 담당이에요.","현수는 정리 담당이에요."],"asset":{"type":"passage","lines":["(간추림) 우리 모둠은 상담 교사가 되는 방법과 역할을 알아보자는 목적으로","(간추림) 상담 선생님과 면담을 했다.","(간추림) 선생님과 상담한 적이 있는 현지가 약속 담당을 맡아 요청이 쉬웠다.","(간추림) 원주는 질문, 기철이는 매체(녹음·녹화), 현수는 정리,","(간추림) 나는 면담 진행을 맡았다. 각자의 역할을 충실히 하며 면담을 마쳤다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 앞부분 — 『국어』 104쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#13','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',2,'blank','auto','자신이 만든 질문을 스스로 확인하는 기준이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#14','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C7',2,'ox','auto','면담 대상자의 동의를 얻어 녹화한 자료는 인터넷에 올려도 괜찮아요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":14,"concept":"K6-2-u2-C7","difficulty":2,"kind":"ox","stem":"면담 대상자의 동의를 얻어 녹화한 자료는 인터넷에 올려도 괜찮아요.","answer":"X","reason_options":[{"t":"동의를 얻은 자료라도 인터넷에 올리거나 다른 사람에게 퍼뜨리면 안 되기 때문에","correct":true},{"t":"동의를 얻었으면 어디에 써도 되기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["녹음·녹화한 자료는 면담 보고서를 쓸 때에만 써요.","인터넷에 올리거나 퍼뜨리면 안 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["여러 가지 매체를 고려해 면담 내용을 녹음·녹화할 때에는","먼저 면담 대상자의 동의를 얻어야 해요.","면담 대상자의 동의를 얻어서 녹음·녹화한 자료는","인터넷에 올리거나 다른 사람에게 퍼뜨리면 안 돼요."],"title":"『국어』 95쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#15','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C8',2,'mc','auto','면담 역할 가운데에서 정리 담당이 하는 일은 무엇인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":15,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"면담 역할 가운데에서 정리 담당이 하는 일은 무엇인가요?","options":[{"t":"면담 내용을 귀 기울여 듣고 핵심을 메모해 보고서 자료를 정리한다","correct":true},{"t":"면담의 전 과정을 살피며 시간을 조정하고 진행한다","mis":"K6-2-u2-X19"},{"t":"면담 약속(날짜, 시간, 장소)을 모둠원에게 알린다","mis":"K6-2-u2-X19"},{"t":"녹음·녹화한 내용을 모둠 친구들과 공유한다","mis":"K6-2-u2-X19"}],"explanation":["진행 담당은 면담을 이끌어요.","정리 담당은 핵심 내용을 메모해요.","메모한 내용으로 보고서 자료를 정리해요."],"asset":{"type":"passage","lines":["㉮ 면담의 전 과정을 살피고, 시간을 조정하며 질문하고 면담을 진행한다.","㉯ 예의를 갖추어 면담 약속(날짜, 시간, 장소)을 잡고 모둠원에게 알린다.","㉰ 친구들과 작성한 질문을 모아 의논해 정하고, 예의 바른 표현으로 다듬는다.","㉱ 녹음·녹화 기기를 준비하고, 면담 내용을 녹음·녹화해 친구들과 공유한다.","㉲ 면담 내용을 귀 기울여 듣고 핵심을 메모해, 보고서에 필요한 자료를 정리한다."],"numbered":false,"title":"역할마다 해야 할 일 — 『국어』 99쪽 (6) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#16','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C10',2,'mc','auto','「바람직한 질문, 불쾌한 질문」 활동에서 찾은 불쾌한 질문의 조건으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":16,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"「바람직한 질문, 불쾌한 질문」 활동에서 찾은 불쾌한 질문의 조건으로 알맞은 것은 무엇인가요?","options":[{"t":"사람의 단점을 파고들거나 비난하려는 의도가 분명하게 느껴지는 질문","correct":true},{"t":"상대가 편하고 즐겁게 대답할 수 있는 질문","mis":"K6-2-u2-X17"},{"t":"상대의 생각을 존중하며 묻는 질문","mis":"K6-2-u2-X17"},{"t":"궁금한 점을 짧고 분명하게 묻는 질문","mis":"K6-2-u2-X17"}],"explanation":["질문을 받고 불쾌했던 기억을 떠올려요.","단점을 파고들거나 비난하려는 질문이 불쾌해요.","이런 질문은 바람직한 질문으로 바꾸어요."],"asset":{"type":"passage","lines":["① 질문을 받았던 기억 떠올리기 — 예: “공부 잘하니?”, “그게 재밌니?”","② 불쾌한 질문의 조건 생각하기 — 예: 사람의 단점을 파고드는 질문,","   비난하려는 의도가 분명하게 느껴지는 질문","③ 바람직한 질문으로 변신시키기 — 예: 공부가 재밌으려면 어떻게 하면 좋을까?","④ 질문 태도 점검표 만들기","⑤ 정리하기 — 점검표를 모둠원과 공유하고 자신의 질문 태도를 점검한다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 1 — 바람직한 질문, 불쾌한 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#17','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',3,'match','auto','면담에서 할 일과 절차를 바르게 이어 보세요.','{}'::text[],false,'{"seq":17,"concept":"K6-2-u2-C3","difficulty":3,"kind":"match","stem":"면담에서 할 일과 절차를 바르게 이어 보세요.","pairs":[{"l":"면담 대상자에게 예의를 지키며 면담 약속 잡기","r":"면담 준비하기"},{"l":"예의 바른 태도로 면담 대상자의 답변 경청하기","r":"면담 진행하기"},{"l":"면담 보고서 쓰기","r":"면담 정리하기"}],"mis":"K6-2-u2-X05","explanation":["약속 잡기는 면담 준비하기에서 해요.","답변 경청은 면담 진행하기에서 해요.","보고서 쓰기는 면담 정리하기에서 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#18','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',3,'mc','auto','보기의 ㉠~㉥ 가운데에서 「질문하기」에서 할 일을 모두 고른 것은 무엇인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X08']::text[],false,'{"seq":18,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"보기의 ㉠~㉥ 가운데에서 「질문하기」에서 할 일을 모두 고른 것은 무엇인가요?","options":[{"t":"㉢, ㉣, ㉥","correct":true},{"t":"㉠, ㉡","mis":"K6-2-u2-X05"},{"t":"㉢, ㉤","mis":"K6-2-u2-X05"},{"t":"㉣, ㉥","mis":"K6-2-u2-X08"}],"explanation":["질문하기에서는 세 기준의 질문을 모두 해요.","구체적인 사실(㉢), 생각이나 느낌(㉣), 앞으로의 계획이나 당부(㉥)예요.","하나라도 빠뜨리지 않아요."],"asset":{"type":"passage","lines":["보기","㉠ 면담 목적 설명하기","㉡ 가벼운 인사말 나누기","㉢ 구체적인 사실에 대한 질문하기","㉣ 생각이나 느낌에 대한 질문하기","㉤ 면담을 마친 뒤 감사 인사하기","㉥ 앞으로의 계획이나 당부에 대한 질문하기"],"numbered":false,"title":"면담 진행하기에서 할 일 — 『국어』 111쪽 2번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#19','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',3,'mc','auto','「내 진로를 더 깊이 이해하려고」 수의사를 면담할 때 점검 기준에 비추어 고쳐야 할 질문은 무엇인가요?',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":19,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「내 진로를 더 깊이 이해하려고」 수의사를 면담할 때 점검 기준에 비추어 고쳐야 할 질문은 무엇인가요?","options":[{"t":"「수의사 선생님의 집은 어디인가요?」","correct":true},{"t":"「주로 어떤 동물을 치료하나요?」","mis":"K6-2-u2-X04"},{"t":"「가장 보람을 느끼는 순간은 언제인가요?」","mis":"K6-2-u2-X04"},{"t":"「수의사가 되고 싶은 학생들에게 해 주실 말씀이 있나요?」","mis":"K6-2-u2-X04"}],"explanation":["집이 어디인지는 공개하기 어려운 개인 정보예요.","면담 목적과도 이어지지 않아요.","질문을 만들면 목적·예의·명료함으로 점검해요."],"asset":{"type":"passage","lines":["구체적인 사실에 대한 질문","  • 주로 어떤 동물을 치료하나요?","  • 수의사가 되기 위해 어떤 공부를 하셨나요?","생각이나 느낌에 대한 질문","  • 가장 보람을 느끼는 순간은 언제인가요?","  • 동물을 치료할 때 어떤 마음이 드나요?","앞으로의 계획이나 당부에 대한 질문","  • 수의사가 되고 싶은 학생들에게 해 주실 말씀이 있나요?"],"numbered":false,"title":"수집한 정보를 바탕으로 만든 질문 예시 — 『국어』 93쪽 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#20','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',3,'mc','auto','면담 과정을 바르게 성찰한 말은 무엇인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":20,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"면담 과정을 바르게 성찰한 말은 무엇인가요?","options":[{"t":"「목적에 맞는 질문은 잘 만들었지만 감사 인사를 못 해서, 다음에는 끝까지 인사하겠다.」","correct":true},{"t":"「면담 대상자의 목소리가 작아서 면담이 별로였고 지루했다.」","mis":"K6-2-u2-X14"},{"t":"「면담이 그냥 재미있었고 다음에도 재미있으면 좋겠다.」","mis":"K6-2-u2-X14"},{"t":"「면담이 잘 안 된 것은 모두 진행을 맡은 친구 탓이다.」","mis":"K6-2-u2-X14"}],"explanation":["성찰은 절차마다 무엇을 했는지 돌아보는 일이에요.","잘한 점과 보완할 점을 함께 찾아요.","보완할 점은 다음에 할 행동으로 바꾸어요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 면담 목적에 맞는 질문을 잘 만들었다.","보완할 점 — 면담을 마무리하고 난 뒤에 면담 대상자에게 감사 인사를","   제대로 못 했다.","더 알고 싶은 점 — 상담 교사가 꿈인 친구들에게 도움이 되는 책이 무엇인지 궁금하다."],"numbered":false,"title":"자신의 면담 과정 정리 — 『국어』 102쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#21','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C2',3,'mc','auto','「학교 전담 경찰관이 정확히 어떤 일을 하는지 궁금해.」라는 목적에 맞는 면담 대상자는 누구인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X20']::text[],false,'{"seq":21,"concept":"K6-2-u2-C2","difficulty":3,"kind":"mc","stem":"「학교 전담 경찰관이 정확히 어떤 일을 하는지 궁금해.」라는 목적에 맞는 면담 대상자는 누구인가요?","options":[{"t":"학교에 교육을 하러 오시는 학교 전담 경찰관","correct":true},{"t":"학교 도서관에서 일하시는 사서","mis":"K6-2-u2-X07"},{"t":"유기 동물 보호 센터 직원","mis":"K6-2-u2-X07"},{"t":"경찰이 나오는 영화의 배우","mis":"K6-2-u2-X20"}],"explanation":["목적을 분명하게 정해야 대상자를 정할 수 있어요.","경찰관이 하는 일은 경찰관에게 물어야 해요.","만화 속 두 학생도 학교 전담 경찰관께 면담을 부탁드렸어요."],"asset":{"type":"speech","turns":[{"who":"학생 1","text":"내일 학교에 학교 전담 경찰관이 와서 교육을 해 주신대."},{"who":"학생 2","text":"나도 들었어. 그런데 학교 전담 경찰관이 정확히 어떤 일을 하는지 궁금해."},{"who":"학생 1","text":"맞아. 나도 평소에 궁금한 점이 많았어. 그럼 학교 전담 경찰관님께 면담을 부탁드려 보자."},{"who":"학생 2","text":"좋아! 그렇다면 내일 경찰관님께 할 질문도 미리 만들어 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#22','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C7',3,'mc','auto','「스스로 확인하기」에서 면담 정리하기에 매체를 활용하는 방법으로 정리한 것은 무엇인가요?',ARRAY['K6-2-u2-X11','K6-2-u2-X13','K6-2-u2-X12']::text[],false,'{"seq":22,"concept":"K6-2-u2-C7","difficulty":3,"kind":"mc","stem":"「스스로 확인하기」에서 면담 정리하기에 매체를 활용하는 방법으로 정리한 것은 무엇인가요?","options":[{"t":"녹음한 내용을 확인하며 중요한 내용 요약하기","correct":true},{"t":"녹음한 내용을 누리집에 올리기","mis":"K6-2-u2-X11"},{"t":"녹음한 내용을 한 글자도 빼지 않고 받아 적기","mis":"K6-2-u2-X13"},{"t":"녹음기로 녹음하며 대면 면담 진행하기","mis":"K6-2-u2-X12"}],"explanation":["정리하기에서는 녹음한 내용을 다시 확인해요.","중요한 내용을 골라 요약해요.","녹음하며 면담하는 것은 진행하기의 일이에요."],"asset":{"type":"passage","lines":["면담 준비하기 — 주의할 점: 면담 목적과 관련 있는 정보만 검색하기","   매체 활용: 인터넷이나 책을 활용해 면담에 필요한 자료 찾기","면담 진행하기 — 주의할 점: 녹음·녹화할 때에는 먼저 면담 대상자의 동의 얻기","   매체 활용: 녹음기로 녹음하며 대면 면담, 영상 통화로 비대면 면담","면담 정리하기 — 주의할 점: 녹음·녹화한 자료는 퍼뜨리지 않고 보고서에만 쓰기","   매체 활용: 녹음한 내용을 확인하며 중요한 내용 요약하기"],"numbered":false,"title":"스스로 확인하기 — 『국어』 112쪽 (1) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#23','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C4',4,'essay','teacher','활동지 예처럼, 면담 목적과 관련해 수집한 내용 하나를 쓰고 그 내용을 바탕으로 면담 질문을 만드세요. 그 질문이 왜 좋은 질문인지도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u2-C4","difficulty":4,"kind":"essay","stem":"활동지 예처럼, 면담 목적과 관련해 수집한 내용 하나를 쓰고 그 내용을 바탕으로 면담 질문을 만드세요. 그 질문이 왜 좋은 질문인지도 쓰세요.","answer_guide":{"answer":"예: 수집한 내용 — 사서는 대출·반납 말고도 독서 행사나 프로그램을 준비한다. 면담 질문 — 「독서 행사를 준비하실 때 가장 신경 쓰는 점은 무엇인가요?」 좋은 까닭 — 미리 찾은 정보를 바탕으로 사서 선생님만 답할 수 있는 내용을 더 깊이 물을 수 있다.","scoring_points":["수집한 내용을 썼는가","수집한 내용을 바탕으로 질문을 만들었는가","그 질문이 좋은 까닭을 썼는가"]},"explanation":["수집한 정보는 질문을 깊게 만드는 바탕이에요.","찾아보면 알 수 있는 것은 다시 묻지 않아요.","그분만 답할 수 있는 것을 물어요."],"asset":{"type":"passage","lines":["수집한 내용 — 경찰의 업무는 수사, 안전, 경비, 교통, 정보 분야로 나뉩니다.","면담 질문 — 경찰의 업무에는 수사, 안전, 경비, 교통, 정보 등이 있다고 하는데,","   지금 어떤 업무를 하고 계신가요?"],"numbered":false,"title":"수집한 내용을 바탕으로 면담 질문 만들기 (활동지 예)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#24','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',4,'essay','teacher','미래의 친구와 면담할 때 「면담 열기 - 질문하기 - 면담 마무리하기」의 흐름에 따라 할 말을 한 문장씩 쓰세요. 매체를 고려할 때 지킬 예절이 하나 이상 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C3","difficulty":4,"kind":"essay","stem":"미래의 친구와 면담할 때 「면담 열기 - 질문하기 - 면담 마무리하기」의 흐름에 따라 할 말을 한 문장씩 쓰세요. 매체를 고려할 때 지킬 예절이 하나 이상 드러나게 쓰세요.","answer_guide":{"answer":"예: 면담 열기 — 「안녕? 바쁜데 면담에 응해 줘서 고마워. 네가 하는 일을 알고 싶어서 면담을 부탁했어. 정확히 정리하려고 녹음해도 괜찮을까?」 질문하기 — 「요즘 하루를 어떻게 보내고 있니?」 면담 마무리하기 — 「오늘 네 일을 자세히 알게 됐어. 녹음한 내용은 면담 보고서를 쓸 때에만 쓸게. 정말 고마워.」","scoring_points":["열기·질문하기·마무리의 흐름에 맞게 썼는가","녹음·녹화 동의나 자료를 보고서에만 쓰는 예절이 드러나는가","감사 인사가 있는가"]},"explanation":["면담 열기에서는 인사, 목적, 동의를 챙겨요.","질문하기에서는 준비한 질문을 하고 경청해요.","마무리에서는 알게 된 것을 확인하고 감사 인사를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_b#25','kor',6,2,'u2','','tb_g6_2_kor_u2_review_b','unit_review','K6-2-u2-C15',4,'mc','auto','「상담 교사, 마음의 길을 밝히는 사람들」이 면담 보고서의 특징을 잘 지킨 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":25,"concept":"K6-2-u2-C15","difficulty":4,"kind":"mc","stem":"「상담 교사, 마음의 길을 밝히는 사람들」이 면담 보고서의 특징을 잘 지킨 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"앞부분 목적·역할, 가운데 새롭게 안 사실 넷, 뒷부분 깨달은 점으로 나누어 썼다","correct":true},{"t":"녹음한 말을 처음부터 끝까지 한 글자도 빼지 않고 옮겨 썼다","mis":"K6-2-u2-X13"},{"t":"느낌만 길게 쓰고 면담으로 새롭게 안 사실은 쓰지 않았다","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 나이와 사는 곳 같은 개인 정보를 자세히 소개했다","mis":"K6-2-u2-X04"}],"explanation":["앞부분에는 목적·대상자·역할과 준비를 썼어요.","가운데 부분에는 새롭게 안 사실을 네 가지로 요약했어요.","뒷부분에는 깨달은 점과 달라진 생각을 썼어요."],"asset":{"type":"passage","lines":["(간추림) 면담은 한 시간 정도 했고, 주요 내용은 네 가지로 요약할 수 있다.","(간추림) 첫째, 되는 과정 — 심리학이나 상담학, 교육학 같은 것을 전공하고","(간추림)   자격증을 따서 교원 임용 시험을 치른다. 고민을 경청하는 자세도 필요하다.","(간추림) 둘째, 하는 일 — 학교생활의 고민을 들어 주고 해결 방법을 찾도록 돕는다.","(간추림) 셋째, 힘든 점 — 정신적으로 힘들 때가 많고, 인내심이 필요하다.","(간추림) 넷째, 보람과 전망 — 고민 해결을 도울 때 가장 보람 있고, 전망이 밝다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 가운데 부분 — 『국어』 104~105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#1','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C1',1,'sa','auto','면담의 특성을 정리한 문장이에요. 빈칸에 알맞은 낱말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#2','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C1',1,'sa','auto','『국어』 78쪽 만화에서 두 학생이 면담을 부탁드리기로 한 사람은 누구인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C1","difficulty":1,"kind":"sa","stem":"『국어』 78쪽 만화에서 두 학생이 면담을 부탁드리기로 한 사람은 누구인지 쓰세요.","answer":["학교 전담 경찰관","경찰관","학교 전담 경찰관님","경찰관님"],"explanation":["내일 학교에 학교 전담 경찰관이 교육을 하러 온다고 했어요.","두 학생은 경찰관님께 면담을 부탁드리기로 했어요.","그리고 질문을 미리 만들었어요."],"asset":{"type":"speech","turns":[{"who":"학생 1","text":"내일 학교에 학교 전담 경찰관이 와서 교육을 해 주신대."},{"who":"학생 2","text":"나도 들었어. 그런데 학교 전담 경찰관이 정확히 어떤 일을 하는지 궁금해."},{"who":"학생 1","text":"맞아. 나도 평소에 궁금한 점이 많았어. 그럼 학교 전담 경찰관님께 면담을 부탁드려 보자."},{"who":"학생 2","text":"좋아! 그렇다면 내일 경찰관님께 할 질문도 미리 만들어 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#3','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',1,'ox','auto','면담 보고서 쓰기는 면담 준비하기에서 하는 일이에요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"ox","stem":"면담 보고서 쓰기는 면담 준비하기에서 하는 일이에요.","answer":"X","reason_options":[{"t":"면담 보고서 쓰기는 면담을 마친 뒤 면담 정리하기에서 하는 일이기 때문에","correct":true},{"t":"보고서를 먼저 써 두어야 면담을 할 수 있기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["면담 정리하기에서는 내용 정리, 과정 성찰, 보고서 쓰기를 해요.","보고서는 면담을 마친 뒤에 써요.","그래서 X예요."],"asset":{"type":"passage","lines":["보기: 감사 · 자료 · 정리 · 질문 · 대상자","면담 준비하기 — 모둠 구성 · 목적 · 면담 (  ㉠  ) 정하기 · 방식 ·","   면담에 필요한 (  ㉡  ) 찾기 · 면담 (  ㉢  ) 만들기 · 역할 · 요청과 허락","면담 진행하기 — 면담 열기 · 질문하고 답변 듣기 · 결과 확인, (  ㉣  ) 인사","면담 정리하기 — 면담 내용 (  ㉤  )하기 · 과정 성찰하기 · 보고서 쓰기"],"numbered":false,"title":"면담의 각 절차에서 해야 할 일 — 『국어』 87쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#4','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C4',1,'ox','auto','「사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?」는 생각이나 느낌에 대한 질문이에요.',ARRAY['K6-2-u2-X08']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"ox","stem":"「사서에게 가장 필요한 능력은 무엇이라고 생각하시나요?」는 생각이나 느낌에 대한 질문이에요.","answer":"O","reason_options":[{"t":"사서가 어떻게 생각하는지를 묻는 질문이기 때문에","correct":true},{"t":"능력은 숫자로 셀 수 있는 사실이기 때문에","mis":"K6-2-u2-X08"}],"mis":"K6-2-u2-X08","explanation":["「생각하시나요?」라고 생각을 물었어요.","생각이나 느낌에 대한 질문이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#5','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C5',1,'mc','auto','「로봇 공학자와의 면담」에서 후속 질문은 무엇인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X06']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":1,"kind":"mc","stem":"「로봇 공학자와의 면담」에서 후속 질문은 무엇인가요?","options":[{"t":"「로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?」","correct":true},{"t":"「답변을 정확하게 정리하기 위해 녹음이나 녹화를 해도 괜찮을까요?」","mis":"K6-2-u2-X05"},{"t":"「로봇 공학자가 로봇을 만들 때 가장 먼저 해야 하는 일은 무엇인가요?」","mis":"K6-2-u2-X06"},{"t":"「로봇을 만들 때 기술뿐만 아니라 우리 생활에 어떤 영향을 줄지도 생각해야 한다는 점이 인상 깊었습니다.」","mis":"K6-2-u2-X05"}],"explanation":["로봇 공학자가 여러 번 시험한다고 대답했어요.","학생은 그 대답에 이어서 까닭을 물었어요.","앞선 대답과 이어진 질문이 후속 질문이에요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"로봇 공학자가 로봇을 만들 때 가장 먼저 해야 하는 일은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 로봇이 풀어야 할 문제부터 정한다. 사람을 도울지, 위험한 곳에 대신 갈지 정한 뒤 모양과 기능을 설계하고 부품을 고르고, 프로그램을 만들어 여러 번 시험한다."},{"who":"학생","text":"로봇을 여러 번 시험해야 하는 까닭은 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 시험하면서 오류를 찾아 고치고 성능을 높여 로봇이 더 정확하고 안전하게 움직이게 하려는 것이다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#6','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',1,'ox','auto','온라인 화상 회의로 하는 면담은 비대면 면담이에요.',ARRAY['K6-2-u2-X12']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"ox","stem":"온라인 화상 회의로 하는 면담은 비대면 면담이에요.","answer":"O","reason_options":[{"t":"면담 대상자를 직접 만나지 않고 진행하는 면담이기 때문에","correct":true},{"t":"화면으로 얼굴이 보이면 직접 만난 것과 같기 때문에","mis":"K6-2-u2-X12"}],"mis":"K6-2-u2-X12","explanation":["『국어』 83쪽 도움말에 나온 내용이에요.","화상 회의나 전자 우편은 직접 만나지 않고 하는 면담이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["면담은 대상자를 직접 만나 마주 보고 이야기하는 대면 면담과","온라인 화상 회의나 전자 우편을 이용하는 것처럼","면담 대상자를 직접 만나지 않고 진행하는 비대면 면담이 있어요."],"title":"『국어』 83쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#7','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',1,'ox','auto','면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리해요.',ARRAY['K6-2-u2-X15']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"ox","stem":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리해요.","answer":"O","reason_options":[{"t":"가운데 부분은 면담으로 새롭게 안 사실을 소개하는 곳이기 때문에","correct":true},{"t":"가운데 부분은 면담을 마친 뒤의 느낌을 쓰는 곳이기 때문에","mis":"K6-2-u2-X15"}],"mis":"K6-2-u2-X15","explanation":["가운데 부분은 면담 대상자의 답변이 중심이에요.","궁금했던 점과 알게 된 내용을 정리해요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"면담 보고서 앞부분에는 우리가 면담을 시작하며 세웠던 계획과 준비 상황을 요약해서 담았어."},{"who":"친구 2","text":"면담 보고서 가운데 부분에는 우리가 궁금했던 점을 면담 대상자가 알려 준 내용으로 정리했어."},{"who":"친구 3","text":"면담 보고서 뒷부분에는 면담을 마친 뒤 깨달은 점과 달라진 생각을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#8','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C11',1,'sa','auto','「진수의 신발에 흙이 묻었다.」에서 「흙이」를 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"sa","stem":"「진수의 신발에 흙이 묻었다.」에서 「흙이」를 소리 나는 대로 쓰세요.","answer":["흘기","[흘기]"],"explanation":["「흙」의 겹받침은 ㄺ이에요.","모음 「이」가 붙으면 ㄱ이 넘어가요.","그래서 [흘기]로 소리 나요."],"asset":{"type":"passage","lines":["● 닭이[달기] 새벽을 알리며 울었다.","● 진수의 신발에 흙이[흘기] 묻었다.","● 노력하는 사람의 삶은[살ː믄] 아름답다."],"numbered":false,"title":"기초 다지기 2 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#9','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C12',2,'mc','auto','「윤서네 모둠의 면담」에서 사서가 가장 보람을 느낀다고 한 때는 언제인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":9,"concept":"K6-2-u2-C12","difficulty":2,"kind":"mc","stem":"「윤서네 모둠의 면담」에서 사서가 가장 보람을 느낀다고 한 때는 언제인가요?","options":[{"t":"추천한 책이 도움이 됐다는 말을 들을 때","correct":true},{"t":"하루 동안 책을 빨리 정리했을 때","mis":"K6-2-u2-X13"},{"t":"일을 마치고 도서관 문을 닫을 때","mis":"K6-2-u2-X13"},{"t":"시험을 보고 사서 자격증을 땄을 때","mis":"K6-2-u2-X13"}],"explanation":["㉤은 보람을 느낀 순간을 묻는 질문이에요.","사서는 추천한 책이 도움이 되었다는 말을 들을 때라고 했어요.","생각이나 느낌에 대한 질문의 답이에요."],"asset":{"type":"passage","lines":["(간추림) ㉠ 대출·반납 돕기, 새 책 주문, 책 정리, 독서 행사나 프로그램 준비","(간추림) ㉡ 대학에서 문헌정보학 공부 → 사서 자격증 → 도서관 채용 절차","(간추림) ㉢ 소통 능력, 검색 능력, 꼼꼼함","(간추림) ㉤ 추천한 책이 도움이 됐다는 말을 들을 때","(간추림) ㉥ 책을 읽는 습관과 궁금한 것을 스스로 찾아보는 습관 기르기"],"numbered":false,"title":"「윤서네 모둠의 면담」 질문과 답변 정리 (듣기 자료 · 『국어』 86쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#10','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C13',2,'mc','auto','로봇 공학자가 앞으로 이루고 싶다고 한 목표는 무엇인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":10,"concept":"K6-2-u2-C13","difficulty":2,"kind":"mc","stem":"로봇 공학자가 앞으로 이루고 싶다고 한 목표는 무엇인가요?","options":[{"t":"아픈 사람·어르신을 돕거나 재난 현장에서 위험한 일을 대신하는 로봇 만들기","correct":true},{"t":"대회에서 이기려고 가장 빠르고 비싼 로봇 만들기","mis":"K6-2-u2-X13"},{"t":"사람 대신 학교에 가서 공부해 주는 로봇 만들기","mis":"K6-2-u2-X13"},{"t":"어려운 일이 많아 로봇 만드는 일을 그만두고 쉬기","mis":"K6-2-u2-X13"}],"explanation":["학생은 앞으로의 계획을 묻는 질문을 했어요.","로봇 공학자는 사람들에게 실제적인 도움을 주는 로봇을 말했어요.","아픈 사람·어르신·재난 현장을 예로 들었어요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"(간추림) 여러 번 고쳐 가며 로봇이 완성된다는 점이 흥미로웠다고 말한 뒤) 그렇다면 로봇 공학자가 된 뒤에 가장 보람 있었던 순간은 언제인가요?"},{"who":"로봇 공학자","text":"(간추림) 자기가 만든 로봇이 사람들에게 실제로 도움이 되었을 때 가장 큰 보람을 느꼈다."},{"who":"학생","text":"그렇군요. 로봇 공학자로서 앞으로 이루고 싶은 목표는 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 아픈 사람이나 어르신을 돕는 로봇, 재난 현장에서 위험한 일을 대신하는 로봇처럼 사람들에게 실제적인 도움을 주는 로봇을 만들고 싶다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#11','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C14',2,'mc','auto','민수가 「면담 보고서가 완성되면 다시 연락드려서 보여 드리고 싶습니다.」라고 한 것은 어느 단계에서 무엇을 한 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X06']::text[],false,'{"seq":11,"concept":"K6-2-u2-C14","difficulty":2,"kind":"mc","stem":"민수가 「면담 보고서가 완성되면 다시 연락드려서 보여 드리고 싶습니다.」라고 한 것은 어느 단계에서 무엇을 한 것인가요?","options":[{"t":"면담 마무리하기에서 감사 인사를 하며 결과를 나누겠다고 했다","correct":true},{"t":"면담 열기에서 녹음·녹화 동의를 구했다","mis":"K6-2-u2-X05"},{"t":"질문하기에서 후속 질문을 했다","mis":"K6-2-u2-X06"},{"t":"면담 준비하기에서 날짜와 장소 약속을 잡았다","mis":"K6-2-u2-X05"}],"explanation":["민수는 면담 결과를 확인한 뒤 이 말을 했어요.","허락해 주셔서 감사하다는 인사와 함께 했어요.","면담 마무리하기의 감사 인사예요."],"asset":{"type":"speech","turns":[{"who":"민수","text":"(간추림) 면담으로 상담 교사의 역할과 상담 교사가 되는 방법을 잘 알게 되었고, 상담 교사를 꿈꾸는 친구들에게 도움이 될 것 같다고 말했다."},{"who":"민수","text":"바쁘신 가운데 저희에게 면담을 허락해 주셔서 감사합니다. 면담 보고서가 완성되면 다시 연락드려서 보여 드리고 싶습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#12','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C15',2,'mc','auto','하늘 모둠은 상담 교사의 전망을 어떻게 소개했나요?',ARRAY['K6-2-u2-X13','K6-2-u2-X15']::text[],false,'{"seq":12,"concept":"K6-2-u2-C15","difficulty":2,"kind":"mc","stem":"하늘 모둠은 상담 교사의 전망을 어떻게 소개했나요?","options":[{"t":"정신 건강의 중요성이 점점 커지고 있어 앞으로 전망이 매우 밝다","correct":true},{"t":"상담 교사를 찾는 학교가 줄어들 것이다","mis":"K6-2-u2-X13"},{"t":"전망은 알 수 없어서 보고서에 쓰지 않았다","mis":"K6-2-u2-X15"},{"t":"응급 환자가 늘어 바빠질 것이다","mis":"K6-2-u2-X15"}],"explanation":["넷째로 소개한 내용은 보람과 전망이에요.","정신 건강이 점점 중요해지고 있다고 했어요.","그래서 전망이 매우 밝다고 했어요."],"asset":{"type":"passage","lines":["(간추림) 면담은 한 시간 정도 했고, 주요 내용은 네 가지로 요약할 수 있다.","(간추림) 첫째, 되는 과정 — 심리학이나 상담학, 교육학 같은 것을 전공하고","(간추림)   자격증을 따서 교원 임용 시험을 치른다. 고민을 경청하는 자세도 필요하다.","(간추림) 둘째, 하는 일 — 학교생활의 고민을 들어 주고 해결 방법을 찾도록 돕는다.","(간추림) 셋째, 힘든 점 — 정신적으로 힘들 때가 많고, 인내심이 필요하다.","(간추림) 넷째, 보람과 전망 — 고민 해결을 도울 때 가장 보람 있고, 전망이 밝다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 가운데 부분 — 『국어』 104~105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#13','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C6',2,'ox','auto','면담 대상자가 말하는 도중에 끼어들어 말하지 않아요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":13,"concept":"K6-2-u2-C6","difficulty":2,"kind":"ox","stem":"면담 대상자가 말하는 도중에 끼어들어 말하지 않아요.","answer":"O","reason_options":[{"t":"면담 대상자의 말을 끝까지 귀 기울여 듣는 것이 면담 예절이기 때문에","correct":true},{"t":"궁금한 것이 생기면 바로 끼어들어야 잊지 않기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["『국어』 111쪽 3번에서 정리한 내용이에요.","궁금한 점은 메모해 두었다가 대답이 끝난 뒤 물어요.","그래서 O예요."],"asset":{"type":"passage","lines":["보기: 면담 · 목적 · 면담 대상자","● (    ㉠    )은/는 특정 인물이나 주제의 정보를 수집하려고","   면담자와 면담 대상자가 주고받는 대화를 말한다.","● (    ㉡    )이/가 말하는 도중에 끼어들어 말하지 않는다.","● 면담 (    ㉢    )에서 벗어난 질문을 하지 않는다."],"numbered":false,"title":"공부한 내용 되돌아보기 — 『국어』 111쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#14','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',2,'blank','auto','『국어』 95쪽 「면담 예절 확인하기」의 문장이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#15','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C8',2,'blank','auto','면담 내용을 정리하는 방법이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#16','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C10',2,'ox','auto','「네가 궁금해 놀이」의 질문 카드에는 서로 묻고 답하기에 불편하거나 민감한 질문은 만들지 않아요.',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":16,"concept":"K6-2-u2-C10","difficulty":2,"kind":"ox","stem":"「네가 궁금해 놀이」의 질문 카드에는 서로 묻고 답하기에 불편하거나 민감한 질문은 만들지 않아요.","answer":"O","reason_options":[{"t":"궁금한 점을 물으면서도 다른 사람을 배려해야 하기 때문에","correct":true},{"t":"놀이에서는 곤란한 질문일수록 더 재미있기 때문에","mis":"K6-2-u2-X17"}],"mis":"K6-2-u2-X17","explanation":["질문 카드에는 궁금한 내용 여섯 가지를 문장으로 만들어요.","불편하거나 민감한 질문은 만들지 않도록 주의해요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 모둠 친구끼리 의논해 질문 카드에 궁금한 내용 여섯 가지를 문장으로 만든다.","   (서로 묻고 답하기에 불편하거나 민감한 질문은 만들지 않는다.)","② 모둠에서 한 사람을 정해 주사위를 던진다.","③ 주사위 번호의 질문을 읽고 대답한다. 한 번 나온 질문은 표시해 다시 묻지 않는다.","④ 다른 사람이 주사위를 던지고 질문에 답한다.","⑤ 질문 카드의 질문에 모두 대답할 때까지 놀이를 진행한다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 2 — 네가 궁금해 놀이 (질문 카드 · 주사위)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#17','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',3,'mc','auto','면담의 절차와 그 절차에서 할 일을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":17,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"면담의 절차와 그 절차에서 할 일을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"면담 정리하기 — 녹음·녹화하거나 메모한 내용을 모아 면담 내용 정리하기","correct":true},{"t":"면담 준비하기 — 면담을 마친 뒤 감사 인사하기","mis":"K6-2-u2-X05"},{"t":"면담 진행하기 — 면담 보고서 쓰고 친구들과 나누기","mis":"K6-2-u2-X05"},{"t":"면담 정리하기 — 면담 목적에 알맞은 질문 만들기","mis":"K6-2-u2-X05"}],"explanation":["질문 만들기는 준비하기에서 해요.","감사 인사는 진행하기의 마무리에서 해요.","녹음·녹화하거나 메모한 내용을 모아 정리하는 일은 정리하기에서 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#18','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',3,'sa','auto','보기의 ㉠~㉥ 가운데에서 「면담 마무리하기」에서 할 일의 기호를 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"K6-2-u2-C3","difficulty":3,"kind":"sa","stem":"보기의 ㉠~㉥ 가운데에서 「면담 마무리하기」에서 할 일의 기호를 쓰세요.","answer":["㉤","ㅁ"],"explanation":["면담 마무리하기에서는 결과를 확인하고 감사 인사를 해요.","㉤ 「면담을 마친 뒤 감사 인사하기」가 여기에 들어가요.","면담 열기는 ㉠·㉡, 질문하기는 ㉢·㉣·㉥이에요."],"asset":{"type":"passage","lines":["보기","㉠ 면담 목적 설명하기","㉡ 가벼운 인사말 나누기","㉢ 구체적인 사실에 대한 질문하기","㉣ 생각이나 느낌에 대한 질문하기","㉤ 면담을 마친 뒤 감사 인사하기","㉥ 앞으로의 계획이나 당부에 대한 질문하기"],"numbered":false,"title":"면담 진행하기에서 할 일 — 『국어』 111쪽 2번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#19','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C4',3,'mc','auto','민수네 모둠의 면담 목적(상담 교사가 되는 방법과 역할 알아보기)에 가장 잘 맞는 질문은 무엇인가요?',ARRAY['K6-2-u2-X02','K6-2-u2-X07','K6-2-u2-X04']::text[],false,'{"seq":19,"concept":"K6-2-u2-C4","difficulty":3,"kind":"mc","stem":"민수네 모둠의 면담 목적(상담 교사가 되는 방법과 역할 알아보기)에 가장 잘 맞는 질문은 무엇인가요?","options":[{"t":"「상담 교사는 학교에서 주로 어떤 일을 하나요?」","correct":true},{"t":"「상담실은 몇 층에 있나요?」","mis":"K6-2-u2-X02"},{"t":"「선생님은 어떤 음식을 좋아하시나요?」","mis":"K6-2-u2-X07"},{"t":"「선생님 댁에는 가족이 몇 명인가요?」","mis":"K6-2-u2-X04"}],"explanation":["목적은 되는 방법과 역할이에요.","학교에서 하는 일을 묻는 질문은 역할을 알게 해 줘요.","찾아보면 알 수 있는 것, 개인 정보는 묻지 않아요."],"asset":{"type":"passage","lines":["㉠ 상담 교사가 되려면 어떤 준비를 해야 하나요?","㉡ 상담 교사는 학교에서 주로 어떤 일을 하나요?","㉢ 상담 교사가 되고 난 뒤 가장 보람 있었던 일은 무엇인가요?","㉣ 상담 교사로서 학생들을 만날 때 가장 힘든 점은 무엇인가요?","㉤ 상담 교사로서 앞으로 꼭 하고 싶은 일은 무엇인가요?","㉥ 이 직업의 전망과 관련해 학생들에게 해 주실 말씀은 무엇인가요?"],"numbered":false,"title":"민수네 모둠의 질문하기 — 『국어』 100쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#20','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',3,'error','auto','친구들이 면담 과정을 돌아보며 쓴 글이에요. 성찰을 잘못한 것을 고르세요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":20,"concept":"K6-2-u2-C9","difficulty":3,"kind":"error","stem":"친구들이 면담 과정을 돌아보며 쓴 글이에요. 성찰을 잘못한 것을 고르세요.","options":[{"t":"「질문을 제대로 못 한 것은 원주 때문이다.」","correct":true,"mis_target":"K6-2-u2-X14"},{"t":"「나는 면담을 준비할 때 책과 인터넷으로 면담 대상자의 정보를 모았다.」","mis":"K6-2-u2-X14"},{"t":"「녹화하기 전에 먼저 동의를 구한 것은 잘한 점이다.」","mis":"K6-2-u2-X14"}],"explanation":["성찰은 한 사람의 잘잘못을 가리는 일이 아니에요.","자신과 모둠이 한 일을 절차에 따라 돌아봐요.","보완할 점은 다음에 실천할 약속으로 바꾸어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 면담을 준비할 때 책과 인터넷을 활용해서 면담 대상자의 정보를 모았어."},{"who":"친구 2","text":"나는 면담을 진행할 때 면담 대상자에게 먼저 동의를 구하고 녹화를 했어."},{"who":"친구 3","text":"면담 내용을 메모하고 녹화한 자료를 활용해서 면담 내용을 정리했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#21','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C14',3,'ox','auto','면담 목적과 맞기만 하면, 연락할 방법이 없는 먼 곳의 유명한 사람을 직접 만날 면담 대상자로 정하는 것이 가장 좋아요.',ARRAY['K6-2-u2-X20']::text[],false,'{"seq":21,"concept":"K6-2-u2-C14","difficulty":3,"kind":"ox","stem":"면담 목적과 맞기만 하면, 연락할 방법이 없는 먼 곳의 유명한 사람을 직접 만날 면담 대상자로 정하는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"실제로 연락할 수 있고 학생과 면담이 가능한 분이어야 면담을 할 수 있기 때문에","correct":true},{"t":"유명한 사람일수록 더 좋은 정보를 주기 때문에","mis":"K6-2-u2-X20"}],"mis":"K6-2-u2-X20","explanation":["면담 대상자는 목적에 맞아야 해요.","그리고 실제로 연락할 수 있고 면담이 가능한 분이어야 해요.","그래서 X예요."],"asset":{"type":"passage","lines":["면담 대상자를 정할 때에는 학생들과 면담이 가능한 분인지가 중요해요.","또 우리가 연락할 수 있는 주변 인물인지 생각해 봐요."],"title":"『국어』 97쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#22','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',3,'match','auto','면담의 절차와 매체 활용 방법을 바르게 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K6-2-u2-C7","difficulty":3,"kind":"match","stem":"면담의 절차와 매체 활용 방법을 바르게 이어 보세요.","pairs":[{"l":"면담 준비하기","r":"인터넷이나 책을 활용해 면담에 필요한 자료 찾기"},{"l":"면담 진행하기","r":"스마트폰으로 영상 통화를 하며 비대면 면담 진행하기"},{"l":"면담 정리하기","r":"녹음한 내용을 확인하며 중요한 내용 요약하기"}],"mis":"K6-2-u2-X12","explanation":["준비하기에서는 자료를 찾는 데 매체를 써요.","진행하기에서는 녹음기나 영상 통화를 써요.","정리하기에서는 녹음한 내용을 다시 확인해요."],"asset":{"type":"passage","lines":["면담 준비하기 — 주의할 점: 면담 목적과 관련 있는 정보만 검색하기","   매체 활용: 인터넷이나 책을 활용해 면담에 필요한 자료 찾기","면담 진행하기 — 주의할 점: 녹음·녹화할 때에는 먼저 면담 대상자의 동의 얻기","   매체 활용: 녹음기로 녹음하며 대면 면담, 영상 통화로 비대면 면담","면담 정리하기 — 주의할 점: 녹음·녹화한 자료는 퍼뜨리지 않고 보고서에만 쓰기","   매체 활용: 녹음한 내용을 확인하며 중요한 내용 요약하기"],"numbered":false,"title":"스스로 확인하기 — 『국어』 112쪽 (1) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#23','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C6',4,'essay','teacher','친구가 「그 일 하면 돈 많이 벌어요?」라는 질문을 만들었어요. 점검 기준에 비추어 무엇이 문제인지 쓰고, 면담 목적에 맞고 예의 바르며 명료한 질문으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u2-C6","difficulty":4,"kind":"essay","stem":"친구가 「그 일 하면 돈 많이 벌어요?」라는 질문을 만들었어요. 점검 기준에 비추어 무엇이 문제인지 쓰고, 면담 목적에 맞고 예의 바르며 명료한 질문으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 공개하기 어려운 개인 정보를 묻고 있어 면담 대상자가 곤란해할 수 있고, 예의를 갖춘 표현도 아니다. 고친 질문 — 「이 일을 하시면서 가장 보람을 느끼는 때는 언제인가요?」","scoring_points":["곤란한 질문·개인 정보·예의 없는 표현이라는 문제를 찾았는가","고친 질문이 면담 목적과 이어지는가","예의 바르고 명료한 표현으로 고쳤는가"]},"explanation":["면담 대상자가 곤란해할 질문이 없는지 살펴요.","개인 정보를 묻는 질문은 빼거나 고쳐요.","예의를 갖추어 분명하게 물어요."],"asset":{"type":"passage","lines":["면담 질문을 만들 때 면담 대상자가 곤란해할 만한 질문이나","공개하기 어려운 개인 정보에 대한 질문은 없는지 잘 살펴봐야 해요.","그리고 면담 목적에 알맞은 질문을 만들어야 해요."],"title":"『국어』 98쪽 도움말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#24','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C8',4,'essay','teacher','민수네 모둠이 정리한 면담 내용을 녹음·녹화·메모한 내용이라고 생각하고, 그 내용을 바탕으로 「면담으로 새롭게 안 사실」 두 가지와 「면담한 뒤의 소감」을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C8","difficulty":4,"kind":"essay","stem":"민수네 모둠이 정리한 면담 내용을 녹음·녹화·메모한 내용이라고 생각하고, 그 내용을 바탕으로 「면담으로 새롭게 안 사실」 두 가지와 「면담한 뒤의 소감」을 쓰세요.","answer_guide":{"answer":"예: 새롭게 안 사실 — 첫째, 상담 교사가 되려면 관련 공부를 하고 자격증을 따서 임용 시험에 합격해야 한다. 둘째, 상담 교사는 정신적으로 힘들 때가 많지만 학생의 고민 해결을 도울 때 가장 큰 보람을 느낀다. 소감 — 상담 교사에게는 공감 능력과 끈기가 필요하다는 것을 알게 되어 상담 선생님을 더 존중하게 되었다.","scoring_points":["새롭게 안 사실 두 가지를 면담 내용에 근거해 썼는가","면담 내용을 자신의 말로 짧게 간추렸는가","면담한 뒤의 소감을 썼는가"]},"explanation":["녹음·녹화·메모한 내용에서 중요한 것을 골라요.","들은 그대로 옮기지 말고 짧게 간추려요.","소감에는 달라진 생각을 담아요."],"asset":{"type":"passage","lines":["면담 열기 — 상담 교사가 되는 방법과 역할을 알아보려고 면담을 했다.","질문하기 — 첫째, 관련 공부를 하고 자격증을 따서 임용 시험에 합격해야 한다.","   둘째, 학생의 고민을 들어 주고 해결 방법을 찾도록 도우며 학교생활을 돕는다.","   셋째, 상담 교사로 일하며 정신적으로 힘들 때가 많다.","   넷째, 고민 해결에 도움을 줄 때 가장 큰 보람을 느끼며, 전망은 매우 밝다.","면담 마무리하기 — 공감 능력과 끈기가 필요한 직업임을 알았다."],"numbered":false,"title":"민수네 모둠이 정리한 면담 내용 — 『국어』 101쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_c#25','kor',6,2,'u2','','tb_g6_2_kor_u2_review_c','unit_review','K6-2-u2-C10',4,'essay','teacher','작품 속 인물 한 명을 정해 그 인물에게 할 질문 두 개를 만들고, 친구가 그 인물이 되어 대답할 때 근거로 삼을 작품 속 사건이나 행동을 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C10","difficulty":4,"kind":"essay","stem":"작품 속 인물 한 명을 정해 그 인물에게 할 질문 두 개를 만들고, 친구가 그 인물이 되어 대답할 때 근거로 삼을 작품 속 사건이나 행동을 함께 쓰세요.","answer_guide":{"answer":"예: 인물 — 흥부. 질문 1 — 「다친 제비를 보고 어떻게 했나요?」(근거: 흥부가 제비 다리를 정성스레 치료해 준 사건) 질문 2 — 「박에서 금은보화가 나왔을 때 어떤 마음이 들었나요?」(근거: 제비가 물어다 준 박씨에서 금은보화가 나와 부자가 된 사건)","scoring_points":["작품 속 인물을 정했는가","인물에게 할 질문 두 개를 만들었는가","대답의 근거가 될 작품 속 사건이나 행동을 썼는가"]},"explanation":["질문은 세 기준 가운데에서 골라 만들어요.","대답은 상상으로만 꾸미지 않아요.","작품 속 사건·대사·행동이 근거예요."],"asset":{"type":"passage","lines":["① 모둠 친구들과 작품 속 인물 떠올리기 (예: 이순신 장군 · 흥부 · 강아지똥)","② 작품 속 인물에게 궁금한 점을 떠올리고 질문 만들기","③ 모둠 친구 가운데 한 명이 작품 속 인물이 되어 면담하기","④ 소감 나누기"],"numbered":false,"title":"이런 활동도 있어요 — 작품 속 인물과 면담하기 (『국어』 108쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#1','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C1',1,'mc','auto','「면담을 진행하려면 면담 대상자를 정하고, 정보를 수집하고, 질문을 만드는 사전 (    )이/가 필요하다.」에서 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"「면담을 진행하려면 면담 대상자를 정하고, 정보를 수집하고, 질문을 만드는 사전 (    )이/가 필요하다.」에서 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"준비","correct":true},{"t":"예의","mis":"K6-2-u2-X05"},{"t":"정리","mis":"K6-2-u2-X05"},{"t":"성찰","mis":"K6-2-u2-X05"}],"explanation":["대상자 정하기, 정보 수집, 질문 만들기는 면담 전에 해요.","이것을 사전 준비라고 해요.","예의는 면담할 때 지키는 거예요."],"asset":{"type":"passage","lines":["보기: 예의 · 준비 · 정보","● 면담은 대화를 주고받는 과정에서 (    ㉠    )을/를 얻는다.","● 면담을 진행하려면 면담 대상자를 정하고, 정보를 수집하고,","   질문을 만드는 사전 (    ㉡    )이/가 필요하다.","● 면담할 때에는 (    ㉢    )을/를 지키는 것이 중요하다."],"numbered":false,"title":"면담의 특성 정리하기 — 『국어』 81쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#2','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C1',1,'ox','auto','신문 동아리 친구들은 면담을 마치고 감사 인사를 했어요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":2,"concept":"K6-2-u2-C1","difficulty":1,"kind":"ox","stem":"신문 동아리 친구들은 면담을 마치고 감사 인사를 했어요.","answer":"O","reason_options":[{"t":"만화 마지막에 「감사합니다.」라고 인사했기 때문에","correct":true},{"t":"질문이 끝나자 인사 없이 돌아갔기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["면담을 마칠 때에는 감사 인사를 해요.","신문 동아리 친구들도 「감사합니다.」라고 했어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"신문 동아리","text":"안녕하세요? ○○초등학교 신문 동아리입니다. 학교 신문에 유기 동물 보호와 관련한 기사를 싣고 싶습니다. 혹시 면담에 참여해 주실 수 있을까요?"},{"who":"보호 센터","text":"네, 다음 주 이 시간에 면담이 가능합니다."},{"who":"신문 동아리","text":"(일주일 뒤) 면담에 응해 주셔서 감사합니다. 미리 수집한 정보를 바탕으로 유기 동물 보호와 관련 있는 질문을 드리려고 합니다."},{"who":"신문 동아리","text":"유기 동물 보호 센터에서 하는 일은 무엇인가요?"},{"who":"신문 동아리","text":"(답을 듣고 나서) 감사합니다."},{"who":"보호 센터","text":"유기 동물 보호 센터에 관심을 가져 주어서 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#3','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',1,'mc','auto','「면담 목적 정하기」는 면담의 어느 절차에서 하는 일인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"「면담 목적 정하기」는 면담의 어느 절차에서 하는 일인가요?","options":[{"t":"면담 준비하기","correct":true},{"t":"면담 진행하기","mis":"K6-2-u2-X05"},{"t":"면담 정리하기","mis":"K6-2-u2-X05"},{"t":"면담 마무리하기","mis":"K6-2-u2-X05"}],"explanation":["면담 준비하기는 모둠 구성, 목적 정하기부터 시작해요.","목적을 정해야 대상자를 정할 수 있어요.","그래서 준비하기의 앞부분에 있어요."],"asset":{"type":"passage","lines":["① 면담 모둠 구성하기 → ② 면담 목적 정하기","③ 면담 대상자 정하기 → ④ 면담 방식 정하기","⑤ 면담에 필요한 자료 찾기 → ⑥ 면담 질문 만들기","⑦ 면담 역할 정하기 → ⑧ 면담을 요청하고 허락 구하기"],"numbered":false,"title":"윤서네 모둠이 면담을 준비하는 과정 — 『국어』 82~83쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#4','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C4',1,'sa','auto','면담 질문의 세 기준은 구체적인 사실에 대한 질문, 생각이나 느낌에 대한 질문, 앞으로의 (    )이나 당부에 대한 질문이에요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"sa","stem":"면담 질문의 세 기준은 구체적인 사실에 대한 질문, 생각이나 느낌에 대한 질문, 앞으로의 (    )이나 당부에 대한 질문이에요. 빈칸에 알맞은 말을 쓰세요.","answer":["계획"],"explanation":["질문은 세 기준으로 나누어 만들어요.","앞일을 묻는 질문은 계획이나 당부에 대한 질문이에요.","세 기준을 골고루 써야 정보가 풍부해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#5','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C5',1,'sa','auto','「후속 질문은 면담 대상자의 (    )을/를 듣고 더 자세히 알려고 이어서 하는 질문을 말해요.」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":1,"kind":"sa","stem":"「후속 질문은 면담 대상자의 (    )을/를 듣고 더 자세히 알려고 이어서 하는 질문을 말해요.」 빈칸에 알맞은 낱말을 쓰세요.","answer":["대답","답변","답"],"explanation":["후속 질문은 대답에서 시작해요.","대답을 끝까지 듣고 궁금한 점을 이어서 물어요.","그러면 대화가 자연스럽게 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#6','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',1,'mc','auto','면담 준비하기에서 매체를 활용하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X11']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"면담 준비하기에서 매체를 활용하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"인터넷이나 책에서 면담에 필요한 자료를 찾는다","correct":true},{"t":"녹음한 내용을 다시 듣고 간추린다","mis":"K6-2-u2-X12"},{"t":"녹화한 영상을 누리집에 올린다","mis":"K6-2-u2-X11"},{"t":"영상 통화로 질문을 한다","mis":"K6-2-u2-X12"}],"explanation":["준비할 때는 인터넷이나 책으로 자료를 찾아요.","진행할 때는 녹음기나 영상 통화를 써요.","정리할 때는 녹음한 내용을 다시 들으며 간추려요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인터넷이나 책에서 면담에 필요한 자료를 찾아 면담을 준비할 수 있어."},{"who":"친구 2","text":"녹음기로 면담 내용을 녹음하며 대면 면담을 진행할 수 있어. 스마트폰으로 영상 통화를 하며 비대면 면담도 할 수 있어."},{"who":"친구 3","text":"그리고 녹음한 내용을 다시 듣고 중요한 내용을 간추리면서 면담 내용을 정리할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#7','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',1,'sa','auto','자신의 면담 과정을 성찰할 때 정리하는 세 가지는 잘한 점, (    ), 더 알고 싶은 점이에요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"sa","stem":"자신의 면담 과정을 성찰할 때 정리하는 세 가지는 잘한 점, (    ), 더 알고 싶은 점이에요. 빈칸에 알맞은 말을 쓰세요.","answer":["보완할 점","보완할점"],"explanation":["잘한 점은 계속 이어 갈 점이에요.","보완할 점은 다음에 고칠 점이에요.","더 알고 싶은 점은 다음 질문이 돼요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 면담 목적에 맞는 질문을 잘 만들었다.","보완할 점 — 면담을 마무리하고 난 뒤에 면담 대상자에게 감사 인사를","   제대로 못 했다.","더 알고 싶은 점 — 상담 교사가 꿈인 친구들에게 도움이 되는 책이 무엇인지 궁금하다."],"numbered":false,"title":"자신의 면담 과정 정리 — 『국어』 102쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#8','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C11',1,'ox','auto','「닭」은 낱말 하나로 발음할 때 [닥]으로 소리 나요.',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"ox","stem":"「닭」은 낱말 하나로 발음할 때 [닥]으로 소리 나요.","answer":"O","reason_options":[{"t":"겹받침은 낱말 하나로 발음할 때 대부분 하나만 소리 나기 때문에","correct":true},{"t":"겹받침은 언제나 두 받침이 모두 소리 나기 때문에","mis":"K6-2-u2-X18"}],"mis":"K6-2-u2-X18","explanation":["겹받침은 대부분 하나만 소리 나요.","닭은 [닥], 값은 [갑]으로 소리 나요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#9','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C12',2,'mc','auto','사서는 사서가 되고 싶은 학생들에게 어떤 말을 해 주었나요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":9,"concept":"K6-2-u2-C12","difficulty":2,"kind":"mc","stem":"사서는 사서가 되고 싶은 학생들에게 어떤 말을 해 주었나요?","options":[{"t":"책 읽는 습관과 궁금한 것을 스스로 찾아보는 습관을 길러 보라","correct":true},{"t":"책은 도서관에서 빌리지 말고 꼭 사서 읽으라","mis":"K6-2-u2-X13"},{"t":"도서관에는 사람이 많으니 자주 오지 말라","mis":"K6-2-u2-X13"},{"t":"사서는 일이 많고 힘드니 다른 일을 하라","mis":"K6-2-u2-X13"}],"explanation":["㉥은 앞으로의 당부를 묻는 질문이에요.","사서는 두 가지 습관을 길러 보라고 했어요.","책 읽는 습관과 스스로 찾아보는 습관이에요."],"asset":{"type":"passage","lines":["(간추림) ㉠ 대출·반납 돕기, 새 책 주문, 책 정리, 독서 행사나 프로그램 준비","(간추림) ㉡ 대학에서 문헌정보학 공부 → 사서 자격증 → 도서관 채용 절차","(간추림) ㉢ 소통 능력, 검색 능력, 꼼꼼함","(간추림) ㉤ 추천한 책이 도움이 됐다는 말을 들을 때","(간추림) ㉥ 책을 읽는 습관과 궁금한 것을 스스로 찾아보는 습관 기르기"],"numbered":false,"title":"「윤서네 모둠의 면담」 질문과 답변 정리 (듣기 자료 · 『국어』 86쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#10','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C13',2,'mc','auto','로봇 공학자가 가장 큰 보람을 느낀 순간은 언제였나요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":10,"concept":"K6-2-u2-C13","difficulty":2,"kind":"mc","stem":"로봇 공학자가 가장 큰 보람을 느낀 순간은 언제였나요?","options":[{"t":"자기가 만든 로봇이 사람들에게 실제로 도움이 되었을 때","correct":true},{"t":"로봇 대회에 나가 일 등 상을 받았을 때","mis":"K6-2-u2-X13"},{"t":"비싼 부품으로 로봇을 처음 완성했을 때","mis":"K6-2-u2-X13"},{"t":"학생들과 면담을 마치고 인사를 나눴을 때","mis":"K6-2-u2-X13"}],"explanation":["학생은 생각이나 느낌을 묻는 질문을 했어요.","로봇 공학자는 로봇이 실제로 도움이 되었을 때라고 했어요.","여러 번 고친 끝에 제대로 움직이면 고생이 사라진다고 했어요."],"asset":{"type":"speech","turns":[{"who":"학생","text":"(간추림) 여러 번 고쳐 가며 로봇이 완성된다는 점이 흥미로웠다고 말한 뒤) 그렇다면 로봇 공학자가 된 뒤에 가장 보람 있었던 순간은 언제인가요?"},{"who":"로봇 공학자","text":"(간추림) 자기가 만든 로봇이 사람들에게 실제로 도움이 되었을 때 가장 큰 보람을 느꼈다."},{"who":"학생","text":"그렇군요. 로봇 공학자로서 앞으로 이루고 싶은 목표는 무엇인가요?"},{"who":"로봇 공학자","text":"(간추림) 아픈 사람이나 어르신을 돕는 로봇, 재난 현장에서 위험한 일을 대신하는 로봇처럼 사람들에게 실제적인 도움을 주는 로봇을 만들고 싶다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#11','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C14',2,'mc','auto','민수네 모둠의 질문 ㉢ 「상담 교사가 되고 난 뒤 가장 보람 있었던 일은 무엇인가요?」는 어떤 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":11,"concept":"K6-2-u2-C14","difficulty":2,"kind":"mc","stem":"민수네 모둠의 질문 ㉢ 「상담 교사가 되고 난 뒤 가장 보람 있었던 일은 무엇인가요?」는 어떤 질문인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적에 맞지 않는 질문","mis":"K6-2-u2-X07"}],"explanation":["보람은 상담 선생님이 느낀 마음이에요.","그래서 생각이나 느낌에 대한 질문이에요.","㉢·㉣이 여기에 들어가요."],"asset":{"type":"passage","lines":["㉠ 상담 교사가 되려면 어떤 준비를 해야 하나요?","㉡ 상담 교사는 학교에서 주로 어떤 일을 하나요?","㉢ 상담 교사가 되고 난 뒤 가장 보람 있었던 일은 무엇인가요?","㉣ 상담 교사로서 학생들을 만날 때 가장 힘든 점은 무엇인가요?","㉤ 상담 교사로서 앞으로 꼭 하고 싶은 일은 무엇인가요?","㉥ 이 직업의 전망과 관련해 학생들에게 해 주실 말씀은 무엇인가요?"],"numbered":false,"title":"민수네 모둠의 질문하기 — 『국어』 100쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#12','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C15',2,'mc','auto','하늘 모둠이 면담을 마친 뒤 깨달은 점은 무엇인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X15']::text[],false,'{"seq":12,"concept":"K6-2-u2-C15","difficulty":2,"kind":"mc","stem":"하늘 모둠이 면담을 마친 뒤 깨달은 점은 무엇인가요?","options":[{"t":"전문적인 지식뿐만 아니라 공감 능력과 끈기가 필요하다","correct":true},{"t":"상담 교사는 아무 준비 없이 마음만 있으면 될 수 있다","mis":"K6-2-u2-X13"},{"t":"상담 교사는 힘든 점이 하나도 없다","mis":"K6-2-u2-X13"},{"t":"면담은 한 시간 정도 걸렸고 주요 내용은 넷이었다","mis":"K6-2-u2-X15"}],"explanation":["뒷부분에는 깨달은 점과 달라진 생각이 담겨요.","공감 능력과 끈기가 필요하다는 것을 배웠어요.","면담 시간은 가운데 부분 첫머리에 나와요."],"asset":{"type":"passage","lines":["(간추림) 면담을 하며 상담 교사라는 직업을 더 자세히 알았다.","(간추림) 전문적인 지식뿐만 아니라 공감 능력과 끈기가 필요하다는 것도 배웠다.","(간추림) 상담 교사의 역할을 더욱 존중하게 되었고, 상담 분야에 더 관심이 생겼다."],"numbered":false,"title":"「상담 교사, 마음의 길을 밝히는 사람들」 뒷부분 — 『국어』 105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#13','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',2,'error','auto','면담 예절을 이야기했어요. 잘못된 말을 고르세요.',ARRAY['K6-2-u2-X10','K6-2-u2-X07']::text[],false,'{"seq":13,"concept":"K6-2-u2-C6","difficulty":2,"kind":"error","stem":"면담 예절을 이야기했어요. 잘못된 말을 고르세요.","options":[{"t":"「대답이 길어지면 중간에 끊고 다음 질문으로 넘어가는 것이 좋아.」","correct":true,"mis_target":"K6-2-u2-X10"},{"t":"「처음에 인사를 바르게 하고 면담 목적을 분명하게 전달해야 해.」","mis":"K6-2-u2-X07"},{"t":"「면담이 끝난 뒤에는 감사 인사를 해야 해.」","mis":"K6-2-u2-X10"}],"explanation":["상대의 말을 끝까지 잘 들어야 해요.","처음에는 인사와 목적, 끝에는 감사 인사를 해요.","말을 끊으면 상대가 생각의 흐름을 잃어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#14','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',2,'mc','auto','인터넷이나 책에서 면담에 필요한 자료를 찾을 때 살펴봐야 할 것은 무엇인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":14,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"인터넷이나 책에서 면담에 필요한 자료를 찾을 때 살펴봐야 할 것은 무엇인가요?","options":[{"t":"면담 목적에 알맞은 자료인지","correct":true},{"t":"사진이 많은 자료인지","mis":"K6-2-u2-X09"},{"t":"가장 먼저 검색된 자료인지","mis":"K6-2-u2-X09"},{"t":"글이 가장 긴 자료인지","mis":"K6-2-u2-X09"}],"explanation":["『국어』 95쪽 「면담 예절 확인하기」의 내용이에요.","자료는 면담 목적에 알맞은지 살펴봐요.","믿을 만한 곳에서 얻었는지도 확인해요."],"asset":{"type":"passage","lines":["보기: 목적 · 자료 · 녹음·녹화","● 인터넷이나 책에서 면담에 필요한 (    ㉠    )을/를 찾을 때에는","   면담 (    ㉡    )에 알맞은지 살펴봐야 해.","● 면담 내용을 (    ㉢    )한 자료는 면담 보고서 작성에만 활용해야 해."],"numbered":false,"title":"면담 예절 확인하기 — 『국어』 95쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#15','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C8',2,'ox','auto','면담 내용을 정리할 때에는 들은 말을 하나도 빼지 않고 그대로 옮겨 적어요.',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":15,"concept":"K6-2-u2-C8","difficulty":2,"kind":"ox","stem":"면담 내용을 정리할 때에는 들은 말을 하나도 빼지 않고 그대로 옮겨 적어요.","answer":"X","reason_options":[{"t":"중요한 내용을 골라 자신의 말로 짧게 간추려야 하기 때문에","correct":true},{"t":"한 글자라도 빼면 면담 대상자에게 예의가 없기 때문에","mis":"K6-2-u2-X13"}],"mis":"K6-2-u2-X13","explanation":["정리는 들은 것을 통째로 옮기는 일이 아니에요.","중요한 내용이 드러나게 자신의 말로 다시 써요.","그래서 X예요."],"asset":{"type":"passage","lines":["보기: 이해 · 불필요한 · 중요한 · 짧게","● 면담 내용을 (    ㉠    ) 간추린다.","● (    ㉡    ) 내용은 삭제하고 (    ㉢    ) 내용만 간추린다.","● 면담에서 중요한 내용을 (    ㉣    )할 수 있게 간추린다."],"numbered":false,"title":"면담 내용을 정리하는 방법 — 『국어』 101쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#16','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',2,'mc','auto','모둠 친구가 작품 속 인물이 되어 대답할 때 근거로 삼아야 하는 것은 무엇인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":16,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"모둠 친구가 작품 속 인물이 되어 대답할 때 근거로 삼아야 하는 것은 무엇인가요?","options":[{"t":"작품 속 사건이나 대사, 행동","correct":true},{"t":"대답하는 친구의 실제 경험","mis":"K6-2-u2-X16"},{"t":"인물에 대해 떠오르는 대로 지어낸 이야기","mis":"K6-2-u2-X16"},{"t":"듣는 친구들이 바라는 대답","mis":"K6-2-u2-X16"}],"explanation":["작품 속 인물과의 면담은 작품을 더 깊이 이해하려는 활동이에요.","대답은 작품 속 사건·대사·행동에 근거해요.","상상으로만 꾸미지 않아요."],"asset":{"type":"passage","lines":["① 모둠 친구들과 작품 속 인물 떠올리기 (예: 이순신 장군 · 흥부 · 강아지똥)","② 작품 속 인물에게 궁금한 점을 떠올리고 질문 만들기","③ 모둠 친구 가운데 한 명이 작품 속 인물이 되어 면담하기","④ 소감 나누기"],"numbered":false,"title":"이런 활동도 있어요 — 작품 속 인물과 면담하기 (『국어』 108쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#17','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',3,'mc','auto','면담의 절차마다 지켜야 할 예절을 짝 지었어요. 바르게 짝 지은 것은 무엇인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X10','K6-2-u2-X11']::text[],false,'{"seq":17,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"면담의 절차마다 지켜야 할 예절을 짝 지었어요. 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"면담 진행하기 — 면담 대상자의 답변을 경청한다","correct":true},{"t":"면담 준비하기 — 면담 대상자에게 알리지 않고 질문을 정한다","mis":"K6-2-u2-X03"},{"t":"면담 진행하기 — 대답이 길면 끊고 다음 질문을 한다","mis":"K6-2-u2-X10"},{"t":"면담 정리하기 — 녹화 영상을 누리집에 올려 감사를 표현한다","mis":"K6-2-u2-X11"}],"explanation":["준비하기에서는 예의를 갖추어 요청하고 불편한 질문이 없는지 점검해요.","진행하기에서는 답변을 경청해요.","정리하기에서는 감사한 마음을 표현하되 자료는 퍼뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#18','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',3,'error','auto','친구들이 보기의 할 일을 면담 진행하기의 단계로 나누었어요. 잘못 나눈 것을 고르세요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":18,"concept":"K6-2-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 보기의 할 일을 면담 진행하기의 단계로 나누었어요. 잘못 나눈 것을 고르세요.","options":[{"t":"면담 열기 — ㉠, ㉤","correct":true,"mis_target":"K6-2-u2-X05"},{"t":"질문하기 — ㉢, ㉣, ㉥","mis":"K6-2-u2-X05"},{"t":"면담 마무리하기 — ㉤","mis":"K6-2-u2-X05"}],"explanation":["㉤ 감사 인사는 면담을 마친 뒤에 해요.","면담 열기에는 ㉠·㉡이 들어가요.","단계마다 할 일을 바르게 나누어요."],"asset":{"type":"passage","lines":["보기","㉠ 면담 목적 설명하기","㉡ 가벼운 인사말 나누기","㉢ 구체적인 사실에 대한 질문하기","㉣ 생각이나 느낌에 대한 질문하기","㉤ 면담을 마친 뒤 감사 인사하기","㉥ 앞으로의 계획이나 당부에 대한 질문하기"],"numbered":false,"title":"면담 진행하기에서 할 일 — 『국어』 111쪽 2번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#19','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',3,'ox','auto','면담에서는 면담 목적에서 벗어난 질문을 하지 않아요.',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":19,"concept":"K6-2-u2-C6","difficulty":3,"kind":"ox","stem":"면담에서는 면담 목적에서 벗어난 질문을 하지 않아요.","answer":"O","reason_options":[{"t":"질문에 따라 대화의 방향과 수집하는 정보가 달라지기 때문에","correct":true},{"t":"목적과 상관없는 질문을 해야 분위기가 좋아지기 때문에","mis":"K6-2-u2-X07"}],"mis":"K6-2-u2-X07","explanation":["『국어』 111쪽 3번에서 정리한 내용이에요.","목적에서 벗어난 질문은 필요한 정보를 얻지 못하게 해요.","그래서 O예요."],"asset":{"type":"passage","lines":["보기: 면담 · 목적 · 면담 대상자","● (    ㉠    )은/는 특정 인물이나 주제의 정보를 수집하려고","   면담자와 면담 대상자가 주고받는 대화를 말한다.","● (    ㉡    )이/가 말하는 도중에 끼어들어 말하지 않는다.","● 면담 (    ㉢    )에서 벗어난 질문을 하지 않는다."],"numbered":false,"title":"공부한 내용 되돌아보기 — 『국어』 111쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#20','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',3,'mc','auto','면담 과정을 돌아보며 「더 알고 싶은 점」으로 알맞게 쓴 것은 무엇인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X04']::text[],false,'{"seq":20,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"면담 과정을 돌아보며 「더 알고 싶은 점」으로 알맞게 쓴 것은 무엇인가요?","options":[{"t":"「상담 교사가 꿈인 친구들에게 도움이 되는 책이 무엇인지 궁금하다.」","correct":true},{"t":"「면담 대상자의 옷이 어디에서 산 것인지 궁금하다.」","mis":"K6-2-u2-X14"},{"t":"「면담 대상자가 몇 살인지 궁금하다.」","mis":"K6-2-u2-X04"},{"t":"「면담이 언제 끝나는지 궁금했다.」","mis":"K6-2-u2-X14"}],"explanation":["더 알고 싶은 점은 면담 목적과 이어진 궁금증이에요.","다음 면담이나 자료 찾기로 이어질 수 있어요.","개인 정보나 겉모습은 알고 싶은 점이 아니에요."],"asset":{"type":"passage","lines":["잘한 점 — 면담을 준비할 때 면담 목적에 맞는 질문을 잘 만들었다.","보완할 점 — 면담을 마무리하고 난 뒤에 면담 대상자에게 감사 인사를","   제대로 못 했다.","더 알고 싶은 점 — 상담 교사가 꿈인 친구들에게 도움이 되는 책이 무엇인지 궁금하다."],"numbered":false,"title":"자신의 면담 과정 정리 — 『국어』 102쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#21','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C14',3,'mc','auto','민수네 모둠이 면담 대상자를 정한 까닭으로 쓴 것은 무엇인가요?',ARRAY['K6-2-u2-X20','K6-2-u2-X12','K6-2-u2-X04']::text[],false,'{"seq":21,"concept":"K6-2-u2-C14","difficulty":3,"kind":"mc","stem":"민수네 모둠이 면담 대상자를 정한 까닭으로 쓴 것은 무엇인가요?","options":[{"t":"평소에 우리 학교 학생들을 친절하게 상담해 주시기 때문이다","correct":true},{"t":"가장 유명한 상담 선생님이기 때문이다","mis":"K6-2-u2-X20"},{"t":"면담 방식을 정하지 않아도 되기 때문이다","mis":"K6-2-u2-X12"},{"t":"상담 선생님의 가족을 알고 있기 때문이다","mis":"K6-2-u2-X04"}],"explanation":["민수네 모둠은 우리 학교 박○○ 상담 선생님을 골랐어요.","평소 학생들을 친절하게 상담해 주시는 분이에요.","연락할 수 있는 주변 인물이라는 점도 알맞아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리 학교 학생들을 상담해 주시는 박○○ 상담 선생님은 어떨까? 늘 친절하고 따뜻하게 우리 이야기를 들어 주시잖아."},{"who":"친구 2","text":"(간추림) 면담 방식은 직접 만나는 대면 면담으로 정하고, 박○○ 상담 선생님께 연락드려 면담을 요청하자고 했다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#22','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',3,'mc','auto','영상 통화로 비대면 면담을 하려는 모둠에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X21','K6-2-u2-X11']::text[],false,'{"seq":22,"concept":"K6-2-u2-C7","difficulty":3,"kind":"mc","stem":"영상 통화로 비대면 면담을 하려는 모둠에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「기기 연결을 미리 확인하고, 녹화하기 전에 면담 대상자의 동의를 얻어야 해.」","correct":true},{"t":"「얼굴을 마주하지 않으니 인사는 생략해도 돼.」","mis":"K6-2-u2-X21"},{"t":"「비대면이니 질문은 준비하지 않아도 돼.」","mis":"K6-2-u2-X21"},{"t":"「화면을 녹화한 영상은 누리집에 올려도 돼.」","mis":"K6-2-u2-X11"}],"explanation":["비대면 면담도 면담 대상자를 만나는 자리예요.","기기 연결과 카메라, 마이크를 점검해요.","녹화는 동의를 얻고, 자료는 퍼뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#23','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',4,'mc','auto','수의사를 면담하려고 만든 질문 가운데 세 가지 점검 기준(목적에 맞음 · 예의를 갖춤 · 명료함)을 모두 만족하는 질문은 무엇인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X04','K6-2-u2-X07']::text[],false,'{"seq":23,"concept":"K6-2-u2-C6","difficulty":4,"kind":"mc","stem":"수의사를 면담하려고 만든 질문 가운데 세 가지 점검 기준(목적에 맞음 · 예의를 갖춤 · 명료함)을 모두 만족하는 질문은 무엇인가요?","options":[{"t":"「수의사가 되기 위해 어떤 공부를 하셨나요?」","correct":true},{"t":"「그거 하려면 뭐 해야 돼요?」","mis":"K6-2-u2-X10"},{"t":"「수의사 선생님은 몇 살이세요?」","mis":"K6-2-u2-X04"},{"t":"「좋아하는 음식은 무엇인가요?」","mis":"K6-2-u2-X07"}],"explanation":["목적은 「내 진로를 더 깊이 이해하려고」예요.","「그거」 같은 말은 명료하지 않고 예의도 부족해요.","나이와 좋아하는 음식은 목적과 멀어요."],"asset":{"type":"passage","lines":["● 면담 목적에 맞게 질문을 만들었나요?","● 면담 대상자에게 예의를 갖추어 표현했나요?","● 면담 대상자가 이해할 수 있는 명료한 표현을 사용했나요?"],"numbered":false,"title":"자신이 만든 질문 스스로 확인하기 — 『국어』 93쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#24','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',4,'mc','auto','영상 통화로 미래의 친구와 면담을 시작할 때 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X21','K6-2-u2-X11']::text[],false,'{"seq":24,"concept":"K6-2-u2-C7","difficulty":4,"kind":"mc","stem":"영상 통화로 미래의 친구와 면담을 시작할 때 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「안녕? 면담에 응해 줘서 고마워. 네가 하는 일을 알고 싶어. 정리하려고 녹화해도 괜찮을까?」","correct":true},{"t":"「화면으로 하니까 인사는 넘어가고 바로 질문부터 할게.」","mis":"K6-2-u2-X21"},{"t":"「녹화는 벌써 시작했으니까 신경 쓰지 말고 그냥 대답해 줘.」","mis":"K6-2-u2-X11"},{"t":"「오늘 면담 내용은 끝나고 바로 누리집에 올려서 모두 보게 할게.」","mis":"K6-2-u2-X11"}],"explanation":["비대면 면담도 인사와 목적 설명으로 시작해요.","녹화는 먼저 동의를 얻어요.","녹화한 자료는 보고서에만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u2_review_d#25','kor',6,2,'u2','','tb_g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',4,'mc','auto','『국어』 103쪽 (4)의 항목으로 자신과 모둠을 확인했어요. 「예의를 지키며 면담 대상자의 답변을 경청했나요?」에 ●(보통임)을 준 모둠이 다음 면담에서 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X10']::text[],false,'{"seq":25,"concept":"K6-2-u2-C9","difficulty":4,"kind":"mc","stem":"『국어』 103쪽 (4)의 항목으로 자신과 모둠을 확인했어요. 「예의를 지키며 면담 대상자의 답변을 경청했나요?」에 ●(보통임)을 준 모둠이 다음 면담에서 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"끼어들지 않고 끝까지 듣고, 궁금한 점은 메모했다가 대답이 끝난 뒤 묻는다","correct":true},{"t":"다음 면담에서는 확인표를 쓰지 않고 넘어간다","mis":"K6-2-u2-X14"},{"t":"경청을 못 한 친구를 찾아 보고서에 이름을 적는다","mis":"K6-2-u2-X14"},{"t":"질문을 더 많이, 더 빨리 해서 시간을 채운다","mis":"K6-2-u2-X10"}],"explanation":["확인표는 다음에 무엇을 할지 정하려고 써요.","경청이 부족했다면 끝까지 듣는 약속을 해요.","궁금한 점은 메모했다가 대답이 끝난 뒤 물어요."],"asset":{"type":"passage","lines":["● 면담 절차에 따라 자신이 맡은 역할을 잘 실천했나요?","● 예의를 지키며 면담 대상자의 답변을 경청했나요?","● 면담 과정에서 매체를 고려해 면담 목적에 맞는 정보를 수집하고 정리했나요?","매우 잘함: ●●● · 잘함: ●● · 보통임: ●"],"numbered":false,"title":"면담할 때 자신과 모둠의 태도와 실천 정도 확인하기 — 『국어』 103쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
